"use client";

import React, { createContext, useContext, useState, useCallback, useEffect, useRef, useMemo } from "react";
import { NavItem, defaultNavItems } from "@/lib/constants";
import { useAuth } from "@/context/AuthContext";
import { CONFIG, THEME_CLASS_NAMES, type Theme } from "@/lib/config";
import { api } from "@/lib/api-client";

type ThemeMode = "dark" | "light";
type ThemeStyle = Theme;
type NavigationMode = "top" | "side";
type TrainingMode = "simplified" | "detailed";

interface AppState {
  navItems: NavItem[];
  dualPageView: boolean;
  panelPosition: "left" | "top";
  currentPage: string;
  collapsed: boolean;
  isMobile: boolean;
  theme: ThemeMode;
  themeStyle: ThemeStyle;
  navigationMode: NavigationMode;
  topPanelExpanded: boolean;
  trainingMode: TrainingMode;
  mobileSidebarOpen: boolean;
}

interface AppContextType extends AppState {
  setCurrentPage: (page: string) => void;
  toggleDualPage: () => void;
  toggleNavVisibility: (id: string) => void;
  toggleNavPin: (id: string) => void;
  reorderNavItems: (newOrder: NavItem[]) => void;
  setCollapsed: (collapsed: boolean) => void;
  getSortedNavItems: () => NavItem[];
  setTheme: (theme: ThemeMode) => void;
  toggleTheme: () => void;
  setThemeStyle: (style: ThemeStyle) => void;
  setNavigationMode: (mode: NavigationMode) => void;
  setTopPanelExpanded: (expanded: boolean) => void;
  setTrainingMode: (mode: TrainingMode) => void;
  mobileSidebarOpen: boolean;
  setMobileSidebarOpen: (open: boolean) => void;
  registerDrawerClose: (closeFn: (() => void) | null) => void;
  activeDrawerClose: (() => void) | null;
}

const AppContext = createContext<AppContextType | null>(null);
const IsMobileContext = createContext(false);
const SortedNavItemsContext = createContext<NavItem[]>(defaultNavItems.filter((item) => item.visible));

export function AppProvider({ children }: { children: React.ReactNode }) {
  const { user } = useAuth();
  const [navItems, setNavItems] = useState<NavItem[]>(defaultNavItems);
  const [dualPageView, setDualPageView] = useState(false);
  const [panelPosition, setPanelPosition] = useState<"left" | "top">("left");
  const [currentPage, setCurrentPage] = useState("dashboard");
  const [collapsed, setCollapsed] = useState(false);
  const [isMobile, setIsMobile] = useState(false);
  const [theme, setThemeState] = useState<ThemeMode>("dark");
  const [themeStyle, setThemeStyleState] = useState<ThemeStyle>("discord");
  const [navigationMode, setNavigationModeState] = useState<NavigationMode>("side");
  const [topPanelExpanded, setTopPanelExpandedState] = useState(true);
  const [trainingMode, setTrainingModeState] = useState<TrainingMode>("simplified");
  const [mobileSidebarOpen, setMobileSidebarOpen] = useState(false);
  const [activeDrawerClose, setActiveDrawerClose] = useState<(() => void) | null>(null);
  const [remotePrefsReady, setRemotePrefsReady] = useState(false);
  const syncedUserIdRef = useRef<string | null>(null);

  const registerDrawerClose = useCallback((closeFn: (() => void) | null) => {
    setActiveDrawerClose(() => closeFn);
  }, []);

  // Load saved state from localStorage
  /* eslint-disable react-hooks/set-state-in-effect -- hydration from localStorage on mount */
  useEffect(() => {
    try {
      const saved = localStorage.getItem("cultivation-nav-state");
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed.navItems && Array.isArray(parsed.navItems)) {
          // Merge saved nav items with defaults: preserve user customizations
          // (order, visibility, pinned) but always use paths/labels/icons from
          // defaultNavItems so corrections propagate to returning users.
          const defaultMap = new Map(defaultNavItems.map(item => [item.id, item]));
          const mergedItems: NavItem[] = parsed.navItems
            .filter((saved: NavItem) => defaultMap.has(saved.id))
            .map((saved: NavItem) => {
              const def = defaultMap.get(saved.id)!;
              return {
                ...def,
                // Preserve user-customisable fields only
                pinned: saved.pinned ?? def.pinned,
                visible: saved.visible ?? def.visible,
              };
            });
          // Append any new default items not present in saved state
          for (const def of defaultNavItems) {
            if (!mergedItems.find(m => m.id === def.id)) {
              mergedItems.push(def);
            }
          }
          setNavItems(mergedItems);
        }
        if (parsed.dualPageView !== undefined) setDualPageView(parsed.dualPageView);
        if (parsed.navigationMode) setNavigationModeState(parsed.navigationMode);
        if (parsed.collapsed !== undefined) setCollapsed(parsed.collapsed);
        if (parsed.trainingMode) setTrainingModeState(parsed.trainingMode);
      }
    } catch {
      // ignore parse errors
    }
  }, []);
  /* eslint-enable react-hooks/set-state-in-effect */

  // Persist state to localStorage
  const persistState = useCallback(() => {
    const state = {
      navItems,
      dualPageView,
      navigationMode,
      collapsed,
      trainingMode,
    };
    localStorage.setItem("cultivation-nav-state", JSON.stringify(state));
  }, [navItems, dualPageView, navigationMode, collapsed, trainingMode]);

  const setTheme = useCallback((t: ThemeMode) => {
    setThemeState(t);
    if (typeof window !== "undefined") {
      document.documentElement.classList.remove("dark", "light");
      document.documentElement.classList.add(t);
      localStorage.setItem("cultivation-theme", t);
    }
  }, []);

  const toggleTheme = useCallback(() => {
    setTheme(theme === "dark" ? "light" : "dark");
  }, [theme, setTheme]);

  const setThemeStyle = useCallback((style: ThemeStyle) => {
    const normalizedStyle: ThemeStyle = (THEME_CLASS_NAMES as readonly string[]).includes(style)
      ? style
      : "discord";
    setThemeStyleState(normalizedStyle);
    if (typeof window !== "undefined") {
      document.documentElement.classList.remove(...THEME_CLASS_NAMES);
      document.documentElement.classList.add(normalizedStyle);
      localStorage.setItem("cultivation-theme-style", normalizedStyle);
    }
  }, []);

  // Load saved theme on mount
  /* eslint-disable react-hooks/set-state-in-effect -- hydration from localStorage on mount */
  useEffect(() => {
    const saved = localStorage.getItem("cultivation-theme") as ThemeMode | null;
    if (saved && (saved === "dark" || saved === "light")) {
      setTheme(saved);
    }
    const savedStyle = localStorage.getItem("cultivation-theme-style") as ThemeStyle | null;
    if (savedStyle && (THEME_CLASS_NAMES as readonly string[]).includes(savedStyle)) {
      setThemeStyle(savedStyle);
    } else {
      setThemeStyle("discord");
    }
    // Layout selection removed: always use Layout 1 shell.
    localStorage.removeItem("cultivation-layout-style");
  }, [setTheme, setThemeStyle]);
  /* eslint-enable react-hooks/set-state-in-effect */

  // Hydrate shared theme preferences per user (desktop/web)
  useEffect(() => {
    let cancelled = false;

    const hydrateRemoteTheme = async () => {
      if (!user?.id) {
        syncedUserIdRef.current = null;
        setRemotePrefsReady(true);
        return;
      }

      setRemotePrefsReady(false);
      try {
        const payload = await api.get<{ appPrefs?: Record<string, unknown> }>("/api/users/preferences", { cache: "no-store" });
        const appPrefs = payload?.appPrefs && typeof payload.appPrefs === "object" ? payload.appPrefs : null;
        if (!appPrefs || cancelled) return;

        const remoteTheme = appPrefs.theme;
        const remoteThemeStyle = appPrefs.themeStyle;

        if (remoteTheme === "dark" || remoteTheme === "light") {
          setThemeState(remoteTheme);
          document.documentElement.classList.remove("dark", "light");
          document.documentElement.classList.add(remoteTheme);
          localStorage.setItem("cultivation-theme", remoteTheme);
        }

        if (typeof remoteThemeStyle === "string") {
          const normalizedStyle: ThemeStyle = (THEME_CLASS_NAMES as readonly string[]).includes(remoteThemeStyle)
            ? (remoteThemeStyle as ThemeStyle)
            : "discord";
          setThemeStyleState(normalizedStyle);
          document.documentElement.classList.remove(...THEME_CLASS_NAMES);
          document.documentElement.classList.add(normalizedStyle);
          localStorage.setItem("cultivation-theme-style", normalizedStyle);
        }
      } catch {
        // Ignore remote sync errors; local settings remain usable.
      } finally {
        if (!cancelled) {
          syncedUserIdRef.current = user.id;
          setRemotePrefsReady(true);
        }
      }
    };

    hydrateRemoteTheme();

    return () => {
      cancelled = true;
    };
  }, [user?.id]);

  // Persist theme changes to shared per-user preferences.
  useEffect(() => {
    if (!remotePrefsReady || !user?.id || syncedUserIdRef.current !== user.id) return;

    const timer = window.setTimeout(() => {
      api.put("/api/users/preferences", {
        appPrefs: {
          theme,
          themeStyle,
        },
      }).catch(() => {
        // Ignore sync failures; local settings are still saved.
      });
    }, 300);

    return () => window.clearTimeout(timer);
  }, [theme, themeStyle, remotePrefsReady, user?.id]);

  // Unified shell mode: the app now keeps the mobile-first structure on every screen size.
  // Screen width can still influence spacing through CSS, but it no longer swaps the UI architecture.
  useEffect(() => {
    const applyUnifiedShell = () => {
      setIsMobile(true);
      setCollapsed(true);
      setPanelPosition("top");
      setTopPanelExpandedState(false);
    };

    applyUnifiedShell();
    window.addEventListener("resize", applyUnifiedShell);
    return () => window.removeEventListener("resize", applyUnifiedShell);
  }, [navigationMode]);

  // Persist state changes
  useEffect(() => {
    persistState();
  }, [persistState]);

  const toggleDualPage = useCallback(() => {
    setDualPageView((v) => !v);
  }, []);

  const toggleNavVisibility = useCallback((id: string) => {
    setNavItems((items) =>
      items.map((item) =>
        item.id === id ? { ...item, visible: !item.visible } : item
      )
    );
  }, []);

  const toggleNavPin = useCallback((id: string) => {
    setNavItems((items) =>
      items.map((item) =>
        item.id === id ? { ...item, pinned: !item.pinned } : item
      )
    );
  }, []);

  const reorderNavItems = useCallback((newOrder: NavItem[]) => {
    setNavItems(newOrder);
  }, []);

  const getSortedNavItems = useCallback(() => {
    const visible = navItems.filter((item) => item.visible);
    const pinned = visible.filter((item) => item.pinned);
    const unpinned = visible.filter((item) => !item.pinned);
    return [...pinned, ...unpinned];
  }, [navItems]);

  const sortedNavItems = useMemo(() => getSortedNavItems(), [getSortedNavItems]);

  const setNavigationMode = useCallback((mode: NavigationMode) => {
    setNavigationModeState(mode);
  }, []);

  const setTopPanelExpanded = useCallback((expanded: boolean) => {
    setTopPanelExpandedState(expanded);
  }, []);

  const setTrainingMode = useCallback((mode: TrainingMode) => {
    setTrainingModeState(mode);
  }, []);

  const appContextValue = useMemo<AppContextType>(() => ({
        navItems,
        dualPageView,
        panelPosition,
        currentPage,
        collapsed,
        isMobile,
        theme,
        themeStyle,
        navigationMode,
        topPanelExpanded,
        trainingMode,
        setCurrentPage,
        toggleDualPage,
        toggleNavVisibility,
        toggleNavPin,
        reorderNavItems,
        setCollapsed,
        getSortedNavItems,
        setTheme,
        toggleTheme,
        setThemeStyle,
        setNavigationMode,
        setTopPanelExpanded,
        setTrainingMode,
        mobileSidebarOpen,
        setMobileSidebarOpen,
        registerDrawerClose,
        activeDrawerClose,
      }), [
        activeDrawerClose,
        collapsed,
        currentPage,
        dualPageView,
        getSortedNavItems,
        isMobile,
        mobileSidebarOpen,
        navItems,
        navigationMode,
        panelPosition,
        registerDrawerClose,
        reorderNavItems,
        setCollapsed,
        setCurrentPage,
        setMobileSidebarOpen,
        setNavigationMode,
        setTheme,
        setThemeStyle,
        setTopPanelExpanded,
        setTrainingMode,
        theme,
        themeStyle,
        toggleDualPage,
        toggleNavPin,
        toggleNavVisibility,
        toggleTheme,
        topPanelExpanded,
        trainingMode,
      ]);

  return (
    <IsMobileContext.Provider value={isMobile}>
      <SortedNavItemsContext.Provider value={sortedNavItems}>
        <AppContext.Provider value={appContextValue}>
          {children}
        </AppContext.Provider>
      </SortedNavItemsContext.Provider>
    </IsMobileContext.Provider>
  );
}

export function useAppContext() {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error("useAppContext must be used within AppProvider");
  return ctx;
}

export function useIsMobile() {
  return useContext(IsMobileContext);
}

export function useSortedNavItems() {
  return useContext(SortedNavItemsContext);
}

"use client";

import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
import { ReactNode, useState, useEffect, useRef, memo } from "react";
import { useAppContext } from "@/context/AppContext";
import { DISPLAY_DEFAULTS } from "@/context/DisplaySettingsContext";

interface PageLayoutProps {
  children: ReactNode;
  sidebar?: ReactNode;
  title: string;
  subtitle?: string;
  sidebarLabel?: string;
  contentWidth?: "centered" | "fluid";
  contentMaxWidthClass?: string;
  mobileContentPaddingClass?: string;
  mobileScrollContainerEnabled?: boolean;
}

function PageLayout({
  children,
  sidebar,
  title,
  subtitle,
  sidebarLabel,
  contentWidth = "centered",
  contentMaxWidthClass = "max-w-[1400px]",
  mobileContentPaddingClass = "p-4 pb-24",
  mobileScrollContainerEnabled = true,
}: PageLayoutProps) {
  const { panelPosition, isMobile, mobileSidebarOpen, setMobileSidebarOpen, themeStyle } = useAppContext();
  const prefersReducedMotion = useReducedMotion();
  const disableMotion = themeStyle === "discord" || prefersReducedMotion;
  const effectivePosition = isMobile ? "top" : panelPosition;
  const mobileMode = isMobile;
  const mobileSidebarHistoryArmedRef = useRef(false);
  const sidebarTouchStartXRef = useRef<number | null>(null);
  const sidebarTouchCurrentXRef = useRef<number | null>(null);
  const sidebarWidth = DISPLAY_DEFAULTS.sidebarWidth;

  const MIN_SIDEBAR_WIDTH = 200;

  const contentContainerClass = contentWidth === "centered"
    ? `mx-auto w-full ${contentMaxWidthClass}`
    : "w-full";

  // Close mobile panels on escape
  useEffect(() => {
    if (!mobileSidebarOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setMobileSidebarOpen(false);
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [mobileSidebarOpen, setMobileSidebarOpen]);

  // Lock body scroll when mobile panels open
  useEffect(() => {
    if (mobileSidebarOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => { document.body.style.overflow = ""; };
  }, [mobileSidebarOpen]);

  // Arm history while mobile drawers are open so Android back closes drawer first.
  useEffect(() => {
    if (!mobileSidebarOpen) {
      mobileSidebarHistoryArmedRef.current = false;
      return;
    }
    if (mobileSidebarHistoryArmedRef.current) return;

    try {
      window.history.pushState({ mobileDrawer: true, at: Date.now() }, "", window.location.href);
      mobileSidebarHistoryArmedRef.current = true;
    } catch {
      // Ignore history errors.
    }
  }, [mobileSidebarOpen]);

  // Browser back should close mobile drawers before navigation.
  useEffect(() => {
    const onPopState = () => {
      if (!mobileSidebarOpen) return;
      setMobileSidebarOpen(false);
      mobileSidebarHistoryArmedRef.current = false;
    };

    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, [mobileSidebarOpen, setMobileSidebarOpen]);

  const onSidebarTouchStart = (event: React.TouchEvent<HTMLDivElement>) => {
    sidebarTouchStartXRef.current = event.touches[0]?.clientX ?? null;
    sidebarTouchCurrentXRef.current = sidebarTouchStartXRef.current;
  };

  const onSidebarTouchMove = (event: React.TouchEvent<HTMLDivElement>) => {
    sidebarTouchCurrentXRef.current = event.touches[0]?.clientX ?? null;
  };

  const onSidebarTouchEnd = () => {
    const start = sidebarTouchStartXRef.current;
    const end = sidebarTouchCurrentXRef.current;
    sidebarTouchStartXRef.current = null;
    sidebarTouchCurrentXRef.current = null;
    if (start == null || end == null) return;
    const deltaX = end - start;
    if (deltaX < -48) {
      setMobileSidebarOpen(false);
      mobileSidebarHistoryArmedRef.current = false;
    }
  };

  // Close sidebars when switching away from mobile
  useEffect(() => {
    if (!isMobile) {
      const timer = window.setTimeout(() => {
        setMobileSidebarOpen(false);
      }, 0);
      return () => window.clearTimeout(timer);
    }
  }, [isMobile, setMobileSidebarOpen]);

  // Desktop sidebar element
  const desktopSidebar = sidebar && !isMobile && effectivePosition !== "top" ? (
    <motion.div
      layout={!disableMotion}
      className="sticky top-0 safe-area-top safe-area-bottom self-start h-full border-l-0 surface-panel surface-panel-strong shrink-0 overflow-hidden flex flex-col"
      style={{
        width: `${sidebarWidth}px`,
        minWidth: `${MIN_SIDEBAR_WIDTH}px`,
        borderRightWidth: 0,
        background: "var(--sidebar-canvas-bg)",
      }}
    >
      <div className="px-5 pt-4 pb-2.5 shrink-0 flex items-center justify-between">
        <h2 className="text-xs text-jade-glow uppercase tracking-widest font-semibold">{title}</h2>
      </div>
      <div className="flex-1 min-h-0 px-1.5 overflow-y-auto sidebar-scroll overscroll-contain">
        {sidebar}
      </div>
      <div className="h-2 shrink-0" />
    </motion.div>
  ) : sidebar && !isMobile && effectivePosition === "top" ? (
    <motion.div
      layout={!disableMotion}
      className="w-full border-b surface-panel surface-panel-strong shrink-0 overflow-hidden flex flex-col max-h-[40vh]"
      style={{
        borderColor: "var(--sidebar-canvas-border)",
        background: "var(--sidebar-canvas-bg)",
      }}
    >
      <div className="px-5 pt-4 pb-2.5 shrink-0 flex items-center justify-between">
        <h2 className="text-xs text-jade-glow uppercase tracking-widest font-semibold">{title}</h2>
      </div>
      <div className="flex-1 min-h-0 px-1.5 overflow-y-auto scrollbar-hide">
        {sidebar}
      </div>
      <div className="h-2 shrink-0" />
    </motion.div>
  ) : null;

  return (
    <motion.div
      initial={disableMotion ? false : { opacity: 0 }}
      animate={disableMotion ? { opacity: 1 } : { opacity: 1 }}
      transition={{ duration: disableMotion ? 0 : 0.25, ease: [0.22, 1, 0.36, 1] }}
      className={`flex ${effectivePosition === "top" || isMobile ? "flex-col" : "flex-row"} relative ${isMobile ? "min-h-full" : "h-full overflow-hidden"}`}
      style={{ background: "var(--page-gutter-bg)" }}
    >
      {/* Desktop sidebar */}
      {desktopSidebar}

      {/* Main Content — full width on mobile */}
      <div className="flex-1 min-w-0">
        <div
          data-mobile-scroll-container={isMobile && mobileScrollContainerEnabled ? "true" : undefined}
          className={`flex-1 min-w-0 ${isMobile ? `${mobileScrollContainerEnabled ? "overflow-y-auto scrollbar-hide" : "overflow-hidden"} ${mobileContentPaddingClass} overflow-x-hidden` : "h-full overscroll-contain [scrollbar-gutter:stable] overflow-x-auto p-2"}`}
        >
          <motion.div
            initial={disableMotion ? false : { opacity: 0 }}
            animate={disableMotion ? { opacity: 1 } : { opacity: 1 }}
            transition={{ delay: disableMotion ? 0 : 0.04, duration: disableMotion ? 0 : 0.25, ease: [0.22, 1, 0.36, 1] }}
            className="page-rise"
          >
            <div className={`${contentContainerClass} ${isMobile ? "" : "rounded-2xl"}`}>
              {children}
            </div>
          </motion.div>
        </div>
      </div>


      {/* ── Mobile slide-in sidebar (page panel) — native APK only ── */}
      <AnimatePresence>
        {mobileSidebarOpen && mobileMode && sidebar && (
          <>
            <motion.div
              key="page-sidebar-backdrop"
              initial={disableMotion ? false : { opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={disableMotion ? { opacity: 1 } : { opacity: 0 }}
              transition={{ duration: disableMotion ? 0 : 0.18 }}
              className="fixed inset-0 z-40 bg-void-black/70"
              onClick={() => setMobileSidebarOpen(false)}
            />
            <motion.div
              key="page-sidebar-panel"
              initial={disableMotion ? false : { x: "-100%" }}
              animate={disableMotion ? { x: 0 } : { x: 0 }}
              exit={disableMotion ? { x: 0 } : { x: "-100%" }}
              drag="x"
              dragDirectionLock
              dragConstraints={{ left: 0, right: 0 }}
              dragElastic={{ left: 0.06, right: 0 }}
              onDragEnd={(_event, info) => {
                if (info.offset.x < -70 || info.velocity.x < -380) {
                  setMobileSidebarOpen(false);
                }
              }}
              transition={disableMotion ? { duration: 0 } : { type: "spring", damping: 31, stiffness: 360, mass: 0.72 }}
              className="fixed inset-y-0 left-0 z-50 surface-panel surface-panel-strong flex flex-col shadow-2xl touch-pan-y pt-[max(env(safe-area-inset-top,0px),12px)] pb-[max(env(safe-area-inset-bottom,0px),10px)]"
              style={{
                width: "min(88vw, 380px)",
                borderRightWidth: 0,
                background: "var(--sidebar-canvas-bg)",
              }}
              onTouchStart={onSidebarTouchStart}
              onTouchMove={onSidebarTouchMove}
              onTouchEnd={onSidebarTouchEnd}
            >
              <div className="flex items-center justify-between px-5 pb-4 border-b border-ink-light/50 shrink-0">
                <h2 className="text-base text-jade-glow font-semibold uppercase tracking-[0.1em]">
                  {sidebarLabel || title}
                </h2>
                <button
                  onClick={() => setMobileSidebarOpen(false)}
                  className="p-2 rounded-xl text-mist-dark active:text-cloud-white active:bg-white/10 transition-colors min-w-[44px] min-h-[44px] flex items-center justify-center"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 sidebar-scroll overscroll-contain">
                {sidebar}
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

    </motion.div>
  );
}

export default memo(PageLayout);

