// ── Check-in / attendance data ───────────────────────────
// Generate realistic check-in data for admin & judy Feb-Apr 2026

function generateCheckIns(userId: string, username: string): Array<{
  date: string;
  userId: string;
  present: boolean;
  weight: number | null;
  comment: string | null;
}> {
  const checkins: Array<{
    date: string;
    userId: string;
    present: boolean;
    weight: number | null;
    comment: string | null;
  }> = [];

  // Start weight and target
  const isAdmin = username === "admin";
  let weight = isAdmin ? 78.5 : 55.2;
  const weightTrend = isAdmin ? -0.15 : -0.08; // gradual loss

  // Training days by week pattern
  // Admin: Mon, Tue, Thu, Fri (sometimes Sat)
  // Judy: Mon, Wed, Thu, Sat
  const adminDays = [1, 2, 4, 5]; // Mon=1, Tue=2, Thu=4, Fri=5
  const judyDays = [1, 3, 4, 6];
  const trainingDays = isAdmin ? adminDays : judyDays;

  const start = new Date("2026-02-02"); // First Monday of Feb
  const end = new Date("2026-04-06");

  const comments = isAdmin
    ? [null, null, null, "Good session", "Felt strong today", null, "A bit tired", null, null, "Great energy", null, "Deload week", null, null, null]
    : [null, null, "Nice workout", null, null, null, "Sore from yesterday", null, null, null, "Feeling great!", null, null, null, null];

  let commentIdx = 0;
  const current = new Date(start);

  while (current <= end) {
    const dow = current.getDay(); // 0=Sun
    const dateStr = current.toISOString().split("T")[0];

    if (trainingDays.includes(dow)) {
      // ~90% attendance rate
      const present = Math.random() < 0.9;

      if (present) {
        // Weight fluctuates ±0.5kg day-to-day
        weight += weightTrend + (Math.random() - 0.5) * 0.6;
        weight = Math.round(weight * 10) / 10;

        checkins.push({
          date: dateStr,
          userId,
          present: true,
          weight: Math.random() < 0.75 ? weight : null, // 75% log weight
          comment: comments[commentIdx % comments.length],
        });
        commentIdx++;
      }
    }

    current.setDate(current.getDate() + 1);
  }

  return checkins;
}

// ─────────────────────────────────────────────────────────

function normalizeKey(s: string): string {
  return s.trim().toLowerCase().replace(/\s+/g, " ");
}

async function main() {
  const client = createClient({ url: DB_URL });

  try {
    console.log("=== Seed Admin Training Logs & Check-ins ===\n");

    // ── Find users ──
    const adminRow = await client.execute({ sql: "SELECT id FROM User WHERE username = ?", args: ["admin"] });
    const judyRow = await client.execute({ sql: "SELECT id FROM User WHERE username = ?", args: ["judy"] });

    if (!adminRow.rows.length) throw new Error("Admin user not found.");
    if (!judyRow.rows.length) throw new Error("Judy user not found.");

    const adminId = String(adminRow.rows[0].id);
    const judyId = String(judyRow.rows[0].id);

    // ── Load exercises ──
    const exerciseRows = await client.execute("SELECT id, name FROM ProgressionExercise");
    const exerciseByName = new Map<string, string>();
    for (const row of exerciseRows.rows) {
      exerciseByName.set(normalizeKey(String(row.name)), String(row.id));
    }

    // Load tiers and variations
    const tierRows = await client.execute("SELECT id, exerciseId, level, name FROM ProgressionTier ORDER BY level ASC");
    const tiersByExercise = new Map<string, Array<{ level: number; name: string }>>();
    for (const row of tierRows.rows) {
      const exId = String(row.exerciseId);
      if (!tiersByExercise.has(exId)) tiersByExercise.set(exId, []);
      tiersByExercise.get(exId)!.push({ level: Number(row.level), name: String(row.name) });
    }

    const varRows = await client.execute("SELECT id, exerciseId, name FROM ProgressionVariation");
    const varsByExercise = new Map<string, string[]>();
    for (const row of varRows.rows) {
      const exId = String(row.exerciseId);
      if (!varsByExercise.has(exId)) varsByExercise.set(exId, []);
      varsByExercise.get(exId)!.push(String(row.name));
    }

    // ── 1. Admin training logs ───────────────────────────
    console.log("── Admin Training Logs ──");

    let logInserted = 0;
    let logSkipped = 0;

    for (const entry of ADMIN_LOGS) {
      const exerciseId = exerciseByName.get(normalizeKey(entry.exercise));
      if (!exerciseId) {
        console.log(`  ⚠ Exercise "${entry.exercise}" not found — skipping`);
        continue;
      }

      // Upsert UserProgressionLevel
      const existingUPL = await client.execute({
        sql: "SELECT id, currentLevel FROM UserProgressionLevel WHERE userId = ? AND exerciseId = ?",
        args: [adminId, exerciseId],
      });

      let progressId: string;
      if (existingUPL.rows.length > 0) {
        progressId = String(existingUPL.rows[0].id);
        const curLevel = Number(existingUPL.rows[0].currentLevel);
        if (entry.level > curLevel) {
          await client.execute({
            sql: "UPDATE UserProgressionLevel SET currentLevel = ?, updatedAt = ? WHERE id = ?",
            args: [entry.level, new Date().toISOString(), progressId],
          });
        }
      } else {
        progressId = cuid();
        const now = new Date().toISOString();
        await client.execute({
          sql: "INSERT INTO UserProgressionLevel (id, userId, exerciseId, currentLevel, createdAt, updatedAt) VALUES (?, ?, ?, ?, ?, ?)",
          args: [progressId, adminId, exerciseId, entry.level, now, now],
        });
      }

      // Check for existing log on same day
      const dayStart = entry.date + "T00:00:00.000Z";
      const dayEnd = entry.date + "T23:59:59.999Z";
      const existingLog = await client.execute({
        sql: "SELECT id FROM ProgressionLog WHERE userProgressionId = ? AND createdAt >= ? AND createdAt <= ?",
        args: [progressId, dayStart, dayEnd],
      });

      if (existingLog.rows.length > 0) {
        logSkipped++;
        continue;
      }

      // Resolve variant
      let variant: string | null = entry.variant ?? null;
      if (variant) {
        const vars = varsByExercise.get(exerciseId) ?? [];
        const match = vars.find((v) => normalizeKey(v) === normalizeKey(variant!));
        variant = match ?? variant;
      }

      await client.execute({
        sql: `INSERT INTO ProgressionLog (id, userProgressionId, level, weight1, reps1, weight2, reps2, weight3, reps3, holdTime, holdTime2, holdTime3, modifier, variant, notes, completed, createdAt)
              VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        args: [
          cuid(), progressId, entry.level,
          entry.w1 ?? null, entry.r1 ?? null,
          entry.w2 ?? null, entry.r2 ?? null,
          entry.w3 ?? null, entry.r3 ?? null,
          entry.holdTime ?? null, entry.holdTime2 ?? null, entry.holdTime3 ?? null,
          entry.modifier ?? null, variant, entry.notes ?? null,
          0, // completed = false
          entry.date + "T09:00:00.000Z",
        ],
      });

      logInserted++;
    }

    console.log(`  Inserted: ${logInserted} logs`);
    console.log(`  Skipped (duplicates): ${logSkipped}`);
    console.log(`  Exercises touched: ${new Set(ADMIN_LOGS.map((l) => l.exercise)).size}`);

    // ── 2. Check-ins / attendance ────────────────────────
    console.log("\n── Check-in Attendance ──");

    const adminCheckins = generateCheckIns(adminId, "admin");
    const judyCheckins = generateCheckIns(judyId, "judy");
    const allCheckins = [...adminCheckins, ...judyCheckins];

    let ciInserted = 0;
    let ciSkipped = 0;

    for (const ci of allCheckins) {
      const dateISO = ci.date + "T00:00:00.000Z";

      const existing = await client.execute({
        sql: "SELECT id FROM CheckIn WHERE date = ? AND userId = ?",
        args: [dateISO, ci.userId],
      });

      if (existing.rows.length > 0) {
        ciSkipped++;
        continue;
      }

      await client.execute({
        sql: "INSERT INTO CheckIn (id, date, userId, present, weight, comment, createdAt) VALUES (?, ?, ?, ?, ?, ?, ?)",
        args: [cuid(), dateISO, ci.userId, ci.present ? 1 : 0, ci.weight, ci.comment, new Date().toISOString()],
      });

      ciInserted++;
    }

    console.log(`  Admin check-ins generated: ${adminCheckins.length}`);
    console.log(`  Judy check-ins generated: ${judyCheckins.length}`);
    console.log(`  Inserted: ${ciInserted}`);
    console.log(`  Skipped (existing): ${ciSkipped}`);

    console.log("\n✓ All training logs and check-ins seeded.");
  } catch (error) {
    console.error("Seed error:", error);
    process.exit(1);
  } finally {
    client.close();
  }
}

main();

import { apiSuccess, ApiErrors } from "@/lib/api";
import { prisma } from "@/lib/prisma";
import {
  ALL_DIFFICULTIES,
} from "@/lib/exercise-types";
import { withAdmin } from "@/lib/auth/middleware";
import { getExerciseDbOptionsFromAppPrefs } from "@/lib/exercise-db-settings";
import { resolveVietnameseValue } from "@/lib/auto-vietnamese";
import {
  isPendingExerciseDescription,
  markPendingExerciseAsEdited,
  markExerciseAsDeleted,
  markExerciseAsPending,
  stripExerciseStatusMarkers,
} from "@/lib/pending-exercises";

function parseJsonObject(value: string | null | undefined): Record<string, unknown> | null {
  if (!value) return null;
  try {
    const parsed = JSON.parse(value);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed as Record<string, unknown>;
    }
  } catch {
    // Ignore malformed JSON and fallback to defaults.
  }
  return null;
}

async function getUserExerciseDbOptions(userId: string) {
  const settings = await prisma.userSettings.findUnique({
    where: { userId },
    select: { pinnedNavItems: true },
  });
  const appPrefs = parseJsonObject(settings?.pinnedNavItems) ?? {};
  return getExerciseDbOptionsFromAppPrefs(appPrefs);
}

function resolveOption(value: string, options: string[]): string | null {
  const target = value.trim().toLowerCase();
  if (!target) return null;
  return options.find((opt) => opt.toLowerCase() === target) ?? null;
}

function normalizeTypeForFlags(typeLabel: string): "weighted" | "timed" | "bodyweight" {
  const lower = typeLabel.trim().toLowerCase();
  if (lower.includes("weight") || lower.includes("load") || lower.includes("resist") || lower.includes("barbell") || lower.includes("dumbbell")) {
    return "weighted";
  }
  if (lower.includes("time") || lower.includes("hold") || lower.includes("duration") || lower.includes("isometric") || lower.includes("sec") || lower.includes("min")) {
    return "timed";
  }
  return "bodyweight";
}

/** PATCH /api/exercise-library/[id] — Update an exercise */
export const PATCH = withAdmin(async (req, { auth, params }) => {
  try {
    const id = params.id as string;
    const body = await req.json();
    const {
      name,
      category,
      exerciseType,
      muscleGroups,
      equipment,
      difficulty,
      description,
      instructions,
      progression,
      variations,
    } = body;

    const existing = await prisma.progressionExercise.findUnique({
      where: { id },
    });
    if (!existing) {
      return ApiErrors.notFound("Exercise not found");
    }

    const dbOptions = await getUserExerciseDbOptions(auth.userId);

    const updateData: Record<string, unknown> = {};
    const existingIsPending = isPendingExerciseDescription(existing.story);

    if (name !== undefined) {
      const trimmedName = String(name).trim().slice(0, 200);
      if (trimmedName.length < 2) {
        return ApiErrors.badRequest("Name must be at least 2 characters");
      }
      const allUserExercises = await prisma.progressionExercise.findMany({
        select: { id: true, name: true },
      });
      const duplicate = allUserExercises.find(
        (ex) =>
          ex.id !== id && ex.name.toLowerCase() === trimmedName.toLowerCase()
      );
      if (duplicate) {
        return ApiErrors.conflict("An exercise with this name already exists");
      }
      updateData.name = trimmedName;
      updateData.wuxiaName = trimmedName;
    }

    if (category !== undefined) {
      const resolvedCategory = resolveOption(String(category || ""), dbOptions.categories);
      if (!resolvedCategory) {
        return ApiErrors.badRequest("Invalid category");
      }
      updateData.category = resolvedCategory;
    }

    if (exerciseType !== undefined) {
      const resolvedType = resolveOption(String(exerciseType || ""), dbOptions.types);
      if (!resolvedType) {
        return ApiErrors.badRequest("Invalid exercise type");
      }
      const normalizedType = normalizeTypeForFlags(resolvedType);
      updateData.bodyweight =
        normalizedType === "bodyweight" || normalizedType === "timed";
      updateData.weighted = normalizedType === "weighted";
    }

    if (muscleGroups !== undefined) {
      if (!Array.isArray(muscleGroups) || muscleGroups.length === 0) {
        return ApiErrors.badRequest("At least one muscle group required");
      }
      const normalizedMuscles = muscleGroups
        .map((mg) => resolveOption(String(mg || ""), dbOptions.muscles))
        .filter(Boolean) as string[];
      if (normalizedMuscles.length !== muscleGroups.length) {
        return ApiErrors.badRequest("One or more muscle groups are invalid");
      }
      updateData.primaryMuscles = normalizedMuscles.join(", ");
    }

    if (equipment !== undefined) {
      updateData.equipmentType = Array.isArray(equipment)
        ? equipment.join(", ")
        : "";
    }

    if (difficulty !== undefined) {
      if (difficulty && !ALL_DIFFICULTIES.includes(difficulty)) {
        return ApiErrors.badRequest("Invalid difficulty");
      }
      updateData.difficulty = difficulty ? String(difficulty).trim() : "";
      updateData.wuxiaDifficulty = difficulty ? String(difficulty).trim() : "";
    }

    if (description !== undefined) {
      updateData.story = String(description).trim().slice(0, 2000);
    }

    if (instructions !== undefined) {
      updateData.tips = JSON.stringify(instructions);
    }

    const normalizedVariations = variations !== undefined
      ? (Array.isArray(variations)
          ? variations
              .map((variation) => String(variation || "").trim().slice(0, 200))
              .filter(Boolean)
          : null)
      : undefined;

    const normalizedProgression = progression !== undefined
      ? (Array.isArray(progression)
          ? progression
              .map((level) => String(level || "").trim().slice(0, 200))
              .filter(Boolean)
          : null)
      : undefined;

    if (normalizedVariations === null) {
      return ApiErrors.badRequest("Invalid variations payload");
    }

    if (normalizedProgression === null) {
      return ApiErrors.badRequest("Invalid progression payload");
    }

    if (normalizedProgression !== undefined) {
      updateData.progression = JSON.stringify(normalizedProgression);
    }

    if (existingIsPending && Object.keys(updateData).length > 0) {
      const nextDescription = description !== undefined
        ? String(description).trim().slice(0, 2000)
        : stripExerciseStatusMarkers(existing.story);
      updateData.story = markPendingExerciseAsEdited(markExerciseAsPending(nextDescription));
    }

    const updated = await prisma.$transaction(async (tx) => {
      if (normalizedVariations !== undefined) {
        await tx.progressionVariation.deleteMany({
          where: { exerciseId: id },
        });

        if (normalizedVariations.length > 0) {
          await tx.progressionVariation.createMany({
            data: normalizedVariations.map((variationName) => ({
              exerciseId: id,
              name: variationName,
              wuxiaName: variationName,
            })),
          });

          const createdVariations = await tx.progressionVariation.findMany({
            where: { exerciseId: id },
            select: { id: true, name: true, description: true, difficulty: true },
          });

          if (createdVariations.length > 0) {
            await tx.progressionVariationTranslation.createMany({
              data: createdVariations.map((variation) => ({
                id: variation.id,
                englishName: variation.name,
                vietnameseName: variation.name,
                englishDescription: variation.description,
                vietnameseDescription: variation.description,
                englishDifficulty: variation.difficulty,
                vietnameseDifficulty: variation.difficulty,
              })),
            });
          }
        }
      }

      const next = await tx.progressionExercise.update({
        where: { id },
        data: updateData,
        include: {
          variations: {
            select: {
              id: true,
              name: true,
            },
            orderBy: { name: "asc" },
          },
        },
      });

      await tx.progressionExerciseTranslation.upsert({
        where: { id },
        create: {
          id,
          englishName: String(updateData.name ?? existing.name),
          vietnameseName: resolveVietnameseValue(
            String(updateData.name ?? existing.name),
            String(updateData.wuxiaName ?? (existing.wuxiaName || updateData.name || existing.name)),
          ),
          englishStory: String(updateData.story ?? existing.story),
          vietnameseStory: resolveVietnameseValue(String(updateData.story ?? existing.story), null),
          englishDifficulty: String(updateData.difficulty ?? existing.difficulty),
          vietnameseDifficulty: resolveVietnameseValue(
            String(updateData.difficulty ?? existing.difficulty),
            String(updateData.wuxiaDifficulty ?? (existing.wuxiaDifficulty || updateData.difficulty || existing.difficulty)),
          ),
          englishType: String(updateData.type ?? existing.type),
          vietnameseType: resolveVietnameseValue(
            String(updateData.type ?? existing.type),
            String(updateData.wuxiaType ?? (existing.wuxiaType || updateData.type || existing.type)),
          ),
        },
        update: {
          ...(updateData.name !== undefined ? { englishName: String(updateData.name) } : {}),
          ...(updateData.wuxiaName !== undefined
            ? {
                vietnameseName: resolveVietnameseValue(
                  String(updateData.name ?? existing.name),
                  String(updateData.wuxiaName || updateData.name || existing.name),
                ),
              }
            : {}),
          ...(updateData.story !== undefined
            ? {
                englishStory: String(updateData.story),
                vietnameseStory: resolveVietnameseValue(String(updateData.story), null),
              }
            : {}),
          ...(updateData.difficulty !== undefined ? { englishDifficulty: String(updateData.difficulty) } : {}),
          ...(updateData.wuxiaDifficulty !== undefined
            ? {
                vietnameseDifficulty: resolveVietnameseValue(
                  String(updateData.difficulty ?? existing.difficulty),
                  String(updateData.wuxiaDifficulty || updateData.difficulty || existing.difficulty),
                ),
              }
            : {}),
          ...(updateData.type !== undefined ? { englishType: String(updateData.type) } : {}),
          ...(updateData.wuxiaType !== undefined
            ? {
                vietnameseType: resolveVietnameseValue(
                  String(updateData.type ?? existing.type),
                  String(updateData.wuxiaType || updateData.type || existing.type),
                ),
              }
            : {}),
        },
      });

      return next;
    });

    return apiSuccess({ exercise: updated });
  } catch (error) {
    console.error("Exercise update error:", error);
    return ApiErrors.internal("Failed to update exercise");
  }
});

/** DELETE /api/exercise-library/[id] — Move an exercise to the recycle bin */
export const DELETE = withAdmin(async (_req, { auth, params }) => {
  try {
    const id = params.id as string;

    const existing = await prisma.progressionExercise.findUnique({
      where: { id },
      select: {
        id: true,
        name: true,
        story: true,
        userId: true,
      },
