"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useSearchParams, useRouter, usePathname } from "next/navigation";
import PageLayout from "@/components/layout/PageLayout";
import PageHeader from "@/components/layout/PageHeader";
import DiscordFriendsRail from "@/components/navigation/DiscordFriendsRail";
import { api } from "@/lib/api-client";
import { useAuth } from "@/context/AuthContext";
import { useDisplaySettings } from "@/context/DisplaySettingsContext";
import { formatDateWithPreference } from "@/lib/constants";
import { EmptyFriends } from "@/components/empty-states";
import { useIncomingFriendRequestsCount } from "@/hooks/useIncomingFriendRequestsCount";
import { translateEnglishToLanguage } from "@/lib/language";

// ── Types ──────────────────────────────────────────────────────────

type Tab = "feed" | "members" | "requests";

interface FeedLog {
  id: string;
  userId: string;
  userName: string;
  exerciseName: string;
  level: number;
  progressionName?: string;
  variant?: string | null;
  createdAt: string;
  reps1?: number | null;
  reps2?: number | null;
  reps3?: number | null;
  reps?: number | null;
  weight1?: number | null;
  weight2?: number | null;
  weight3?: number | null;
  holdTime?: number | null;
  holdTime2?: number | null;
  holdTime3?: number | null;
  dynamicSetRows?: Array<{ weight: string; reps: string }> | null;
  completed: boolean;
}

interface BasicUser {
  id: string;
  name: string;
  username: string;
  createdAt?: string | null;
  friendCode?: string | null;
  sessionCount?: number | null;
  checkInCount?: number | null;
  lastWorkoutAt?: string | null;
  lastCheckInAt?: string | null;
  lastActivityAt?: string | null;
  lastActivityLabel?: string | null;
  themeStyle?: string | null;
}

interface FriendRequestRow {
  id: string;
  requesterId: string;
  receiverId: string;
  status: string;
  createdAt: string;
  requester: BasicUser;
  receiver: BasicUser;
}

interface FriendPayload {
  me?: { id: string; friendCode?: string | null } | null;
  friends: BasicUser[];
  incomingRequests: FriendRequestRow[];
  outgoingRequests: FriendRequestRow[];
}

interface CheckInRow {
  date: string;
  userId: string;
  present: boolean;
  weight?: number | null;
}

// ── Helpers ────────────────────────────────────────────────────────

function toTimestamp(value: string | null | undefined): number {
  if (!value) return Number.NaN;
  const parsed = new Date(value).getTime();
  return Number.isFinite(parsed) ? parsed : Number.NaN;
}

function formatRelative(dateLike: string | null | undefined): string {
  if (!dateLike) return "-";
  const ts = toTimestamp(dateLike);
  if (!Number.isFinite(ts)) return "-";
  const diffMs = Date.now() - ts;
  if (diffMs < 0) return "just now";
  const m = 60 * 1000;
  const h = 60 * m;
  const d = 24 * h;
  if (diffMs < h) return `${Math.max(1, Math.floor(diffMs / m))}m ago`;
  if (diffMs < d) return `${Math.max(1, Math.floor(diffMs / h))}h ago`;
  if (diffMs < 14 * d) return `${Math.max(1, Math.floor(diffMs / d))}d ago`;
  return new Date(ts).toLocaleDateString();
}

const THEME_STYLE_LABELS: Record<string, string> = {
  discord: "Discord theme",
  forest: "Forest",
  "ink-dragon": "Ink Dragon",
  "ying-yang": "Ying Yang",
  "phoenix-bloom": "Phoenix Bloom",
  "storm-chains": "Storm Chains",
  "obsidian-ember": "Obsidian Ember",
  "mist-cultivator": "Mist Cultivator",
  "frost-sect": "Frost Sect",
  "heavenly-sword": "Heavenly Sword",
};

function formatThemeStyle(themeStyle: string | null | undefined, lt?: (text: string) => string): string {
  if (!themeStyle) return lt ? lt("Theme unknown") : "Theme unknown";
  return THEME_STYLE_LABELS[themeStyle] || themeStyle;
}

function getThemePalette(themeStyle: string | null | undefined): string[] {
  const key = themeStyle && THEME_STYLE_LABELS[themeStyle] ? themeStyle : "discord";
  return [1, 2, 3, 4].map((index) => `var(--theme-preview-${key}-${index})`);
}

// ── Shared styles ──────────────────────────────────────────────────

const tileStyle = {
  borderColor: "color-mix(in srgb, var(--ink-light) 40%, transparent)",
  backgroundColor: "color-mix(in srgb, var(--ink-mid) 48%, var(--ink-deep))",
};

const microTileStyle = {
  backgroundColor: "color-mix(in srgb, var(--ink-light) 8%, transparent)",
  border: "1px solid color-mix(in srgb, var(--ink-light) 24%, transparent)",
};

function formatRelativeRecentDate(
  dateLike: string,
  dateFormat: "dd-mm-yyyy" | "dd-mmm-yyyy" | "dd-mm-yy" | "dd-mmm-yy" = "dd-mmm-yyyy",
  timeZone?: string,
): string {
  void dateFormat;
  void timeZone;
  const timestamp = new Date(dateLike).getTime();
  if (!Number.isFinite(timestamp)) return "";

  const diffMs = Date.now() - timestamp;
  if (diffMs < 0) {
    return "just now";
  }

  const minuteMs = 60 * 1000;
  const hourMs = 60 * minuteMs;
  const dayMs = 24 * hourMs;

  if (diffMs < hourMs) {
    const mins = Math.max(1, Math.floor(diffMs / minuteMs));
    return `${mins}m ago`;
  }

  if (diffMs < dayMs) {
    const hours = Math.max(1, Math.floor(diffMs / hourMs));
    return `${hours}h ago`;
  }

  const days = Math.max(1, Math.floor(diffMs / dayMs));
  return `${days} day${days === 1 ? "" : "s"} ago`;
}

// ── Feed helpers ──────────────────────────────────────────────────

function getFeedSetChips(log: FeedLog): string[] {
  const hasHold = log.holdTime != null || log.holdTime2 != null || log.holdTime3 != null;
  const chips: string[] = [];

  if (hasHold) {
    const times = [log.holdTime, log.holdTime2, log.holdTime3];
    const repsArr = [log.reps1, log.reps2, log.reps3];
    for (let i = 0; i < 3; i++) {
      const t = times[i]; const r = repsArr[i];
      if (t == null && r == null) continue;
      chips.push(t != null ? `${t}s${r != null ? ` × ${r}` : ""}` : `${r} reps`);
    }
  } else {
    const weights = [log.weight1, log.weight2, log.weight3];
    const repsArr = [log.reps1, log.reps2, log.reps3];
    for (let i = 0; i < 3; i++) {
      const w = weights[i]; const r = repsArr[i];
      if (w == null && r == null) continue;
      chips.push(w != null && w > 0 ? `${w}kg × ${r ?? "-"}` : r != null ? `${r} reps` : "-");
    }
  }

  const dynamic = Array.isArray(log.dynamicSetRows) ? log.dynamicSetRows : [];
  for (const row of dynamic) {
    if (row.weight !== "-" || row.reps !== "-") {
      chips.push(row.reps !== "-" ? `${row.weight} × ${row.reps}` : row.weight);
    }
  }

  if (chips.length === 0 && log.reps != null) chips.push(`${log.reps} reps`);
  return chips;
}

// ── Feed tab ───────────────────────────────────────────────────────

function FeedTab({ userId, onOpenFriendDrawer }: { userId: string; onOpenFriendDrawer?: (friendId: string) => void }) {
  const NON_MUTUAL_VISIBILITY_KEY = "circle-show-non-mutual-users";
  const NON_MUTUAL_VISIBILITY_EVENT = "circle-non-mutual-visibility-changed";
  const { user } = useAuth();
  const { settings } = useDisplaySettings();
  const lt = useCallback((text: string) => translateEnglishToLanguage(text, settings.languageMode), [settings.languageMode]);
  const isAdmin = user?.role === "admin";
  const [loading, setLoading] = useState(true);
  const [logs, setLogs] = useState<FeedLog[]>([]);
  const [expandedKeys, setExpandedKeys] = useState<Set<string>>(new Set());
  const [showNonMutualInFeed, setShowNonMutualInFeed] = useState<boolean>(() => {
    if (typeof window === "undefined") return false;
    return window.localStorage.getItem(NON_MUTUAL_VISIBILITY_KEY) === "1";
  });

  useEffect(() => {
    if (isAdmin || !showNonMutualInFeed) return;
    setShowNonMutualInFeed(false);
  }, [isAdmin, showNonMutualInFeed]);

  useEffect(() => {
    if (typeof window === "undefined") return;

    const syncNonMutualVisibility = () => {
      if (!isAdmin) {
        setShowNonMutualInFeed(false);
        return;
      }
      setShowNonMutualInFeed(window.localStorage.getItem(NON_MUTUAL_VISIBILITY_KEY) === "1");
    };

    syncNonMutualVisibility();
    window.addEventListener(NON_MUTUAL_VISIBILITY_EVENT, syncNonMutualVisibility);
    window.addEventListener("storage", syncNonMutualVisibility);
    return () => {
      window.removeEventListener(NON_MUTUAL_VISIBILITY_EVENT, syncNonMutualVisibility);
      window.removeEventListener("storage", syncNonMutualVisibility);
    };
  }, [isAdmin]);

  const feedScope = isAdmin && showNonMutualInFeed ? "community" : "friends";

  useEffect(() => {
    let cancelled = false;
    setLoading(true);

    type FeedExercise = {
      id: string;
      name: string;
      tiers?: Array<{ level: number; name: string }>;
      userProgress?: Array<{
        userId: string;
        user?: { id: string; name: string };
        logs: Array<{
          id: string;
          createdAt: string;
          level: number;
          variant?: string | null;
          reps1?: number | null;
          reps2?: number | null;
          reps3?: number | null;
          reps?: number | null;
          weight1?: number | null;
          weight2?: number | null;
          weight3?: number | null;
          holdTime?: number | null;
          holdTime2?: number | null;
          holdTime3?: number | null;
          dynamicSetRows?: Array<{ weight: string; reps: string }> | null;
          completed?: boolean;
        }>;
      }>;
    };

    api
      .get<{ exercises: FeedExercise[] }>(`/api/feed?scope=${feedScope}`)
      .then((data) => {
        if (cancelled) return;
        const allLogs: FeedLog[] = [];
        for (const exercise of data.exercises || []) {
          for (const progress of exercise.userProgress || []) {
            for (const log of progress.logs || []) {
              allLogs.push({
                id: log.id,
                userId: progress.userId,
                userName: progress.user?.name || lt("Unknown"),
                exerciseName: exercise.name,
                level: log.level,
                progressionName:
                  exercise.tiers?.find((t) => t.level === log.level)?.name ??
                  `${lt("Progression")} ${log.level}`,
                variant: log.variant,
                createdAt: log.createdAt,
                reps1: log.reps1,
                reps2: log.reps2,
                reps3: log.reps3,
                reps: log.reps,
                weight1: log.weight1,
                weight2: log.weight2,
                weight3: log.weight3,
                holdTime: log.holdTime,
                holdTime2: log.holdTime2,
                holdTime3: log.holdTime3,
                dynamicSetRows: log.dynamicSetRows,
                completed: log.completed || false,
              });
            }
          }
        }
        allLogs.sort(
          (a, b) =>
            new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        );
        setLogs(allLogs);
      })
      .catch(() => {
        // silent — empty state handles it
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true; };
  }, [feedScope, lt]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-[12px] text-[color:var(--text-muted)]">{lt("Loading feed...")}</p>
      </div>
    );
  }

  if (logs.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4 text-center">
        <p className="text-sm font-semibold text-[color:var(--text-primary)]">{lt("Nothing yet")}</p>
        <p className="mt-1 text-[12px] text-[color:var(--text-muted)]">
          {lt("When your circle logs workouts, their sessions will appear here.")}
        </p>
      </div>
    );
  }

  // Group by calendar day
  const grouped: Record<string, FeedLog[]> = {};
  for (const log of logs) {
    const day = log.createdAt.slice(0, 10);
    if (!grouped[day]) grouped[day] = [];
    grouped[day].push(log);
  }

  return (
    <div className="space-y-4">
      {Object.entries(grouped)
        .slice(0, 14)
        .map(([day, dayLogs], groupIndex) => {
          // Group by user + exercise within the day
          const exerciseGroups: Record<string, { exerciseName: string; userName: string; userId: string; logs: FeedLog[] }> = {};
          for (const log of dayLogs) {
            const key = `${log.userId}::${log.exerciseName}`;
            if (!exerciseGroups[key]) {
              exerciseGroups[key] = { exerciseName: log.exerciseName, userName: log.userName, userId: log.userId, logs: [] };
            }
            exerciseGroups[key].logs.push(log);
          }

          return (
            <div key={day}>
              <div className={`flex items-center gap-2 ${groupIndex === 0 ? "mb-2" : "mb-2 mt-6"}`}>
                <div className="h-px flex-1" style={{ background: "color-mix(in srgb, var(--ink-light) 55%, transparent)" }} />
                <p className="shrink-0 text-[9px] font-semibold uppercase tracking-[0.12em]" style={{ color: "var(--text-secondary)" }}>
                  {formatDateWithPreference(new Date(`${day}T00:00:00`), settings.dateFormat || "dd-mmm-yyyy")}
                </p>
                <div className="h-px flex-1" style={{ background: "color-mix(in srgb, var(--ink-light) 55%, transparent)" }} />
              </div>

              <div className="space-y-1">
                {Object.entries(exerciseGroups).map(([groupKey, group]) => {
                  const scopedGroupKey = `${day}::${groupKey}`;
                  const hasMultiple = group.logs.length > 1;
                  const isExpanded = expandedKeys.has(scopedGroupKey);
                  const visibleLogs = isExpanded ? group.logs : [];
                  const latestLog = group.logs[0];
                  const isCurrentUserLog = group.userId === userId;
                  const userNameColor = isCurrentUserLog
                    ? "var(--cultivator-self)"
                    : "var(--cultivator-friend)";
                  const toggleExpanded = () => {
                    setExpandedKeys((prev) => {
                      const next = new Set(prev);
                      if (next.has(scopedGroupKey)) next.delete(scopedGroupKey);
                      else next.add(scopedGroupKey);
                      return next;
                    });
                  };
                  const relativeDate = latestLog
                    ? formatRelativeRecentDate(
                        latestLog.createdAt,
                        settings.dateFormat || "dd-mmm-yyyy",
                        settings.timeZone,
                      )
                    : "";
                  const displayUserName = isCurrentUserLog ? lt("Me") : group.userName;

                  return (
                    <div key={groupKey}>
                      {/* Exercise header — train-style row */}
                      <article
                        className="mx-1 my-0.5 rounded-md px-3 py-2.5"
                        style={{
                          border: "1px solid color-mix(in srgb, var(--ink-light) 40%, transparent)",
                          backgroundColor: "color-mix(in srgb, var(--ink-mid) 48%, var(--ink-deep))",
                          cursor: "pointer",
                        }}
                        role="button"
                        tabIndex={0}
                        onClick={toggleExpanded}
                        onKeyDown={(event) => {
                          if (event.key === "Enter" || event.key === " ") {
                            event.preventDefault();
                            toggleExpanded();
                          }
                        }}
                      >
                        <div className="flex items-start justify-between gap-2">
                          <p className="min-w-0 text-sm font-semibold leading-tight" style={{ color: "var(--text-primary)" }}>
                            {group.exerciseName}
                            {hasMultiple ? (
                              <sup className="ml-0.5 text-[12px] font-bold leading-none" style={{ color: "var(--accent)" }}>
                                {group.logs.length}
                              </sup>
                            ) : null}
                          </p>
                          <button
                            type="button"
                            className="shrink-0 text-[11px]"
                            style={{
                              color: userNameColor,
                              cursor: isCurrentUserLog ? "default" : "pointer",
                            }}
                            onClick={(event) => {
                              event.stopPropagation();
                              if (!isCurrentUserLog) onOpenFriendDrawer?.(group.userId);
                            }}
                            disabled={isCurrentUserLog}
                            aria-label={isCurrentUserLog ? undefined : lt("Open friend drawer")}
                          >
                            {displayUserName}
                          </button>
                        </div>
                        {!isExpanded && (
                          <div className="mt-0.5 flex items-center justify-between gap-2">
                            <p className="min-w-0 truncate text-[11px] italic" style={{ color: "var(--text-muted)" }}>
                              {`${group.logs[0].variant ? `${group.logs[0].variant} ` : ""}${group.logs[0].progressionName} ${group.exerciseName}`}
                            </p>
                            <p className="shrink-0 text-[10px]" style={{ color: "var(--text-muted)" }}>
                              {relativeDate}
                            </p>
                          </div>
                        )}
                        <div
                          className="mt-1 w-full text-left"
                          aria-label={isExpanded ? lt("Collapse sets") : lt("Expand sets")}
                        >
                          <div className="space-y-1">
                            {visibleLogs.map((log, logIndex) => {
                              const chips = getFeedSetChips(log);
                              const fullLabel = `${log.variant ? `${log.variant} ` : ""}${log.progressionName || `${lt("Progression")} ${log.level}`} ${group.exerciseName}`;
                              return (
                                <div key={`${groupKey}-log-${log.id || logIndex}`} className="flex flex-col gap-0.5">
                                  <div className="flex items-center justify-between gap-2">
                                    <span className="min-w-0 truncate text-[11px] italic" style={{ color: "var(--text-muted)" }}>
                                      {fullLabel}
                                    </span>
                                    <span className="shrink-0 text-[10px] italic" style={{ color: "var(--text-muted)" }}>
                                      {formatRelativeRecentDate(log.createdAt, settings.dateFormat || "dd-mmm-yyyy", settings.timeZone)}
                                    </span>
                                  </div>
                                  <div className="flex flex-wrap items-center gap-1 pl-1">
                                    {chips.length > 0 ? chips.map((chip, chipIndex) => (
                                      <span
                                        key={`${groupKey}-log-${log.id || logIndex}-chip-${chipIndex}`}
                                        className="rounded px-1.5 py-0.5 text-[10px]"
                                        style={{
                                          backgroundColor: "color-mix(in srgb, var(--ink-light) 14%, transparent)",
                                          border: "1px solid color-mix(in srgb, var(--ink-light) 26%, transparent)",
                                          color: "var(--mist-light)",
                                        }}
                                      >
                                        {chip}
                                      </span>
                                    )) : (
                                      <span className="text-[10px]" style={{ color: "var(--mist-light)" }}>{lt("No sets recorded")}</span>
                                    )}
                                  </div>
                                </div>
                              );
                            })}
                          </div>
                        </div>
                      </article>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
    </div>
  );
}

// ── Members tab ────────────────────────────────────────────────────

function MembersTab({ userId: _userId }: { userId: string }) {
  const NON_MUTUAL_VISIBILITY_KEY = "circle-show-non-mutual-users";
  const NON_MUTUAL_VISIBILITY_EVENT = "circle-non-mutual-visibility-changed";
  const { user } = useAuth();
  const { settings } = useDisplaySettings();
  const lt = useCallback((text: string) => translateEnglishToLanguage(text, settings.languageMode), [settings.languageMode]);
  const dateFormat = settings.dateFormat || "dd-mmm-yyyy";
  const timeZone = settings.timeZone;
  const isAdmin = user?.role === "admin";

  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<FriendPayload>({
    me: null,
    friends: [],
    incomingRequests: [],
    outgoingRequests: [],
  });
  const [checkins, setCheckins] = useState<CheckInRow[]>([]);
  const [communityUsers, setCommunityUsers] = useState<BasicUser[]>([]);
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
  const [friendCodeInput, setFriendCodeInput] = useState("");
  const [addMsg, setAddMsg] = useState("");
  const [working, setWorking] = useState(false);
  const [showNonMutualUsers, setShowNonMutualUsers] = useState<boolean>(() => {
    if (typeof window === "undefined") return false;
    return window.localStorage.getItem(NON_MUTUAL_VISIBILITY_KEY) === "1";
  });

  useEffect(() => {
    // Non-admins should never be able to activate this view, even with stale local storage.
    if (isAdmin || !showNonMutualUsers) return;
    setShowNonMutualUsers(false);
  }, [isAdmin, showNonMutualUsers]);

  useEffect(() => {
    if (typeof window === "undefined" || !isAdmin) return;
    window.localStorage.setItem(NON_MUTUAL_VISIBILITY_KEY, showNonMutualUsers ? "1" : "0");
    window.dispatchEvent(new Event(NON_MUTUAL_VISIBILITY_EVENT));
  }, [isAdmin, showNonMutualUsers]);

  const broadcastUpdated = useCallback(() => {
    if (typeof window === "undefined") return;
    window.dispatchEvent(new Event("friend-requests-updated"));
    localStorage.setItem("friend-requests-updated-at", String(Date.now()));
  }, []);

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      const [fd, ci, community] = await Promise.all([
        api.get<FriendPayload>("/api/friends"),
        api
          .get<{ checkins: CheckInRow[] }>("/api/checkins?scope=friends")
          .catch(() => ({ checkins: [] as CheckInRow[] })),
        isAdmin
          ? api
              .get<{ users: BasicUser[] }>("/api/users/public?scope=community")
              .catch(() => ({ users: [] as BasicUser[] }))
          : Promise.resolve({ users: [] as BasicUser[] }),
      ]);
      setData(fd);
      setCheckins(ci.checkins || []);
      setCommunityUsers(community.users || []);
    } catch {
      // keep previous state on error
    } finally {
      setLoading(false);
    }
  }, [isAdmin]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const sendRequest = useCallback(async () => {
    const code = friendCodeInput.trim();
    if (!code) {
      setAddMsg(lt("Enter a friend code first."));
      return;
    }
    setWorking(true);
    setAddMsg("");
    try {
      await api.post("/api/friends", { friendCode: code });
      broadcastUpdated();
      await refresh();
      setFriendCodeInput("");
      setAddMsg(lt("Request sent."));
    } catch (e) {
      setAddMsg(e instanceof Error ? e.message : lt("Failed to send request."));
    } finally {
      setWorking(false);
    }
  }, [broadcastUpdated, friendCodeInput, lt, refresh]);

  const removeFriend = useCallback(
    async (friendUserId: string, name?: string) => {
      if (
        typeof window !== "undefined" &&
        !window.confirm(`${lt("Remove")} ${name || lt("this friend")}?`)
      )
        return;
      setWorking(true);
      try {
        await api.delete("/api/friends", { friendUserId });
        broadcastUpdated();
        await refresh();
      } finally {
        setWorking(false);
      }
    },
    [broadcastUpdated, lt, refresh]
  );

  const friendStatsMap = useMemo(() => {
    const map = new Map<
      string,
      {
        totalCheckIns: number;
        lastCheckInDate: string | null;
        lastSeenAt: string | null;
        totalSessions: number;
      }
    >();
    const rowsByUser = new Map<string, CheckInRow[]>();
    for (const row of checkins) {
      const existing = rowsByUser.get(row.userId) || [];
      existing.push(row);
      rowsByUser.set(row.userId, existing);
    }
    for (const friend of data.friends) {
      const rows = rowsByUser.get(friend.id) || [];
      const present = rows
        .filter((r) => r.present)
        .sort((a, b) => b.date.localeCompare(a.date));
      const candidates = [
        friend.lastActivityAt,
        friend.lastWorkoutAt,
        friend.lastCheckInAt,
        present[0]?.date ? `${present[0].date}T00:00:00.000Z` : null,
      ]
        .filter((v): v is string => Boolean(v))
        .sort((a, b) => toTimestamp(b) - toTimestamp(a));
      map.set(friend.id, {
        totalCheckIns: present.length || Number(friend.checkInCount || 0),
        lastCheckInDate: present[0]?.date || null,
        lastSeenAt: candidates[0] || null,
        totalSessions: Number(friend.sessionCount || 0),
      });
    }
    return map;
  }, [checkins, data.friends]);

  const sorted = useMemo(
    () =>
      [...data.friends].sort((a, b) => {
        const aTs = toTimestamp(friendStatsMap.get(a.id)?.lastSeenAt);
        const bTs = toTimestamp(friendStatsMap.get(b.id)?.lastSeenAt);
        if (Number.isFinite(aTs) || Number.isFinite(bTs)) {
          if (!Number.isFinite(aTs)) return 1;
          if (!Number.isFinite(bTs)) return -1;
          if (aTs !== bTs) return bTs - aTs;
        }
        return a.name.localeCompare(b.name);
      }),
    [data.friends, friendStatsMap]
  );

  const nonMutualUsers = useMemo(() => {
    if (!isAdmin) return [];
    const friendIds = new Set(data.friends.map((friend) => friend.id));
    return [...communityUsers]
      .filter((member) => member.id !== data.me?.id)
      .filter((member) => !friendIds.has(member.id))
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [communityUsers, data.friends, data.me?.id, isAdmin]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-[12px] text-[color:var(--text-muted)]">{lt("Loading members...")}</p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {/* Add friend */}
      <div className="rounded-lg px-3 py-3 border" style={tileStyle}>
        <p className="mb-2 text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">
          {lt("Add by friend code")}
        </p>
        <div className="flex gap-2">
          <input
            value={friendCodeInput}
            onChange={(e) => setFriendCodeInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") void sendRequest();
            }}
            placeholder={lt("Friend code")}
            className="flex-1 rounded-md bg-transparent px-2.5 py-1.5 text-[13px] text-[color:var(--text-primary)] outline-none"
            style={{
              border:
                "1px solid color-mix(in srgb, var(--ink-light) 40%, transparent)",
            }}
          />
          <button
            type="button"
            onClick={() => void sendRequest()}
            disabled={working}
            className="rounded-md px-3 py-1.5 text-[12px] font-semibold text-[color:var(--text-primary)] disabled:opacity-50"
            style={{
              backgroundColor:
                "color-mix(in srgb, var(--accent) 20%, transparent)",
              border:
                "1px solid color-mix(in srgb, var(--accent) 40%, transparent)",
            }}
          >
            {lt("Add")}
          </button>
        </div>
        {data.me?.friendCode && (
          <p className="mt-2 text-[11px] text-[color:var(--text-secondary)]">
            {lt("Your code:")}{" "}
            <span className="font-semibold text-[color:var(--text-primary)]">
              {data.me.friendCode}
            </span>
          </p>
        )}
        {addMsg && (
          <p className="mt-1 text-[11px] text-[color:var(--text-muted)]">{addMsg}</p>
        )}
      </div>

      {/* Friends list */}
      {isAdmin && (
        <div className="rounded-lg px-3 py-2.5 border" style={tileStyle}>
          <label className="flex cursor-pointer items-center justify-between gap-3">
            <div>
              <p className="text-[12px] font-semibold text-[color:var(--text-primary)]">
                {lt("Show users not mutually friended")}
              </p>
              <p className="text-[11px] text-[color:var(--text-muted)]">
                {lt("Toggle between your friends and all non-mutual users.")}
              </p>
            </div>
            <input
              type="checkbox"
              checked={showNonMutualUsers}
              onChange={(e) => setShowNonMutualUsers(e.target.checked)}
              className="h-4 w-4"
            />
          </label>
        </div>
      )}

      {isAdmin && showNonMutualUsers ? (
        nonMutualUsers.length === 0 ? (
          <div className="rounded-lg p-3 border" style={tileStyle}>
            <p className="text-[12px] text-[color:var(--text-muted)]">{lt("No non-mutual users found")}</p>
          </div>
        ) : (
          <div className="space-y-2">
            {isAdmin && (
              <div className="my-1 flex w-full items-center justify-center gap-1.5 px-2">
                <div className="h-px flex-1" style={{ backgroundColor: "color-mix(in srgb, var(--ink-light) 44%, transparent)" }} />
                <span className="text-[9px] uppercase tracking-[0.1em]" style={{ color: "var(--text-muted)" }}>
                  {lt("Non-mutual")}
                </span>
                <div className="h-px flex-1" style={{ backgroundColor: "color-mix(in srgb, var(--ink-light) 44%, transparent)" }} />
              </div>
            )}
            {nonMutualUsers.map((member) => (
              <article
                key={member.id}
                className="rounded-lg p-3 border"
                style={tileStyle}
              >
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <p className="truncate text-sm font-semibold text-[color:var(--text-primary)]">
                      {member.name}
                    </p>
                    <p className="truncate text-[11px] text-[color:var(--text-secondary)]">
                      @{member.username}
                    </p>
                  </div>
                  <span
                    className="shrink-0 rounded-md px-2 py-1 text-[11px] text-[color:var(--mist-light)]"
                    style={{
                      backgroundColor:
                        "color-mix(in srgb, var(--ink-light) 14%, transparent)",
                      border:
                        "1px solid color-mix(in srgb, var(--ink-light) 34%, transparent)",
                    }}
                  >
                    {lt("Not mutual")}
                  </span>
                </div>
                <p className="mt-2 text-[11px] text-[color:var(--text-muted)]">
                  {lt("Member since")}: {member.createdAt
                    ? formatDateWithPreference(member.createdAt, dateFormat, timeZone)
                    : "-"}
                </p>
              </article>
            ))}
          </div>
        )
      ) : sorted.length === 0 ? (
        <div className="rounded-lg p-3 border" style={tileStyle}>
          <EmptyFriends friendCode={data.me?.friendCode ?? undefined} />
        </div>
      ) : (
        <div className="space-y-2">
          {isAdmin && (
            <div className="my-1 flex w-full items-center justify-center gap-1.5 px-2">
              <div className="h-px flex-1" style={{ backgroundColor: "color-mix(in srgb, var(--ink-light) 44%, transparent)" }} />
              <span className="text-[9px] uppercase tracking-[0.1em]" style={{ color: "var(--text-muted)" }}>
                {lt("Mutual")}
              </span>
              <div className="h-px flex-1" style={{ backgroundColor: "color-mix(in srgb, var(--ink-light) 44%, transparent)" }} />
            </div>
          )}
          {sorted.map((friend) => {
            const stats = friendStatsMap.get(friend.id);
            const expanded = expandedIds.has(friend.id);
            const lastActivityText = friend.lastActivityAt
              ? `${friend.lastActivityLabel || lt("Active")} · ${formatRelative(friend.lastActivityAt)}`
              : stats?.lastSeenAt
                ? formatRelative(stats.lastSeenAt)
                : lt("No activity");
            return (
              <article
                key={friend.id}
                className="rounded-lg p-3 border"
                style={tileStyle}
              >
                <button
                  type="button"
                  onClick={() =>
                    setExpandedIds((prev) => {
                      const n = new Set(prev);
                      n.has(friend.id) ? n.delete(friend.id) : n.add(friend.id);
                      return n;
                    })
                  }
                  aria-expanded={expanded}
                  className="flex w-full items-start justify-between gap-3 text-left"
                >
                  <div className="min-w-0">
                    <p className="truncate text-sm font-semibold text-[color:var(--text-primary)]">
                      {friend.name}
                    </p>
                    <p className="truncate text-[11px] text-[color:var(--text-secondary)]">
                      @{friend.username}
                    </p>
                  </div>
                  <span
                      className="shrink-0 rounded-md px-2 py-1 text-[11px] text-[color:var(--mist-light)]"
                    style={{
                      backgroundColor:
                        "color-mix(in srgb, var(--accent) 14%, transparent)",
                      border:
                        "1px solid color-mix(in srgb, var(--accent) 34%, transparent)",
                    }}
                  >
                    {lastActivityText}
                  </span>
                </button>

                {expanded && (
                  <div className="mt-2.5 space-y-2">
                    <div className="grid grid-cols-2 gap-1.5">
                      <div className="rounded-md px-2 py-1.5" style={microTileStyle}>
                        <p className="text-[10px] uppercase tracking-[0.08em] text-[color:var(--text-muted)]">
                          {lt("Sessions")}
                        </p>
                        <p className="mt-0.5 text-[12px] font-semibold text-[color:var(--text-primary)]">
                          {stats?.totalSessions ?? 0}
                        </p>
                      </div>
                      <div className="rounded-md px-2 py-1.5" style={microTileStyle}>
                        <p className="text-[10px] uppercase tracking-[0.08em] text-[color:var(--text-muted)]">
                          Check-ins
                        </p>
                        <p className="mt-0.5 text-[12px] font-semibold text-[color:var(--text-primary)]">
                          {stats?.totalCheckIns ?? 0}
                        </p>
                      </div>
                      <div className="rounded-md px-2 py-1.5" style={microTileStyle}>
                        <p className="text-[10px] uppercase tracking-[0.08em] text-[color:var(--text-muted)]">
                          {lt("Last check-in")}
                        </p>
                        <p className="mt-0.5 text-[12px] font-semibold text-[color:var(--text-primary)]">
                          {stats?.lastCheckInDate
                            ? formatDateWithPreference(
                                stats.lastCheckInDate,
                                dateFormat,
                                timeZone
                              )
                            : "-"}
                        </p>
                      </div>
                      <div className="rounded-md px-2 py-1.5" style={microTileStyle}>
                        <p className="text-[10px] uppercase tracking-[0.08em] text-[color:var(--text-muted)]">
                          {lt("Member since")}
                        </p>
                        <p className="mt-0.5 text-[12px] font-semibold text-[color:var(--text-primary)]">
                          {friend.createdAt
                            ? formatDateWithPreference(friend.createdAt, dateFormat, timeZone)
                            : "-"}
                        </p>
                      </div>
                      <div className="rounded-md px-2 py-1.5" style={microTileStyle}>
                        <p className="text-[10px] uppercase tracking-[0.08em] text-[color:var(--text-muted)]">
                          {lt("Theme")}
                        </p>
                        <p className="mt-0.5 text-[12px] font-semibold text-[color:var(--text-primary)]">
                          {formatThemeStyle(friend.themeStyle, lt)}
                        </p>
                        <div className="mt-1.5 flex items-center gap-1.5">
                          {getThemePalette(friend.themeStyle).map((color, index) => (
                            <span
                              key={`${friend.id}-theme-swatch-${index}`}
                              className="h-2.5 w-2.5 rounded-full"
                              style={{
                                backgroundColor: color,
                                border: "1px solid color-mix(in srgb, var(--ink-light) 38%, transparent)",
                              }}
                            />
                          ))}
                        </div>
                      </div>
                    </div>
                    <div className="rounded-md px-2 py-1.5" style={microTileStyle}>
                      <p className="text-[10px] uppercase tracking-[0.08em] text-[color:var(--text-muted)]">
                        {lt("Last activity")}
                      </p>
                      <p className="mt-0.5 text-[12px] font-semibold text-[color:var(--text-primary)]">
                        {lastActivityText}
                      </p>
                    </div>
                    <button
                      type="button"
                      onClick={() => void removeFriend(friend.id, friend.name)}
                      disabled={working}
                      className="w-full rounded-md py-1.5 text-[11px] font-medium text-[color:var(--danger)] disabled:opacity-50"
                      style={{
                        border:
                          "1px solid color-mix(in srgb, var(--danger) 24%, transparent)",
                        backgroundColor:
                          "color-mix(in srgb, var(--danger) 8%, transparent)",
                      }}
                    >
                      {lt("Remove")}
                    </button>
                  </div>
                )}
              </article>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ── Requests tab ───────────────────────────────────────────────────

function RequestsTab() {
  const { settings } = useDisplaySettings();
  const lt = useCallback((text: string) => translateEnglishToLanguage(text, settings.languageMode), [settings.languageMode]);
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<FriendPayload>({
    me: null,
    friends: [],
    incomingRequests: [],
    outgoingRequests: [],
  });
  const [working, setWorking] = useState(false);

  const broadcastUpdated = useCallback(() => {
    if (typeof window === "undefined") return;
    window.dispatchEvent(new Event("friend-requests-updated"));
    localStorage.setItem("friend-requests-updated-at", String(Date.now()));
  }, []);

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      const fd = await api.get<FriendPayload>("/api/friends");
      setData(fd);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const respond = useCallback(
    async (requestId: string, action: "accept" | "reject") => {
      setWorking(true);
      try {
        await api.patch("/api/friends", { requestId, action });
        broadcastUpdated();
        await refresh();
      } finally {
        setWorking(false);
      }
    },
    [broadcastUpdated, refresh]
  );

  const cancel = useCallback(
    async (requestId: string) => {
      setWorking(true);
      try {
        await api.delete("/api/friends", { requestId });
        broadcastUpdated();
        await refresh();
      } finally {
        setWorking(false);
      }
    },
    [broadcastUpdated, refresh]
  );

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-[12px] text-[color:var(--text-muted)]">{lt("Loading requests...")}</p>
      </div>
    );
  }

  const { incomingRequests, outgoingRequests } = data;

  return (
    <div className="space-y-4">
      <section>
        <p className="mb-2 text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">
          {lt("Incoming")} ({incomingRequests.length})
        </p>
        {incomingRequests.length === 0 ? (
          <div
            className="rounded-lg p-3 text-center border"
            style={tileStyle}
          >
            <p className="text-[12px] text-[color:var(--text-muted)]">{lt("No pending requests")}</p>
          </div>
        ) : (
          <div className="space-y-2">
            {incomingRequests.map((req) => (
              <div
                key={req.id}
                className="flex items-center justify-between gap-3 rounded-lg px-3 py-2.5 border"
                style={tileStyle}
              >
                <div className="min-w-0">
                  <p className="truncate text-sm font-semibold text-[color:var(--text-primary)]">
                    {req.requester.name}
                  </p>
                  <p className="truncate text-[11px] text-[color:var(--text-secondary)]">
                    @{req.requester.username}
                  </p>
                </div>
                <div className="flex shrink-0 gap-1.5">
                  <button
                    type="button"
                    onClick={() => void respond(req.id, "accept")}
                    disabled={working}
                    className="rounded-md px-2.5 py-1 text-[11px] font-semibold text-[color:var(--forest)] disabled:opacity-50"
                    style={{
                      backgroundColor:
                        "color-mix(in srgb, var(--forest) 14%, transparent)",
                      border:
                        "1px solid color-mix(in srgb, var(--forest) 34%, transparent)",
                    }}
                  >
                    {lt("Accept")}
                  </button>
                  <button
                    type="button"
                    onClick={() => void respond(req.id, "reject")}
                    disabled={working}
                    className="rounded-md px-2.5 py-1 text-[11px] font-medium text-[color:var(--danger)] disabled:opacity-50"
                    style={{
                      backgroundColor:
                        "color-mix(in srgb, var(--danger) 8%, transparent)",
                      border:
                        "1px solid color-mix(in srgb, var(--danger) 24%, transparent)",
                    }}
                  >
                    {lt("Decline")}
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      <section>
        <p className="mb-2 text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">
          {lt("Outgoing")} ({outgoingRequests.length})
        </p>
        {outgoingRequests.length === 0 ? (
          <div
            className="rounded-lg p-3 text-center border"
            style={tileStyle}
          >
            <p className="text-[12px] text-[color:var(--text-muted)]">{lt("No outgoing requests")}</p>
          </div>
        ) : (
          <div className="space-y-2">
            {outgoingRequests.map((req) => (
              <div
                key={req.id}
                className="flex items-center justify-between gap-3 rounded-lg px-3 py-2.5 border"
                style={tileStyle}
              >
                <div className="min-w-0">
                  <p className="truncate text-sm font-semibold text-[color:var(--text-primary)]">
                    {req.receiver.name}
                  </p>
                  <p className="truncate text-[11px] text-[color:var(--text-secondary)]">
                    @{req.receiver.username}
                  </p>
                </div>
                <button
                  type="button"
                  onClick={() => void cancel(req.id)}
                  disabled={working}
                  className="rounded-md px-2.5 py-1 text-[11px] font-medium text-[color:var(--text-muted)] disabled:opacity-50"
                  style={{
                    backgroundColor:
                      "color-mix(in srgb, var(--ink-light) 12%, transparent)",
                    border:
                      "1px solid color-mix(in srgb, var(--ink-light) 30%, transparent)",
                  }}
                >
                  {lt("Cancel")}
                </button>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

// ── Main page ──────────────────────────────────────────────────────

export default function CirclePage() {
  const { user } = useAuth();
  const { settings } = useDisplaySettings();
  const lt = useCallback((text: string) => translateEnglishToLanguage(text, settings.languageMode), [settings.languageMode]);
  const { count: incomingFriendRequestCount } = useIncomingFriendRequestsCount(user?.id);
  const searchParams = useSearchParams();
  const router = useRouter();
  const pathname = usePathname();
  const [isFriendRailDrawerOpen, setIsFriendRailDrawerOpen] = useState(false);

  const tab = (searchParams.get("tab") as Tab) || "feed";

  const setTab = useCallback(
    (newTab: Tab) => {
      if (newTab === tab) return;
      router.push(`${pathname}?tab=${newTab}`, { scroll: false });
    },
    [pathname, router, tab]
  );

  const openFriendDrawerFromFeed = useCallback((friendId: string) => {
    if (!friendId || typeof window === "undefined") return;
    window.dispatchEvent(
      new CustomEvent("circle-open-friend-drawer", {
        detail: { friendId },
      })
    );
  }, []);

  const tabs: Array<{ id: Tab; label: string }> = [
    { id: "feed", label: lt("Feed") },
    { id: "members", label: lt("Members") },
    { id: "requests", label: lt("Requests") },
  ];

  const sectionShellStyle = {
    borderColor: "color-mix(in srgb, var(--ink-light) 56%, transparent)",
    backgroundColor: "color-mix(in srgb, var(--ink-deep) 96%, var(--ink-mid))",
    boxShadow:
      "inset 0 0 0 1px color-mix(in srgb, var(--cloud-white) 2%, transparent)",
  };

  return (
    <PageLayout
      title={lt("Circle")}
      subtitle={lt("Your cultivation circle")}
      mobileContentPaddingClass="p-0 pt-4 pb-0"
      mobileScrollContainerEnabled={false}
    >
      <div className="flex flex-1 min-h-0">
        <div className="flex shrink-0">
          <DiscordFriendsRail
            incomingFriendRequestCount={incomingFriendRequestCount}
            onDrawerOpenChange={setIsFriendRailDrawerOpen}
          />
        </div>
        <div className="flex min-w-0 flex-1 flex-col px-0">
          {!isFriendRailDrawerOpen ? (
            <section
              className="flex min-h-0 flex-1 flex-col rounded-tl-2xl border"
              style={{ ...sectionShellStyle }}
            >
              {/* Fixed top region: Page header + Tab bar */}
              <div
                className="shrink-0 rounded-tl-2xl"
                style={{
                  backgroundColor:
                    "color-mix(in srgb, var(--ink-deep) 94%, var(--ink-mid))",
                }}
              >
                <PageHeader
                  eyebrow={lt("Circle")}
                  title={tabs.find((t) => t.id === tab)?.label ?? lt("Feed")}
                  className="px-3 pt-3 pb-2.5"
                  noBorder
                />
                <div
                  className="flex border-b"
                  style={{
                    borderBottomColor:
                      "color-mix(in srgb, var(--ink-light) 42%, transparent)",
                  }}
                >
                  {tabs.map((t) => (
                    <button
                      key={t.id}
                      type="button"
                      onClick={() => setTab(t.id)}
                      className="flex-1 py-2.5 text-[12px] font-semibold tracking-wide transition-colors"
                      style={{
                        color: tab === t.id ? "var(--text-primary)" : "var(--text-muted)",
                        borderBottom:
                          tab === t.id
                            ? "2px solid var(--accent)"
                            : "2px solid transparent",
                      }}
                    >
                      {t.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Tab content — scrolls internally */}
              <div
                data-mobile-scroll-container="true"
                className="min-h-0 flex-1 overflow-y-auto scrollbar-hide px-2 py-3"
                style={{
                  paddingBottom:
                    "calc(var(--mobile-nav-offset, calc(env(safe-area-inset-bottom, 0px) + 4.85rem)) + 0.75rem)",
                }}
              >
                {user && tab === "feed" && (
                  <FeedTab
                    userId={user.id}
                    onOpenFriendDrawer={openFriendDrawerFromFeed}
                  />
                )}
                {user && tab === "members" && <MembersTab userId={user.id} />}
                {tab === "requests" && <RequestsTab />}
              </div>
            </section>
          ) : null}
        </div>
      </div>
    </PageLayout>
  );
}

﻿"use client";

import { motion } from "framer-motion";
import { useState, useEffect, useMemo, useCallback, useRef } from "react";
import PageLayout from "@/components/layout/PageLayout";
import PageSkeleton from "@/components/ui/PageSkeleton";
import GlowCard from "@/components/ui/GlowCard";
import ExerciseStatsCarousel from "@/components/dashboard/ExerciseStatsCarousel";
import { useAuth } from "@/context/AuthContext";
import { useDisplaySettings } from "@/context/DisplaySettingsContext";
import { api } from "@/lib/api-client";
import { formatDateWithPreference } from "@/lib/constants";
import { translateEnglishToLanguage } from "@/lib/language";
import { formatSetValue } from "@/lib/unit-conversion";
import { EmptyFeed } from "@/components/empty-states";

interface UserProfile {
  id: string;
  name: string;
  username?: string;
}

interface ExerciseLog {
  id: string;
  userId: string;
  userName: string;
  exerciseName: string;
  level: number;
  progressionName?: string;
  weight1?: number;
  weight2?: number;
  weight3?: number;
  reps1?: number;
  reps2?: number;
  reps3?: number;
  modifier?: string | null;
  notes?: string;
  createdAt: string;
  completed: boolean;
}

interface MemberStats {
  lastActiveAt: string;
}

interface ExerciseFeedGroup {
  exerciseName: string;
  logs: ExerciseLog[];
  lastActiveAt: string;
}

interface MemberFeed {
  userId: string;
  userName: string;
  dateKey: string;
  logs: ExerciseLog[];
  exerciseGroups: ExerciseFeedGroup[];
  stats: MemberStats;
}

function countLogSets(log: ExerciseLog): number {
  const setPairs: Array<[number | undefined, number | undefined]> = [
    [log.weight1, log.reps1],
    [log.weight2, log.reps2],
    [log.weight3, log.reps3],
  ];

  return setPairs.filter(([, reps]) => reps != null && reps > 0).length;
}

function calculateLogVolume(log: ExerciseLog): number {
  const setPairs: Array<[number | undefined, number | undefined]> = [
    [log.weight1, log.reps1],
    [log.weight2, log.reps2],
    [log.weight3, log.reps3],
  ];

  return setPairs.reduce((total, [weight, reps]) => {
    if (weight == null || reps == null || weight <= 0 || reps <= 0) return total;
    return total + weight * reps;
  }, 0);
}

const ITEMS_PER_PAGE = 7;

export default function CommunityFeedClient() {
  const { user } = useAuth();
  const { settings } = useDisplaySettings();
  const lt = useCallback((text: string) => translateEnglishToLanguage(text, settings.languageMode), [settings.languageMode]);
  const dateFormat = settings.dateFormat || "dd-mmm-yyyy";
  const weightUnit = settings.defaultWeightUnit ?? "kg";
  const [loading, setLoading] = useState(true);
  const [exerciseLogs, setExerciseLogs] = useState<ExerciseLog[]>([]);
  const [allExercises, setAllExercises] = useState<any[]>([]);
  const [filterMode, setFilterMode] = useState<"category" | "muscle-group">("category");
  const [selectedFilter, setSelectedFilter] = useState<string>("");
  const [scope, setScope] = useState<"friends" | "community">(() => {
    if (typeof window === "undefined") return "friends";
    const saved = localStorage.getItem("community-feed-scope");
    return saved === "community" ? "community" : "friends";
  });
  const [displayCount, setDisplayCount] = useState(ITEMS_PER_PAGE);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [expandedMemberGroups, setExpandedMemberGroups] = useState<Record<string, boolean>>({});
  const [expandedExerciseGroups, setExpandedExerciseGroups] = useState<Record<string, boolean>>({});
  const observerTarget = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (typeof window === "undefined") return;
    localStorage.setItem("community-feed-scope", scope);
  }, [scope]);

  useEffect(() => {
    const fetchNewsfeed = async () => {
      if (!user) return;

      setLoading(true);

      try {
        const feedData = await api.get<{
          exercises: Array<{
            id: string;
            name: string;
            category: string;
            primaryMuscles?: string;
            tiers?: Array<{
              level: number;
              name: string;
            }>;
            userProgress?: Array<{
              userId: string;
              user?: UserProfile;
              logs: Array<{
                id: string;
                createdAt: string;
                weight1?: number;
                weight2?: number;
                weight3?: number;
                reps1?: number;
                reps2?: number;
                reps3?: number;
                level: number;
                modifier?: string | null;
                notes?: string;
                completed?: boolean;
              }>;
            }>;
          }>;
        }>(`/api/feed?scope=${scope}`);

        setAllExercises(feedData.exercises || []);

        const usersMap: Record<string, UserProfile> = {};
        const allLogs: ExerciseLog[] = [];

        for (const exercise of feedData.exercises || []) {
          for (const progress of exercise.userProgress || []) {
            if (progress.user) {
              usersMap[progress.userId] = progress.user;
            }

            for (const log of progress.logs || []) {
              allLogs.push({
                id: log.id,
                userId: progress.userId,
                userName: progress.user?.name || usersMap[progress.userId]?.name || "Unknown",
                exerciseName: exercise.name,
                level: log.level,
                progressionName: exercise.tiers?.find((tier) => tier.level === log.level)?.name ?? `Progression ${log.level}`,
                weight1: log.weight1,
                weight2: log.weight2,
                weight3: log.weight3,
                reps1: log.reps1,
                reps2: log.reps2,
                reps3: log.reps3,
                modifier: log.modifier,
                notes: log.notes,
                createdAt: log.createdAt,
                completed: log.completed || false,
              });
            }
          }
        }

        allLogs.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
        setExerciseLogs(allLogs);
      } catch (err) {
        console.error("Failed to fetch newsfeed:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchNewsfeed();
  }, [scope, user]);

  const formatDayHeader = (dateKey: string): string => {
    const parsed = new Date(`${dateKey}T00:00:00`);
    return formatDateWithPreference(parsed, dateFormat);
  };

  const handleFilterChange = useCallback((mode: "category" | "muscle-group", filter: string) => {
    setFilterMode(mode);
    setSelectedFilter(filter);
    setDisplayCount(ITEMS_PER_PAGE);
  }, []);

  const toggleMemberGroup = useCallback((memberKey: string) => {
    setExpandedMemberGroups((prev) => ({
      ...prev,
      [memberKey]: !prev[memberKey],
    }));
  }, []);

  const toggleExerciseGroup = useCallback((exerciseKey: string) => {
    setExpandedExerciseGroups((prev) => ({
      ...prev,
      [exerciseKey]: !prev[exerciseKey],
    }));
  }, []);

  const allGroupedByMemberDay = useMemo<MemberFeed[]>(() => {
    const filteredLogs = selectedFilter === ""
      ? exerciseLogs
      : exerciseLogs.filter((log) => {
          const exercise = allExercises.find((e) => e.name === log.exerciseName);
          if (!exercise) return false;

          if (filterMode === "category") {
            return exercise.category === selectedFilter;
          }

          return exercise.primaryMuscles === selectedFilter;
        });

    const grouped: Record<string, ExerciseLog[]> = {};
    for (const log of filteredLogs) {
      const dateKey = log.createdAt.slice(0, 10);
      const groupKey = `${log.userId}:${dateKey}`;
      if (!grouped[groupKey]) {
        grouped[groupKey] = [];
      }
      grouped[groupKey].push(log);
    }

    return Object.entries(grouped)
      .map(([groupKey, logs]) => {
        const [userId, dateKey] = groupKey.split(":");
        const lastActiveAt = logs[0]?.createdAt ?? "";

        return {
          userId,
          userName: logs[0]?.userName ?? "Unknown",
          dateKey,
          logs,
          exerciseGroups: Object.entries(
            logs.reduce<Record<string, ExerciseLog[]>>((acc, log) => {
              if (!acc[log.exerciseName]) {
                acc[log.exerciseName] = [];
              }
              acc[log.exerciseName].push(log);
              return acc;
            }, {}),
          )
            .map(([exerciseName, groupedLogs]) => {
              const sortedLogs = [...groupedLogs].sort(
                (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
              );

              return {
                exerciseName,
                logs: sortedLogs,
                lastActiveAt: sortedLogs[0]?.createdAt ?? "",
              };
            })
            .sort((a, b) => new Date(b.lastActiveAt).getTime() - new Date(a.lastActiveAt).getTime()),
          stats: {
            lastActiveAt,
          },
        };
      })
      .sort((a, b) => new Date(b.stats.lastActiveAt).getTime() - new Date(a.stats.lastActiveAt).getTime());
  }, [exerciseLogs, allExercises, selectedFilter, filterMode]);

  const groupedByMemberDay = useMemo(() => {
    return allGroupedByMemberDay.slice(0, displayCount);
  }, [allGroupedByMemberDay, displayCount]);

  const hasMore = displayCount < allGroupedByMemberDay.length;

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting && !isLoadingMore && hasMore) {
          setIsLoadingMore(true);
          setTimeout(() => {
            setDisplayCount((prev) => Math.min(prev + ITEMS_PER_PAGE, allGroupedByMemberDay.length));
            setIsLoadingMore(false);
          }, 300);
        }
      },
      { threshold: 0.1 },
    );

    if (observerTarget.current) {
      observer.observe(observerTarget.current);
    }

    return () => observer.disconnect();
  }, [isLoadingMore, hasMore, allGroupedByMemberDay.length]);

  const timeAgo = (dateString: string): string => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return "just now";
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return formatDateWithPreference(date, dateFormat);
  };

  if (!user) return null;

  return (
    <PageLayout
      title="Community Feed"
      mobileContentPaddingClass="p-3 pb-24"
    >
      {loading ? (
        <PageSkeleton statCards={0} wideBlock rows={4} />
      ) : (
        <div className="dashboard-modern-feed">
          {allExercises.length > 0 && (
            <section className="mb-3 sm:mb-4">
              <GlowCard glow="none" hoverable={false} className="dashboard-modern-hero !p-0 overflow-hidden">
                <ExerciseStatsCarousel
                  exercises={allExercises}
                  communityLogs={exerciseLogs}
                  currentUserId={user?.id}
                  scope={scope}
                  onScopeChange={setScope}
                  onFilterChange={handleFilterChange}
                />
              </GlowCard>
            </section>
          )}

          {allGroupedByMemberDay.length === 0 ? (
            selectedFilter !== "" ? (
              <GlowCard glow="none" hoverable={false} className="dashboard-modern-empty mt-8">
                <div className="flex flex-col items-center justify-center py-12 text-center">
                  <div className="text-4xl mb-4 opacity-40">🏛️</div>
                  <h3 className="text-sm text-jade-glow uppercase tracking-wider mb-2">The Hall is Silent</h3>
                  <p className="text-sm text-mist-light max-w-sm">
                    {`No activity found for the selected ${filterMode === "category" ? "category" : "muscle group"}.`}
                  </p>
                </div>
              </GlowCard>
            ) : (
              <EmptyFeed />
            )
          ) : (
            <>
              <div className="mt-3 space-y-2.5 sm:mt-4">
                {groupedByMemberDay.map((member, memberIdx) => (
                  <GlowCard
                    key={`${member.userId}-${member.dateKey}`}
                    glow="none"
                    hoverable={false}
                    className="dashboard-modern-member"
                  >
                    {(() => {
                      const memberKey = `${member.userId}-${member.dateKey}`;
                      const isMemberExpanded = Boolean(expandedMemberGroups[memberKey]);
                      const memberNameColor = member.userId === user.id
                        ? "var(--cultivator-self)"
                        : "var(--cultivator-friend)";

                      return (
                        <>
                          <button
                            type="button"
                            onClick={() => toggleMemberGroup(memberKey)}
                            className="dashboard-modern-member-trigger w-full text-left"
                            aria-expanded={isMemberExpanded}
                          >
                            <div className="grid grid-cols-[36px_1fr_auto] sm:grid-cols-[40px_1fr_auto] gap-2 sm:gap-3 items-center">
                              <div className="grid h-9 w-9 place-items-center rounded-md border border-[var(--border)] bg-[var(--ink-deep)] sm:h-10 sm:w-10">
                                <span className="text-base font-bold sm:text-lg" style={{ color: memberNameColor }}>
                                  {member.userName.charAt(0).toUpperCase()}
                                </span>
                              </div>
                              <div className="min-w-0">
                                <h3 className="truncate text-sm font-semibold sm:text-base" style={{ color: memberNameColor }}>{member.userName}</h3>
                                <p className="truncate text-[10px] text-[var(--mist-mid)] sm:text-xs">
                                  {member.exerciseGroups.length} {member.exerciseGroups.length === 1 ? "exercise" : "exercises"} • {member.logs.length} {member.logs.length === 1 ? "entry" : "entries"} • active {timeAgo(member.stats.lastActiveAt)}
                                </p>
                              </div>
                              <div className="justify-self-end flex flex-col items-end gap-1 shrink-0">
                                <div className="rounded-md border border-[var(--border)] bg-[var(--void-black)] px-2 py-0.5 text-[9px] font-semibold uppercase tracking-wide text-[var(--mist-mid)] whitespace-nowrap sm:px-2.5 sm:py-1 sm:text-[10px]">
                                  {formatDayHeader(member.dateKey)}
                                </div>
                                <span className="text-[10px] text-[var(--text-muted)]">
                                  {isMemberExpanded ? "Hide exercises" : "Show exercises"}
                                </span>
                              </div>
                            </div>
                          </button>

                          {isMemberExpanded && (
                            <div className="flex flex-col gap-1.5 pt-2">
                              {member.exerciseGroups.map((exerciseGroup, exerciseIdx) => {
                                const exerciseKey = `${memberKey}-${exerciseGroup.exerciseName}`;
                                const isExerciseExpanded = Boolean(expandedExerciseGroups[exerciseKey]);

                                return (
                                  <motion.div
                                    key={exerciseKey}
                                    initial={{ opacity: 0, x: -10 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    transition={{ delay: memberIdx * 0.05 + (exerciseIdx * 0.02) }}
                                    className="dashboard-modern-exercise overflow-hidden px-2.5 py-2 sm:px-3"
                                  >
                                    <button
                                      type="button"
                                      onClick={() => toggleExerciseGroup(exerciseKey)}
                                      className="w-full rounded-md px-1 py-1 text-left transition-colors hover:bg-[var(--ink-deep)]/55"
                                      aria-expanded={isExerciseExpanded}
                                    >
                                      <article
                                        className="rounded-md px-2 py-2"
                                        style={{
                                          borderTop: "1px solid color-mix(in srgb, var(--ink-light) 72%, transparent)",
                                          border: isExerciseExpanded ? "1px solid color-mix(in srgb, var(--jade-glow) 55%, var(--ink-light))" : undefined,
                                          backgroundColor: isExerciseExpanded ? "color-mix(in srgb, var(--jade-glow) 10%, var(--ink-deep))" : "transparent",
                                          boxShadow: isExerciseExpanded ? "inset 0 0 0 1px color-mix(in srgb, var(--jade-glow) 14%, transparent)" : "none",
                                        }}
                                      >
                                        <div className="flex items-start justify-between gap-2">
                                          <p className="text-sm font-semibold leading-tight text-[var(--text-primary)]">
                                            {exerciseGroup.exerciseName}
                                          </p>
                                          <span className="shrink-0 text-[11px] text-[var(--text-muted)]">
                                            {timeAgo(exerciseGroup.lastActiveAt)}
                                          </span>
                                        </div>
                                        <p className="mt-0.5 text-[11px] italic text-[var(--text-muted)]">
                                          {`Recent: ${exerciseGroup.logs.length} ${exerciseGroup.logs.length === 1 ? "entry" : "entries"} • ${isExerciseExpanded ? "hide logs" : "show logs"}`}
                                        </p>
                                      </article>
                                    </button>

                                    {isExerciseExpanded && (
                                      <div className="mt-1 flex flex-col gap-1.5 pl-2 sm:pl-3">
                                        {exerciseGroup.logs.map((log) => {
                                          const modifierValue = log.modifier?.trim() || "";
                                          const notesValue = log.notes?.trim() || "";

                                          return (
                                          <article
                                            key={log.id}
                                            className="dashboard-modern-log px-3 py-2.5 sm:px-3.5"
                                            style={{ borderTop: "1px solid color-mix(in srgb, var(--ink-light) 72%, transparent)" }}
                                          >
                                            <div className="flex items-start justify-between gap-2">
                                              <div className="min-w-0">
                                                <p className="text-sm font-semibold leading-tight text-[var(--accent)]">
                                                  {log.progressionName || `Progression ${log.level}`}
                                                </p>
                                              </div>
                                              <span className="shrink-0 text-[11px] text-[var(--text-muted)]">
                                                {timeAgo(log.createdAt)}
                                              </span>
                                            </div>
                                            <div className="mt-1.5 space-y-0.5 text-[11px] leading-relaxed text-[var(--mist-light)]">
                                              {[1, 2, 3].map((setNumber) => {
                                                const weight = log[`weight${setNumber}` as keyof ExerciseLog] as number | undefined;
                                                const reps = log[`reps${setNumber}` as keyof ExerciseLog] as number | undefined;
                                                if (weight == null || reps == null) return null;
                                                return (
                                                  <div key={`${log.id}-set-${setNumber}`} className="grid grid-cols-2 gap-x-3">
                                                    <div className="min-w-0 truncate">
                                                      <span className="text-[var(--text-muted)]">Weight {setNumber}:</span>{" "}
                                                      <span className="text-[var(--accent)]">
                                                        {formatSetValue(weight, weight > 0 ? "weighted" : "bodyweight", weightUnit)}{weight > 0 ? ` ${weightUnit}` : ""}
                                                      </span>
                                                    </div>
                                                    <div className="min-w-0 truncate">
                                                      <span className="text-[var(--text-muted)]">Reps:</span>{" "}
                                                      <span className="text-[var(--forest)]">{reps}</span>
                                                    </div>
                                                  </div>
                                                );
                                              })}
                                              {(notesValue || modifierValue) ? (
                                                <div className="grid grid-cols-2 gap-x-3">
                                                  <div className="min-w-0 truncate">
                                                    {notesValue ? (
                                                      <>
                                                        <span className="text-[var(--text-muted)]">Notes:</span>{" "}
                                                        <span className="text-[var(--mist-light)]">{notesValue}</span>
                                                      </>
                                                    ) : <span aria-hidden="true" />}
                                                  </div>
                                                  <div className="min-w-0 truncate">
                                                    {modifierValue ? (
                                                      <>
                                                        <span className="text-[var(--text-muted)]">Mod:</span>{" "}
                                                        <span className="text-[var(--gold)]">{modifierValue}</span>
                                                      </>
                                                    ) : <span aria-hidden="true" />}
                                                  </div>
                                                </div>
                                              ) : null}
                                              <div className="grid grid-cols-2 gap-x-3">
                                                <div className="min-w-0 truncate">
                                                  <span className="text-[var(--text-muted)]">{lt("Status:")}</span>{" "}
                                                  <span className={log.completed ? "text-[var(--forest)]" : "text-[var(--mist-mid)]"}>
                                                    {log.completed ? lt("Completed") : lt("Logged")}
                                                  </span>
                                                </div>
                                              </div>
                                              <div className="grid grid-cols-2 gap-x-3">
                                                <div className="min-w-0 truncate">
                                                  <span className="text-[var(--text-muted)]">{lt("Sets:")}</span>{" "}
                                                  <span className="text-[var(--text-primary)]">{countLogSets(log)}</span>
                                                </div>
                                                <div className="min-w-0 truncate">
                                                  <span className="text-[var(--text-muted)]">{lt("Volume:")}</span>{" "}
                                                  <span className="text-[var(--danger)]">{calculateLogVolume(log).toFixed(1)} {weightUnit}-reps</span>
                                                </div>
                                              </div>
                                            </div>
                                          </article>
                                          );
                                        })}
                                      </div>
                                    )}
                                  </motion.div>
                                );
                              })}
                            </div>
                          )}
                        </>
                      );
                    })()}
                  </GlowCard>
                ))}
              </div>

              <div
                ref={observerTarget}
                className="dashboard-modern-loadmore flex items-center justify-center py-8"
              >
                {isLoadingMore ? (
                  <div className="flex items-center gap-3">
                    <div className="h-2 w-2 rounded-full bg-jade-glow/60 animate-bounce" />
                    <div className="h-2 w-2 rounded-full bg-jade-glow/60 animate-bounce" style={{ animationDelay: "0.1s" }} />
                    <div className="h-2 w-2 rounded-full bg-jade-glow/60 animate-bounce" style={{ animationDelay: "0.2s" }} />
                    <span className="ml-2 text-xs text-mist-light">{lt("Loading more activity...")}</span>
                  </div>
                ) : hasMore ? (
                  <button
                    type="button"
                    onClick={() => setDisplayCount((prev) => Math.min(prev + ITEMS_PER_PAGE, allGroupedByMemberDay.length))}
                    className="dashboard-modern-loadmore-btn rounded-md border border-ink-light/30 bg-ink-dark/60 px-3 py-1.5 text-xs text-jade-glow hover:bg-ink-dark/80 transition-colors"
                  >
                    {lt("Load more activity")}
                  </button>
                ) : allGroupedByMemberDay.length > 0 ? (
                  <div className="text-center">
                    <p className="text-xs text-mist-dark mb-1">{lt("No more activity")}</p>
                    <span className="text-[10px] text-mist-dark/60">You have seen all {allGroupedByMemberDay.length} recent entries</span>
                  </div>
                ) : null}
              </div>
            </>
          )}
        </div>
      )}
    </PageLayout>
  );
}

"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useParams, useRouter, useSearchParams } from "next/navigation";
import PageLayout from "@/components/layout/PageLayout";
import GlowCard from "@/components/ui/GlowCard";
import GlowButton from "@/components/ui/GlowButton";
import { useAuth } from "@/context/AuthContext";
import { useDisplaySettings } from "@/context/DisplaySettingsContext";
import { api } from "@/lib/api-client";
import { getExerciseDisplayName } from "@/lib/exercise-name";
import { getDefaultExerciseDbOptions, type ExerciseDbOptions } from "@/lib/exercise-db-settings";
import { PROGRESSION_EXERCISES_UPDATED_EVENT } from "@/lib/progression-events";
import type {
  SimpleExercise,
  TrainingCategory,
  SimpleExerciseType,
  MuscleGroup,
} from "@/lib/exercise-types";
import {
  getCategoryIcon,
  getExerciseTypeIcon,
} from "@/lib/exercise-types";

type EditorPanelId = "identity" | "classification" | "structure" | "review";

const EDITOR_PANELS: Array<{ id: EditorPanelId; label: string; description: string }> = [
  { id: "identity", label: "Identity", description: "Exercise name" },
  { id: "classification", label: "Class", description: "Category and muscles" },
  { id: "structure", label: "Structure", description: "Progression and variants" },
  { id: "review", label: "Review", description: "Apply changes" },
];

function joinList(values: string[]): string {
  return values.join(", ") || "—";
}

function splitDraftLabels(value: string): string[] {
  return value
    .split(",")
    .map((item) => item.trim().slice(0, 200))
    .filter(Boolean);
}

export default function ExerciseDetailPage() {
  const params = useParams<{ id: string }>();
  const router = useRouter();
  const searchParams = useSearchParams();
  const { user } = useAuth();
  const { settings } = useDisplaySettings();
  const userId = user?.id;
  const exerciseId = Array.isArray(params?.id) ? params.id[0] : params?.id;

  const [exercise, setExercise] = useState<SimpleExercise | null>(null);
  const [dbOptions, setDbOptions] = useState<ExerciseDbOptions>(getDefaultExerciseDbOptions());
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");

  const [name, setName] = useState("");
  const [category, setCategory] = useState<TrainingCategory>("GYM");
  const [exerciseType, setExerciseType] = useState<SimpleExerciseType>("weighted");
  const [muscleGroups, setMuscleGroups] = useState<MuscleGroup[]>([]);
  const [progression, setProgression] = useState<string[]>([]);
  const [progressionDraft, setProgressionDraft] = useState("");
  const [variations, setVariations] = useState<string[]>([]);
  const [variationDraft, setVariationDraft] = useState("");
  const [activePanel, setActivePanel] = useState<EditorPanelId>("identity");
  const [confirmedPanels, setConfirmedPanels] = useState<EditorPanelId[]>([]);
  const [highlightedField, setHighlightedField] = useState<string | null>(null);

  const resolveExerciseName = useCallback((item: SimpleExercise) => {
    return getExerciseDisplayName(
      {
        name: item.englishName || item.name,
        wuxiaName: item.vietnameseName || "",
        englishName: item.englishName,
        vietnameseName: item.vietnameseName,
      },
      settings.terminologyMode,
      settings.showExerciseForeignLanguage,
    );
  }, [settings.showExerciseForeignLanguage, settings.terminologyMode]);

  const displayName = useMemo(() => {
    if (!exercise) return "Exercise Editor";
    return resolveExerciseName(exercise);
  }, [exercise, resolveExerciseName]);

  useEffect(() => {
    if (!exercise) return;
    setName(exercise.name);
    setCategory(exercise.category);
    setExerciseType(exercise.exerciseType);
    setMuscleGroups(exercise.muscleGroups ?? []);
    setProgression((exercise.progression ?? []).filter(Boolean));
    setVariations((exercise.variations ?? []).map((variation) => variation.name).filter(Boolean));
  }, [exercise]);

  const loadExercise = useCallback(async () => {
    if (!userId || !exerciseId) return;

    setLoading(true);
    setError("");
    try {
      const [libraryData, optionsData] = await Promise.all([
        api.get<{ exercises?: SimpleExercise[] }>("/api/exercise-library"),
        api.get<{ options?: ExerciseDbOptions }>("/api/exercise-library/db-settings"),
      ]);

      if (optionsData.options) {
        setDbOptions(optionsData.options);
      }

      const found = (libraryData.exercises ?? []).find((item) => item.id === exerciseId) ?? null;
      setExercise(found);
      if (!found) {
        setError("Exercise not found.");
      }
    } catch (err) {
      console.error("Failed to load exercise details:", err);
      setError("Failed to load exercise details.");
    } finally {
      setLoading(false);
    }
  }, [exerciseId, userId]);

  useEffect(() => {
    void loadExercise();
  }, [loadExercise]);

  useEffect(() => {
    const step = searchParams.get("step");
    if (!step) return;
    if (EDITOR_PANELS.some((panel) => panel.id === step)) {
      setActivePanel(step as EditorPanelId);
    }
  }, [searchParams]);

  useEffect(() => {
    const field = searchParams.get("field");
    if (!field) {
      setHighlightedField(null);
      return;
    }

    setHighlightedField(field);

    const frame = window.requestAnimationFrame(() => {
      const target = document.getElementById(`editor-field-${field}`);
      target?.scrollIntoView({ block: "center", behavior: "smooth" });
    });

    const timeout = window.setTimeout(() => {
      setHighlightedField((current) => (current === field ? null : current));
    }, 2600);

    return () => {
      window.cancelAnimationFrame(frame);
      window.clearTimeout(timeout);
    };
  }, [activePanel, searchParams]);

  const isFocusedField = (field: string) => highlightedField === field;
  const getEditorFieldStyle = (field: string) => ({
    scrollMarginTop: "5.5rem",
    borderColor: isFocusedField(field)
      ? "color-mix(in srgb, var(--forest) 52%, transparent)"
      : "color-mix(in srgb, var(--border) 78%, transparent)",
    backgroundColor: isFocusedField(field)
      ? "color-mix(in srgb, var(--forest) 12%, var(--surface))"
      : "color-mix(in srgb, var(--surface) 92%, black)",
    boxShadow: isFocusedField(field)
      ? "0 0 0 1px color-mix(in srgb, var(--forest) 18%, transparent) inset, 0 0 22px color-mix(in srgb, var(--forest) 12%, transparent)"
      : "none",
    animation: isFocusedField(field) ? "exerciseEditorFieldFocus 1.9s ease-out 1" : "none",
    transition: "border-color 320ms ease, background-color 320ms ease, box-shadow 320ms ease, opacity 420ms ease",
    opacity: isFocusedField(field) ? 1 : 0.98,
  });

  const inputCls = "w-full rounded-lg border border-ink-light/40 bg-ink-dark px-3 py-2 text-sm text-cloud-white outline-none transition-colors focus:border-jade-glow/60";
  const chipBase = "text-[11px] rounded-lg border px-2.5 py-1.5 transition-all duration-150";
  const chipOn = "border-jade-glow/50 bg-jade-deep/40 text-jade-light";
  const chipOff = "border-ink-light/40 bg-ink-dark/60 text-mist-light hover:border-accent/55 hover:bg-accent/18 hover:text-cloud-white";

  const toggleMuscle = (muscle: MuscleGroup) => {
    setMuscleGroups((prev) => (prev.includes(muscle) ? prev.filter((item) => item !== muscle) : [...prev, muscle]));
  };

  const addUniqueLabel = (value: string, current: string[], setValue: (next: string[]) => void) => {
    const next = value.trim().slice(0, 200);
    if (!next) return false;
    if (current.some((item) => item.toLowerCase() === next.toLowerCase())) return false;
    setValue([...current, next]);
    return true;
  };

  const addDraftLabels = useCallback((value: string, current: string[], setValue: (next: string[]) => void) => {
    const nextLabels = splitDraftLabels(value);
    if (nextLabels.length === 0) return false;

    const existing = new Set(current.map((item) => item.toLowerCase()));
    const additions: string[] = [];

    for (const label of nextLabels) {
      const normalized = label.toLowerCase();
      if (existing.has(normalized)) continue;
      existing.add(normalized);
      additions.push(label);
    }

    if (additions.length === 0) return false;
    setValue([...current, ...additions]);
    return true;
  }, []);

  const moveProgressionStage = (index: number, direction: -1 | 1) => {
    setProgression((prev) => {
      const targetIndex = index + direction;
      if (targetIndex < 0 || targetIndex >= prev.length) return prev;
      const next = [...prev];
      const [moved] = next.splice(index, 1);
      next.splice(targetIndex, 0, moved);
      return next;
    });
  };

  const postEditHistory = async (field: string, beforeValue: string, afterValue: string) => {
    if (!exercise) return;
    await api.post("/api/exercise-library/edit-history", {
      exerciseId: exercise.id,
      exerciseName: exercise.name,
      field,
      beforeValue,
      afterValue,
    });
  };

  const handleSave = async () => {
    if (!exercise || !exerciseId) return;

    setError("");
    setStatus("");

    const nextName = name.trim();
    if (nextName.length < 2) {
      setError("Name must be at least 2 characters.");
      return;
    }
    if (muscleGroups.length === 0) {
      setError("Select at least one muscle group.");
      return;
    }
    if (progression.length === 0) {
      setError("Add at least one progression stage.");
      return;
    }

    const previousVariationNames = (exercise.variations ?? []).map((variation) => variation.name).filter(Boolean);
    const beforeMuscles = joinList(exercise.muscleGroups ?? []);
    const afterMuscles = joinList(muscleGroups);
    const beforeProgression = joinList(exercise.progression ?? []);
    const afterProgression = joinList(progression);
    const beforeVariations = joinList(previousVariationNames);
    const afterVariations = joinList(variations);

    const hasChanges =
      nextName !== exercise.name
      || category !== exercise.category
      || exerciseType !== exercise.exerciseType
      || beforeMuscles !== afterMuscles
      || beforeProgression !== afterProgression
      || beforeVariations !== afterVariations;

    if (!hasChanges) {
      setStatus("No changes to save.");
      return;
    }

    setSaving(true);
    try {
      await api.patch(`/api/exercise-library/${exerciseId}`, {
        name: nextName,
        category,
        exerciseType,
        muscleGroups,
        progression,
        variations,
      });

      const historyWrites: Promise<unknown>[] = [];
      if (nextName !== exercise.name) {
        historyWrites.push(postEditHistory("Name", exercise.name, nextName));
      }
      if (category !== exercise.category) {
        historyWrites.push(postEditHistory("Category", exercise.category, category));
      }
      if (exerciseType !== exercise.exerciseType) {
        historyWrites.push(postEditHistory("Type", exercise.exerciseType, exerciseType));
      }
      if (beforeMuscles !== afterMuscles) {
        historyWrites.push(postEditHistory("Muscles", beforeMuscles, afterMuscles));
      }
      if (beforeProgression !== afterProgression) {
        historyWrites.push(postEditHistory("Progression", beforeProgression, afterProgression));
      }
      if (beforeVariations !== afterVariations) {
        historyWrites.push(postEditHistory("Variants", beforeVariations, afterVariations));
      }

      await Promise.all(historyWrites);

      const updatedExercise: SimpleExercise = {
        ...exercise,
        name: nextName,
        category,
        exerciseType,
        muscleGroups,
        progression,
        variations: variations.map((value, index) => ({
          id: exercise.variations?.[index]?.id,
          name: value,
        })),
        updatedAt: new Date().toISOString(),
      };

      setExercise(updatedExercise);
      setConfirmedPanels((prev) => (prev.includes("review") ? prev : [...prev, "review"]));
      window.dispatchEvent(new Event(PROGRESSION_EXERCISES_UPDATED_EVENT));
      setStatus("Exercise saved successfully.");
    } catch (err) {
      console.error("Failed to save exercise:", err);
      setError(err instanceof Error ? err.message : "Failed to save exercise.");
    } finally {
      setSaving(false);
    }
  };

  const hasUnsavedChanges = useMemo(() => {
    if (!exercise) return false;
    return name.trim() !== exercise.name
      || category !== exercise.category
      || exerciseType !== exercise.exerciseType
      || joinList(muscleGroups) !== joinList(exercise.muscleGroups ?? [])
      || joinList(progression) !== joinList(exercise.progression ?? [])
      || joinList(variations) !== joinList((exercise.variations ?? []).map((variation) => variation.name).filter(Boolean));
  }, [exercise, name, category, exerciseType, muscleGroups, progression, variations]);

  const saveReady = name.trim().length >= 2 && muscleGroups.length > 0 && progression.length > 0;
  const shellMinHeight = "calc(100dvh - 0.5rem)";
  const panelShellStyle = { minHeight: 0, height: "100%" };
  const activePanelIndex = EDITOR_PANELS.findIndex((panel) => panel.id === activePanel);

  const completionByPanel: Record<EditorPanelId, boolean> = {
    identity: confirmedPanels.includes("identity") && name.trim().length >= 2,
    classification: confirmedPanels.includes("classification") && Boolean(category) && Boolean(exerciseType) && muscleGroups.length > 0,
    structure: confirmedPanels.includes("structure") && progression.length > 0,
    review: confirmedPanels.includes("review") && saveReady,
  };

  const handleResetDraft = () => {
    if (!exercise) return;
    setName(exercise.name);
    setCategory(exercise.category);
    setExerciseType(exercise.exerciseType);
    setMuscleGroups(exercise.muscleGroups ?? []);
    setProgression((exercise.progression ?? []).filter(Boolean));
    setVariations((exercise.variations ?? []).map((variation) => variation.name).filter(Boolean));
    setProgressionDraft("");
    setVariationDraft("");
    setError("");
    setStatus("");
    setActivePanel("identity");
    setConfirmedPanels([]);
  };

  const goToNextPanel = () => {
    if (activePanelIndex >= EDITOR_PANELS.length - 1) return;

    setConfirmedPanels((prev) => {
      const canConfirmCurrent =
        (activePanel === "identity" && name.trim().length >= 2)
        || (activePanel === "classification" && Boolean(category) && Boolean(exerciseType) && muscleGroups.length > 0)
        || (activePanel === "structure" && progression.length > 0);

      if (!canConfirmCurrent || prev.includes(activePanel)) return prev;
      return [...prev, activePanel];
    });

    setActivePanel(EDITOR_PANELS[activePanelIndex + 1]?.id ?? "review");
  };

  const goToPreviousPanel = () => {
    if (activePanelIndex <= 0) return;
    setActivePanel(EDITOR_PANELS[activePanelIndex - 1]?.id ?? "identity");
  };

  const renderPanelActions = (mode: "next" | "save" = "next") => (
    <div
      className="mt-auto flex items-center justify-between gap-2 border-t pt-3"
      style={{ borderColor: "color-mix(in srgb, var(--ink-light) 34%, transparent)" }}
    >
      <GlowButton
        variant="ghost"
        size="sm"
        onClick={goToPreviousPanel}
        disabled={activePanelIndex <= 0}
        className={`h-10 min-w-[96px] justify-center rounded-xl ${activePanelIndex <= 0 ? "pointer-events-none opacity-45" : ""}`}
        style={{
          borderColor: "color-mix(in srgb, var(--ink-light) 72%, transparent)",
          backgroundColor: "color-mix(in srgb, var(--ink-dark) 92%, var(--ink-deep))",
          color: "var(--cloud-white)",
          boxShadow: "0 0 0 1px rgba(88,101,242,0.06) inset",
        }}
      >
        ← Back
      </GlowButton>

      {mode === "save" ? (
        <GlowButton
          variant="jade"
          size="sm"
          disabled={saving || !saveReady}
          onClick={() => void handleSave()}
          className="h-10 min-w-[110px] justify-center rounded-xl"
        >
          {saving ? "Saving..." : "Save"}
        </GlowButton>
      ) : (
        <GlowButton variant="jade" size="sm" onClick={goToNextPanel} className="h-10 min-w-[96px] justify-center rounded-xl">
          Next →
        </GlowButton>
      )}
    </div>
  );

  if (!user || user.role !== "admin") {
    return (
      <PageLayout
        title="Exercise Editor"
        subtitle="Update category, type, muscles, progression, and variants for this exercise"
        mobileContentPaddingClass="p-0 pb-0"
        mobileScrollContainerEnabled={false}
      >
        <div className="flex flex-col items-center justify-center py-20 space-y-4">
          <div className="text-5xl opacity-50">🔒</div>
          <h3 className="text-lg font-semibold text-crimson-light">Access Restricted</h3>
          <p className="text-sm text-mist-dark text-center max-w-md">
            Exercise editing is available only to admins.
          </p>
          <GlowButton variant="ghost" size="sm" onClick={() => router.push("/dashboard/overview")}>
            ← Return to Overview
          </GlowButton>
        </div>
      </PageLayout>
    );
  }

  return (
    <PageLayout
      title="Exercise Editor"
      subtitle="Update category, type, muscles, progression, and variants for this exercise"
      mobileContentPaddingClass="p-0 pb-0"
      mobileScrollContainerEnabled={false}
    >
      {loading ? (
        <GlowCard glow="jade" hoverable={false}>
          <p className="py-4 text-center text-sm text-mist-dark">Loading exercise editor...</p>
        </GlowCard>
      ) : error && !exercise ? (
        <GlowCard glow="jade" hoverable={false}>
          <div className="space-y-3">
            <p className="text-sm" style={{ color: "var(--danger)" }}>{error}</p>
            <GlowButton onClick={() => router.push("/dashboard/exercise-db")} variant="jade" size="sm">
              Return to library
            </GlowButton>
          </div>
        </GlowCard>
      ) : (
        <div className="flex flex-col px-0" style={{ minHeight: shellMinHeight }}>
          <section
            className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-tl-2xl border"
            style={{
              minHeight: shellMinHeight,
              borderColor: "color-mix(in srgb, var(--ink-light) 56%, transparent)",
              backgroundColor: "color-mix(in srgb, var(--ink-deep) 96%, var(--ink-mid))",
            }}
          >
            <div
              className="sticky top-0 z-10 border-b px-3 py-2.5"
              style={{
                borderBottomColor: "color-mix(in srgb, var(--ink-light) 42%, transparent)",
                backgroundColor: "color-mix(in srgb, var(--ink-deep) 94%, var(--ink-mid))",
              }}
            >
              <div className="flex items-center gap-2">
                <Link
                  href="/dashboard/exercise-db"
                  className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-md transition-colors"
                  style={{ color: "var(--mist-light)", backgroundColor: "transparent" }}
                  aria-label="Back to exercise library"
                >
                  <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.2}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
                  </svg>
                </Link>
                <div className="min-w-0">
                  <p className="text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Exercise Library</p>
                  <h2 className="mt-0.5 text-xs font-semibold uppercase tracking-[0.08em] text-[color:var(--text-primary)]">Edit Exercise</h2>
                  <p className="mt-0.5 text-[11px] text-[color:var(--text-secondary)]">A train-style stepper for updating exercise details.</p>
                </div>
              </div>
            </div>

            <div className="flex flex-1 flex-col gap-3 px-2 py-2.5 pb-[calc(env(safe-area-inset-bottom,0px)+0.75rem)]">
              {error ? (
                <div
                  className="rounded-lg border px-3 py-2 text-[11px]"
                  style={{
                    borderColor: "color-mix(in srgb, var(--danger) 40%, transparent)",
                    backgroundColor: "color-mix(in srgb, var(--danger) 10%, transparent)",
                    color: "color-mix(in srgb, var(--danger) 78%, white)",
                  }}
                >
                  {error}
                </div>
              ) : null}

              {status ? (
                <div
                  className="rounded-lg border px-3 py-2 text-[11px]"
                  style={{
                    borderColor: "color-mix(in srgb, var(--forest) 35%, transparent)",
                    backgroundColor: "color-mix(in srgb, var(--forest) 10%, transparent)",
                    color: "color-mix(in srgb, var(--forest) 82%, white)",
                  }}
                >
                  {status}
                </div>
              ) : null}

              <div className="flex min-h-0 flex-1 flex-row gap-3 overflow-hidden">
                <aside className="w-[68px] shrink-0 sm:w-[72px]">
                  <div className="flex h-full min-h-full flex-col items-center py-1">
                    <div className="flex flex-1 flex-col items-center gap-1.5">
                      {EDITOR_PANELS.map((panel, index) => {
                        const isActive = activePanel === panel.id;
                        return (
                          <button
                            key={panel.id}
                            type="button"
                            onClick={() => setActivePanel(panel.id)}
                            className="flex h-11 w-11 items-center justify-center rounded-full text-center transition-all"
                            style={{
                              border: completionByPanel[panel.id]
                                ? "1px solid color-mix(in srgb, var(--forest) 42%, transparent)"
                                : isActive
                                  ? "1px solid color-mix(in srgb, var(--accent) 42%, transparent)"
                                  : "1px solid color-mix(in srgb, var(--border) 80%, transparent)",
                              backgroundColor: completionByPanel[panel.id]
                                ? "color-mix(in srgb, var(--forest) 14%, transparent)"
                                : isActive
                                  ? "color-mix(in srgb, var(--accent) 14%, transparent)"
                                  : "transparent",
                              color: completionByPanel[panel.id]
                                ? "color-mix(in srgb, var(--forest) 82%, white)"
                                : isActive
                                  ? "var(--text-primary)"
                                  : "var(--text-muted)",
                              boxShadow: completionByPanel[panel.id]
                                ? "0 0 16px color-mix(in srgb, var(--forest) 12%, transparent)"
                                : isActive
                                  ? "0 0 14px color-mix(in srgb, var(--accent) 10%, transparent)"
                                  : "none",
                            }}
                            aria-label={panel.label}
                            title={`${panel.label} • ${panel.description}`}
                          >
                            <span className="text-[11px] font-semibold">{index + 1}</span>
                          </button>
                        );
                      })}

                      <button
                        type="button"
                        onClick={handleResetDraft}
                        className="mt-1 flex h-10 w-10 items-center justify-center rounded-xl transition-colors"
                        style={{
                          border: "1px solid transparent",
                          backgroundColor: "transparent",
                          color: "var(--text-muted)",
                        }}
                        aria-label="Reset editor"
                        title="Reset editor"
                      >
                        <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.9}>
                          <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h5" />
                          <path strokeLinecap="round" strokeLinejoin="round" d="M20 20v-5h-5" />
                          <path strokeLinecap="round" strokeLinejoin="round" d="M20 9a8 8 0 0 0-13.66-3.66L4 9m16 6-2.34 3.66A8 8 0 0 1 4 15" />
                        </svg>
                      </button>
                    </div>
                  </div>
                </aside>

                <div className="min-w-0 flex min-h-0 flex-1 flex-col pr-0.5">
                  {activePanel === "identity" ? (
                    <section className="flex flex-col overflow-hidden px-1 py-1" style={panelShellStyle}>
                      <div className="flex-1 overflow-y-auto pr-0.5">
                        <div className="min-w-0">
                          <p className="text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Exercise identity</p>
                          <p className="mt-1 text-[11px] text-[color:var(--text-secondary)]">Confirm the parent exercise name before moving on.</p>
                        </div>

                        <div className="mt-4 rounded-lg border px-3 py-3" style={{ borderColor: "color-mix(in srgb, var(--border) 78%, transparent)", backgroundColor: "color-mix(in srgb, var(--surface) 92%, black)" }}>
                          <label className="block space-y-2">
                            <span className="text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Parent exercise</span>
                            <input
                              type="text"
                              value={name}
                              onChange={(event) => setName(event.target.value)}
                              className={inputCls}
                              maxLength={200}
                              placeholder="Enter exercise name"
                            />
                          </label>
                          <p className="mt-2 text-[11px] text-[color:var(--text-secondary)]">This is the label shown throughout the training system.</p>
                        </div>
                      </div>

                      {renderPanelActions()}
                    </section>
                  ) : null}

                  {activePanel === "classification" ? (
                    <section className="flex flex-col overflow-hidden px-1 py-1" style={panelShellStyle}>
                      <div className="flex-1 overflow-y-auto pr-0.5">
                        <div>
                          <p className="text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Classification</p>
                          <p className="mt-1 text-[11px] text-[color:var(--text-secondary)]">Set the category, training type, and targeted muscle groups.</p>
                        </div>

                        <div className="mt-4 space-y-4">
                          <div id="editor-field-category" className="rounded-lg border px-3 py-3" style={getEditorFieldStyle("category")}>
                            <label className="mb-1 block text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Category</label>
                            <div className="flex flex-wrap gap-2">
                              {dbOptions.categories.map((item) => (
                                <button
                                  key={item}
                                  type="button"
                                  onClick={() => setCategory(item as TrainingCategory)}
                                  className={`${chipBase} ${category === item ? chipOn : chipOff}`}
                                >
                                  {getCategoryIcon(item as TrainingCategory)} {item}
                                </button>
                              ))}
                            </div>
                          </div>

                          <div id="editor-field-type" className="rounded-lg border px-3 py-3" style={getEditorFieldStyle("type")}>
                            <label className="mb-1 block text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Type</label>
                            <div className="flex flex-wrap gap-2">
                              {dbOptions.types.map((item) => (
                                <button
                                  key={item}
                                  type="button"
                                  onClick={() => setExerciseType(item as SimpleExerciseType)}
                                  className={`${chipBase} ${exerciseType === item ? chipOn : chipOff}`}
                                >
                                  {getExerciseTypeIcon(item as SimpleExerciseType)} {item}
                                </button>
                              ))}
                            </div>
                          </div>

                          <div id="editor-field-muscles" className="rounded-lg border px-3 py-3" style={getEditorFieldStyle("muscles")}>
                            <label className="mb-1 block text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Muscle groups</label>
                            <div className="flex flex-wrap gap-2">
                              {dbOptions.muscles.map((item) => (
                                <button
                                  key={item}
                                  type="button"
                                  onClick={() => toggleMuscle(item as MuscleGroup)}
                                  className={`${chipBase} ${muscleGroups.includes(item as MuscleGroup) ? chipOn : chipOff}`}
                                >
                                  {item}
                                </button>
                              ))}
                            </div>
                          </div>
                        </div>
                      </div>

                      {renderPanelActions()}
                    </section>
                  ) : null}

                  {activePanel === "structure" ? (
                    <section className="flex flex-col overflow-hidden px-1 py-1" style={panelShellStyle}>
                      <div className="flex-1 overflow-y-auto pr-0.5">
                        <div>
                          <p className="text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Exercise structure</p>
                          <p className="mt-1 text-[11px] text-[color:var(--text-secondary)]">Define the progression stages and optional variations used in the library.</p>
                        </div>

                        <div className="mt-4 grid gap-3 lg:grid-cols-2">
                          <div id="editor-field-progression" className="rounded-lg border px-3 py-3" style={getEditorFieldStyle("progression")}>
                            <label className="mb-1 block text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Progression</label>
                            <div className="mb-3 flex flex-wrap gap-1.5">
                              {progression.length === 0 ? (
                                <span className="text-[11px] text-[color:var(--text-secondary)]">No progression stages yet.</span>
                              ) : progression.map((value, index) => (
                                <span key={`${value}-${index}`} className="inline-flex items-center gap-1 rounded-md border px-2 py-1 text-[11px]" style={{ borderColor: "color-mix(in srgb, var(--border) 78%, transparent)", color: "var(--text-primary)", backgroundColor: "color-mix(in srgb, var(--surface) 92%, black)" }}>
                                  <span className="rounded px-1 text-[10px]" style={{ backgroundColor: "color-mix(in srgb, var(--accent) 16%, transparent)", color: "color-mix(in srgb, var(--accent) 70%, white)" }}>
                                    {index + 1}
                                  </span>
                                  <span>{value}</span>
                                  <button
                                    type="button"
                                    onClick={() => moveProgressionStage(index, -1)}
                                    disabled={index === 0}
                                    className="rounded px-1 disabled:opacity-35"
                                    style={{ color: "#b5bac1" }}
                                    title="Move up"
                                  >
                                    ↑
                                  </button>
                                  <button
                                    type="button"
                                    onClick={() => moveProgressionStage(index, 1)}
                                    disabled={index === progression.length - 1}
                                    className="rounded px-1 disabled:opacity-35"
                                    style={{ color: "#b5bac1" }}
                                    title="Move down"
                                  >
                                    ↓
                                  </button>
                                  <button type="button" onClick={() => setProgression((prev) => prev.filter((item, itemIndex) => itemIndex !== index))} style={{ color: "var(--danger)" }}>
                                    x
                                  </button>
                                </span>
                              ))}
                            </div>
                            <div className="flex gap-2">
                              <input
                                type="text"
                                value={progressionDraft}
                                onChange={(event) => setProgressionDraft(event.target.value)}
                                onKeyDown={(event) => {
                                  if (event.key !== "Enter") return;
                                  event.preventDefault();
                                  const added = addDraftLabels(progressionDraft, progression, setProgression);
                                  if (added) setProgressionDraft("");
                                }}
                                placeholder="e.g. Assisted, Bodyweight, Weighted"
                                className={`${inputCls} !py-1.5`}
                              />
                              <button
                                type="button"
                                onClick={() => {
                                  const added = addDraftLabels(progressionDraft, progression, setProgression);
                                  if (added) setProgressionDraft("");
                                }}
                                className="theme-action-btn rounded-md border px-3 py-1.5 text-xs"
                              >
                                Add
                              </button>
                            </div>
                            <p className="mt-2 text-[11px] text-[color:var(--text-secondary)]">Add one or paste multiple stages separated by commas.</p>
                          </div>

                          <div id="editor-field-variation" className="rounded-lg border px-3 py-3" style={getEditorFieldStyle("variation")}>
                            <label className="mb-1 block text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Variants</label>
                            <div className="mb-3 flex flex-wrap gap-1.5">
                              {variations.length === 0 ? (
                                <span className="text-[11px] text-[color:var(--text-secondary)]">No variants yet.</span>
                              ) : variations.map((value) => (
                                <span key={value} className="inline-flex items-center gap-1 rounded-md border px-2 py-1 text-[11px]" style={{ borderColor: "color-mix(in srgb, var(--border) 78%, transparent)", color: "var(--text-primary)", backgroundColor: "color-mix(in srgb, var(--surface) 92%, black)" }}>
                                  {value}
                                  <button type="button" onClick={() => setVariations((prev) => prev.filter((item) => item !== value))} style={{ color: "var(--danger)" }}>
                                    x
                                  </button>
                                </span>
                              ))}
                            </div>
                            <div className="flex gap-2">
                              <input
                                type="text"
                                value={variationDraft}
                                onChange={(event) => setVariationDraft(event.target.value)}
                                onKeyDown={(event) => {
                                  if (event.key !== "Enter") return;
                                  event.preventDefault();
                                  const added = addDraftLabels(variationDraft, variations, setVariations);
                                  if (added) setVariationDraft("");
                                }}
                                placeholder="e.g. Wide grip, Neutral grip, Rings"
                                className={`${inputCls} !py-1.5`}
                              />
                              <button
                                type="button"
                                onClick={() => {
                                  const added = addDraftLabels(variationDraft, variations, setVariations);
                                  if (added) setVariationDraft("");
                                }}
                                className="theme-action-btn rounded-md border px-3 py-1.5 text-xs"
                              >
                                Add
                              </button>
                            </div>
                            <p className="mt-2 text-[11px] text-[color:var(--text-secondary)]">Paste multiple variants separated by commas for bulk add.</p>
                          </div>
                        </div>
                      </div>

                      {renderPanelActions()}
                    </section>
                  ) : null}

                  {activePanel === "review" ? (
                    <section className="flex flex-col overflow-hidden px-1 py-1" style={panelShellStyle}>
                      <div className="flex-1 overflow-y-auto pr-0.5">
                        <div>
                          <p className="text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Review changes</p>
                          <p className="mt-1 text-[11px] text-[color:var(--text-secondary)]">Check the full setup before saving back to the exercise library.</p>
                        </div>

                        <div className="mt-4 grid gap-3 lg:grid-cols-2">
                          <div className="rounded-lg border px-3 py-3" style={{ borderColor: "color-mix(in srgb, var(--border) 78%, transparent)", backgroundColor: "color-mix(in srgb, var(--surface) 92%, black)" }}>
                            <p className="text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Identity</p>
                            <p className="mt-2 text-sm font-semibold text-[color:var(--text-primary)]">{name.trim() || "—"}</p>
                            <p className="mt-3 text-[11px] text-[color:var(--text-secondary)]">{category} • {exerciseType}</p>
                          </div>

                          <div className="rounded-lg border px-3 py-3" style={{ borderColor: "color-mix(in srgb, var(--border) 78%, transparent)", backgroundColor: "color-mix(in srgb, var(--surface) 92%, black)" }}>
                            <p className="text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Muscle groups</p>
                            <p className="mt-2 text-[11px] text-[color:var(--text-primary)]">{muscleGroups.length > 0 ? muscleGroups.join(", ") : "None selected"}</p>
                          </div>

                          <div className="rounded-lg border px-3 py-3" style={{ borderColor: "color-mix(in srgb, var(--border) 78%, transparent)", backgroundColor: "color-mix(in srgb, var(--surface) 92%, black)" }}>
                            <p className="text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Progression</p>
                            <p className="mt-2 text-[11px] text-[color:var(--text-primary)]">{progression.length > 0 ? progression.join(" → ") : "No progression stages"}</p>
                          </div>

                          <div className="rounded-lg border px-3 py-3" style={{ borderColor: "color-mix(in srgb, var(--border) 78%, transparent)", backgroundColor: "color-mix(in srgb, var(--surface) 92%, black)" }}>
                            <p className="text-[10px] uppercase tracking-[0.1em] text-[color:var(--text-muted)]">Variants</p>
                            <p className="mt-2 text-[11px] text-[color:var(--text-primary)]">{variations.length > 0 ? variations.join(", ") : "No variants"}</p>
                          </div>
                        </div>

                        <div
                          className="mt-3 rounded-lg border px-3 py-2 text-[11px]"
                          style={{
                            borderColor: saveReady
                              ? "color-mix(in srgb, var(--forest) 35%, transparent)"
                              : "color-mix(in srgb, var(--warning) 35%, transparent)",
                            backgroundColor: saveReady
                              ? "color-mix(in srgb, var(--forest) 10%, transparent)"
                              : "color-mix(in srgb, var(--warning) 10%, transparent)",
                            color: saveReady
                              ? "color-mix(in srgb, var(--forest) 82%, white)"
                              : "color-mix(in srgb, var(--warning) 78%, white)",
                          }}
                        >
                          {saveReady
                            ? hasUnsavedChanges
                              ? "Everything is ready to save."
                              : "No pending changes right now."
                            : "Complete the required exercise details before saving."}
                        </div>
                      </div>

                      {renderPanelActions("save")}
                    </section>
                  ) : null}
                </div>
              </div>
            </div>
          </section>
        </div>
      )}
    </PageLayout>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import PageLayout from "@/components/layout/PageLayout";
import { useAuth } from "@/context/AuthContext";
import { useDisplaySettings } from "@/context/DisplaySettingsContext";
import GlowButton from "@/components/ui/GlowButton";
import { api } from "@/lib/api-client";
import { getExerciseDisplayName } from "@/lib/exercise-name";
import {
  getDefaultExerciseDbOptions,
  type ExerciseDbOptions,
} from "@/lib/exercise-db-settings";
import { notifyExerciseDbSettingsUpdated } from "@/lib/progression-events";
import type { SimpleExercise } from "@/lib/exercise-types";

type RenamePair = { from: string; to: string };
type RenameState = {
  categories: RenamePair[];
  types: RenamePair[];
  muscles: RenamePair[];
  variants: RenamePair[];
};

type ExerciseVariantRow = {
  id: string;
  name: string;
  englishName?: string;
  vietnameseName?: string;
  category: string;
  exerciseType: string;
  progression: string[];
  variants: string[];
};

function normalizeDraft(values: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];

  const capitalizeFirst = (value: string) => {
    if (!value) return value;
    return `${value.charAt(0).toUpperCase()}${value.slice(1)}`;
  };

  for (const value of values) {
    const next = capitalizeFirst(value.trim());
    if (!next) continue;
    const key = next.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(next);
  }
  return out;
}

function normalizeTypeLabel(value: string): string {
  const lower = value.trim().toLowerCase();
  if (lower === "weighted" || lower === "weight") return "Weighted";
  if (lower === "timed" || lower === "time" || lower === "hold") return "Timed";
  if (lower === "bodyweight" || lower === "bodytype" || lower === "body type" || lower === "body") return "Bodyweight";
  if (!value) return value;
  return `${value.charAt(0).toUpperCase()}${value.slice(1)}`;
}

function normalizeTypeDraft(values: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const value of values) {
    const next = normalizeTypeLabel(value.trim());
    if (!next) continue;
    const key = next.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(next);
  }
  return out;
}

function OptionListEditor({
  title,
  subtitle,
  values,
  onAdd,
  onRename,
  onRemove,
  placeholder,
}: {
  title: string;
  subtitle: string;
  values: string[];
  onAdd: (value: string) => void;
  onRename: (from: string, to: string) => void;
  onRemove: (value: string) => void;
  placeholder: string;
}) {
  const [draft, setDraft] = useState("");
  const [editingValue, setEditingValue] = useState<string | null>(null);
  const [editDraft, setEditDraft] = useState("");

  const commitRename = () => {
    if (!editingValue) return;
    onRename(editingValue, editDraft);
    setEditingValue(null);
    setEditDraft("");
  };

  return (
    <div className="border overflow-hidden" style={{ borderColor: "var(--border)", borderRadius: "2px" }}>
      <div className="px-3 py-2 border-b" style={{ borderColor: "var(--nyaa-table-grid)", backgroundColor: "var(--nyaa-table-head-bg)" }}>
        <p className="text-xs font-semibold" style={{ color: "var(--text-primary)" }}>{title}</p>
        <p className="text-[11px]" style={{ color: "var(--text-secondary)" }}>{subtitle}</p>
      </div>

      <div className="space-y-2 p-3" style={{ backgroundColor: "var(--surface)" }}>
        <div className="flex flex-wrap gap-1.5">
          {values.map((value) => (
            <span
              key={value}
              className="inline-flex items-center gap-1 text-[11px] border px-2 py-1"
              style={{ borderColor: "var(--border)", color: "var(--text-primary)", backgroundColor: "color-mix(in srgb, var(--border) 10%, transparent)", borderRadius: "2px" }}
            >
              {editingValue === value ? (
                <input
                  autoFocus
                  value={editDraft}
                  onChange={(e) => setEditDraft(e.target.value)}
                  onBlur={commitRename}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      e.preventDefault();
                      commitRename();
                    }
                    if (e.key === "Escape") {
                      e.preventDefault();
                      setEditingValue(null);
                      setEditDraft("");
                    }
                  }}
                  className="w-24 border px-1 py-0 text-[11px] outline-none"
                  style={{ borderColor: "var(--accent)", borderRadius: "2px", backgroundColor: "var(--surface)", color: "var(--text-primary)" }}
                />
              ) : (
                <button
                  type="button"
                  onClick={() => {
                    setEditingValue(value);
                    setEditDraft(value);
                  }}
                  className="text-left hover:underline"
                  style={{ color: "var(--text-primary)" }}
                  title="Click to edit"
                >
                  {value}
                </button>
              )}
              <button
                type="button"
                onClick={() => {
                  const confirmed = window.confirm(`Are you sure you want to delete \"${value}\" from ${title}?`);
                  if (!confirmed) return;
                  onRemove(value);
                }}
                className="text-[11px] px-1"
                style={{ color: "var(--danger)" }}
                aria-label={`Remove ${value}`}
              >
                x
              </button>
            </span>
          ))}
        </div>

        <div className="flex flex-col gap-2 sm:flex-row">
          <input
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              if (e.key !== "Enter") return;
              e.preventDefault();
              onAdd(draft);
              setDraft("");
            }}
            className="flex-1 border px-2 py-1.5 text-xs outline-none"
            style={{ borderColor: "var(--border)", borderRadius: "2px", backgroundColor: "var(--surface)", color: "var(--text-primary)" }}
            placeholder={placeholder}
          />
          <button
            type="button"
            onClick={() => {
              onAdd(draft);
              setDraft("");
            }}
            className="px-3 py-1.5 text-xs border transition-colors sm:w-auto"
            style={{ borderColor: "var(--accent)", color: "var(--accent)", backgroundColor: "color-mix(in srgb, var(--accent) 10%, transparent)", borderRadius: "2px" }}
          >
            Add
          </button>
        </div>
      </div>
    </div>
  );
}

function ExerciseRowLabelEditor({
  row,
  values,
  kind,
  emptyLabel,
  addPlaceholder,
  onSave,
}: {
  row: ExerciseVariantRow;
  values: string[];
  kind: "progression" | "variant";
  emptyLabel: string;
  addPlaceholder: string;
  onSave: (exerciseId: string, exerciseName: string, previousValues: string[], nextValues: string[]) => Promise<void>;
}) {
  const [draft, setDraft] = useState("");
  const [editingValue, setEditingValue] = useState<string | null>(null);
  const [editDraft, setEditDraft] = useState("");
  const [saving, setSaving] = useState(false);
  const [adding, setAdding] = useState(false);

  const normalizeValue = (value: string) => {
    const trimmed = value.trim().slice(0, 60);
    if (!trimmed) return "";
    return `${trimmed.charAt(0).toUpperCase()}${trimmed.slice(1)}`;
  };

  const dedupeValues = (list: string[]) => {
    return list.filter((value, index, all) => all.findIndex((item) => item.toLowerCase() === value.toLowerCase()) === index);
  };

  const persist = async (nextValues: string[]) => {
    const deduped = dedupeValues(nextValues);
    const before = values;
    const same = before.length === deduped.length && before.every((value, index) => value === deduped[index]);
    if (same) return;
    setSaving(true);
    try {
      await onSave(row.id, row.name, before, deduped);
      setDraft("");
      setEditingValue(null);
      setEditDraft("");
      setAdding(false);
    } finally {
      setSaving(false);
    }
  };

  const addValue = async () => {
    const next = normalizeValue(draft);
    if (!next) return;
    if (values.some((item) => item.toLowerCase() === next.toLowerCase())) {
      setDraft("");
      setAdding(false);
      return;
    }
    await persist([...values, next]);
  };

  const removeValue = async (value: string) => {
    const confirmed = window.confirm(`Are you sure you want to delete \"${value}\" from ${kind}s?`);
    if (!confirmed) return;
    await persist(values.filter((item) => item !== value));
  };

  const commitRename = async () => {
    if (!editingValue) return;
    const next = normalizeValue(editDraft);
    if (!next) {
      setEditingValue(null);
      setEditDraft("");
      return;
    }
    await persist(values.map((item) => (item === editingValue ? next : item)));
  };

  return (
    <div className="space-y-2">
      {values.length === 0 ? (
        <span className="text-[10px]" style={{ color: "var(--text-muted)" }}>{emptyLabel}</span>
      ) : (
        <div className="flex flex-wrap gap-1.5">
          {values.map((value) => (
            <span
              key={`${row.id}:${kind}:${value}`}
              className="inline-flex items-center gap-1 text-[10px] border px-1.5 py-0.5"
              style={{
                borderColor: "color-mix(in srgb, var(--accent) 28%, var(--border))",
                color: "var(--text-primary)",
                backgroundColor: "color-mix(in srgb, var(--accent) 10%, transparent)",
                borderRadius: "2px",
              }}
            >
              {editingValue === value ? (
                <input
                  autoFocus
                  value={editDraft}
                  onChange={(e) => setEditDraft(e.target.value)}
                  onBlur={() => { void commitRename(); }}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      e.preventDefault();
                      void commitRename();
                    }
                    if (e.key === "Escape") {
                      e.preventDefault();
                      setEditingValue(null);
                      setEditDraft("");
                    }
                  }}
                  className="w-24 border px-1 py-0 text-[10px] outline-none"
                  style={{ borderColor: "var(--accent)", borderRadius: "2px", backgroundColor: "var(--surface)", color: "var(--text-primary)" }}
                />
              ) : (
                <button
                  type="button"
                  onClick={() => {
                    setEditingValue(value);
                    setEditDraft(value);
                  }}
                  className="text-left hover:underline"
                  style={{ color: "var(--text-primary)" }}
                  disabled={saving}
                  title="Click to edit"
                >
                  {value}
                </button>
              )}
              <button
                type="button"
                onClick={() => { void removeValue(value); }}
                className="px-1"
                style={{ color: "var(--danger)" }}
                disabled={saving}
                aria-label={`Remove ${value}`}
              >
                x
              </button>
            </span>
          ))}
        </div>
      )}

      {adding ? (
        <div className="flex items-center gap-2">
          <input
            autoFocus
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                void addValue();
              }
              if (e.key === "Escape") {
                e.preventDefault();
                setAdding(false);
                setDraft("");
              }
            }}
            className="flex-1 border px-2 py-1.5 text-xs outline-none"
            style={{ borderColor: "var(--border)", borderRadius: "2px", backgroundColor: "var(--surface)", color: "var(--text-primary)" }}
            placeholder={addPlaceholder}
            disabled={saving}
          />
          <button
            type="button"
            onClick={() => { void addValue(); }}
            className="px-2 py-1.5 text-xs border transition-colors"
            style={{ borderColor: "var(--accent)", color: "var(--accent)", backgroundColor: "color-mix(in srgb, var(--accent) 10%, transparent)", borderRadius: "2px" }}
            disabled={saving}
          >
            {saving ? "Saving..." : "Add"}
          </button>
          <button
            type="button"
            onClick={() => {
              setAdding(false);
              setDraft("");
            }}
            className="px-2 py-1.5 text-xs border"
            style={{ borderColor: "var(--border)", color: "var(--text-secondary)", backgroundColor: "var(--surface)", borderRadius: "2px" }}
            disabled={saving}
          >
            Cancel
          </button>
        </div>
      ) : (
        <div className="flex justify-end">
          <button
            type="button"
            onClick={() => setAdding(true)}
            className="inline-flex items-center justify-center w-5 h-5 text-xs border"
            style={{ borderColor: "var(--accent)", color: "var(--accent)", backgroundColor: "color-mix(in srgb, var(--accent) 10%, transparent)", borderRadius: "2px" }}
            title={`Add ${kind}`}
            disabled={saving}
          >
            +
          </button>
        </div>
      )}

      <p className="text-[10px]" style={{ color: "var(--text-muted)" }}>
        Click a label to rename it.
      </p>
    </div>
  );
}

export function ExerciseDbSettingsPanel({ embedded = false }: { embedded?: boolean } = {}) {
  const router = useRouter();
  const { user } = useAuth();
  const { settings } = useDisplaySettings();
  const defaults = useMemo(() => getDefaultExerciseDbOptions(), []);

  const [categories, setCategories] = useState<string[]>(defaults.categories);
  const [types, setTypes] = useState<string[]>(defaults.types);
  const [muscles, setMuscles] = useState<string[]>(defaults.muscles);
  const [variants, setVariants] = useState<string[]>(defaults.variants);
  const [exerciseVariantRows, setExerciseVariantRows] = useState<ExerciseVariantRow[]>([]);
  const [variantCategoryFilter, setVariantCategoryFilter] = useState("");
  const [variantTypeFilter, setVariantTypeFilter] = useState("");
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState<string>("");
  const [initialOptions, setInitialOptions] = useState<ExerciseDbOptions>(defaults);
  const [pendingRenames, setPendingRenames] = useState<RenameState>({
    categories: [],
    types: [],
    muscles: [],
    variants: [],
  });

  const addUnique = useCallback((values: string[], value: string) => {
    const raw = value.trim().slice(0, 60);
    const next = raw ? `${raw.charAt(0).toUpperCase()}${raw.slice(1)}` : "";
    if (!next) return values;
    if (values.some((item) => item.toLowerCase() === next.toLowerCase())) return values;
    return [...values, next];
  }, []);

  const addTypeValue = useCallback((value: string) => {
    const normalized = normalizeTypeLabel(value.trim());
    if (!normalized) return;
    setTypes((prev) => addUnique(prev, normalized));
  }, [addUnique]);

  const updateExerciseMetadata = useCallback(async (
    exerciseId: string,
    exerciseName: string,
    previousProgression: string[],
    nextProgression: string[],
    previousVariants: string[],
    nextVariants: string[],
  ) => {
    const previousRows = exerciseVariantRows;
    setExerciseVariantRows((prev) => prev.map((row) => row.id === exerciseId
      ? { ...row, progression: nextProgression, variants: nextVariants }
      : row));

    try {
      await api.patch(`/api/exercise-library/${exerciseId}`, {
        progression: nextProgression,
        variations: nextVariants,
      });

      const beforeProgression = previousProgression.join(", ") || "—";
      const afterProgression = nextProgression.join(", ") || "—";
      if (beforeProgression !== afterProgression) {
        await api.post("/api/exercise-library/edit-history", {
          exerciseId,
          exerciseName,
          field: "Progression",
          beforeValue: beforeProgression,
          afterValue: afterProgression,
        });
      }

      const beforeValue = previousVariants.join(", ") || "—";
      const afterValue = nextVariants.join(", ") || "—";
      if (beforeValue !== afterValue) {
        await api.post("/api/exercise-library/edit-history", {
          exerciseId,
          exerciseName,
          field: "Variants",
          beforeValue,
          afterValue,
        });
      }
    } catch (error) {
      setExerciseVariantRows(previousRows);
      setMessage(`Failed to update progression/variants for ${exerciseName}.`);
      throw error;
    }
  }, [exerciseVariantRows]);

  const filteredExerciseVariantRows = useMemo(() => {
    return exerciseVariantRows.filter((row) => {
      if (variantCategoryFilter && row.category !== variantCategoryFilter) return false;
      if (variantTypeFilter && row.exerciseType !== variantTypeFilter) return false;
      return true;
    });
  }, [exerciseVariantRows, variantCategoryFilter, variantTypeFilter]);

  const resolveRowDisplayName = useCallback((row: ExerciseVariantRow) => {
    return getExerciseDisplayName(
      {
        name: row.englishName || row.name,
        wuxiaName: row.vietnameseName || "",
        englishName: row.englishName,
        vietnameseName: row.vietnameseName,
      },
      settings.terminologyMode,
      settings.showExerciseForeignLanguage,
    );
  }, [settings.terminologyMode, settings.showExerciseForeignLanguage]);

  const hasUnsavedChanges = useMemo(() => {
    const listEquals = (a: string[], b: string[]) => {
      if (a.length !== b.length) return false;
      return a.every((value, index) => value === b[index]);
    };

    const nextOptions: ExerciseDbOptions = {
      categories: normalizeDraft(categories),
      types: normalizeTypeDraft(types),
      muscles: normalizeDraft(muscles),
      variants: normalizeDraft(variants),
    };

    const renameCount = pendingRenames.categories.length
      + pendingRenames.types.length
      + pendingRenames.muscles.length
      + pendingRenames.variants.length;

    return !listEquals(nextOptions.categories, initialOptions.categories)
      || !listEquals(nextOptions.types, initialOptions.types)
      || !listEquals(nextOptions.muscles, initialOptions.muscles)
      || !listEquals(nextOptions.variants, initialOptions.variants)
      || renameCount > 0;
  }, [categories, types, muscles, variants, pendingRenames, initialOptions]);

  useEffect(() => {
    const load = async () => {
      try {
        const [data, exerciseData] = await Promise.all([
          api.get<{ options?: ExerciseDbOptions }>("/api/exercise-library/db-settings"),
          api.get<{ exercises?: SimpleExercise[] }>("/api/exercise-library"),
        ]);
        const options = data.options ?? defaults;
        const normalizedInitial: ExerciseDbOptions = {
          categories: normalizeDraft(options.categories),
          types: normalizeTypeDraft(options.types),
          muscles: normalizeDraft(options.muscles),
          variants: normalizeDraft(options.variants),
        };
        setCategories(options.categories);
        setTypes(normalizeTypeDraft(options.types));
        setMuscles(options.muscles);
        setVariants(options.variants);
        setInitialOptions(normalizedInitial);
        setExerciseVariantRows(
          (exerciseData.exercises ?? []).map((exercise) => ({
            id: exercise.id,
            name: exercise.name,
            englishName: exercise.englishName,
            vietnameseName: exercise.vietnameseName,
            category: exercise.category,
            exerciseType: normalizeTypeLabel(exercise.exerciseType),
            progression: (exercise.progression ?? []).filter(Boolean),
            variants: (exercise.variations ?? []).map((item) => item.name).filter(Boolean),
          })),
        );
        setPendingRenames({ categories: [], types: [], muscles: [], variants: [] });
      } catch (error) {
        console.error("Failed to load exercise DB settings:", error);
        setMessage("Unable to load DB settings. Using defaults.");
      } finally {
        setLoading(false);
      }
    };
    void load();
  }, [defaults]);

  const handleBack = useCallback(() => {
    if (hasUnsavedChanges) {
      const confirmed = window.confirm("You have unsaved DB setting changes. Leave without saving?");
      if (!confirmed) return;
    }
    router.push("/dashboard/train?library=1");
  }, [hasUnsavedChanges, router]);

  const registerRename = useCallback((key: keyof RenameState, from: string, to: string) => {
    const src = from.trim();
    const dest = to.trim();
    if (!src || !dest) return;
    if (src.toLowerCase() === dest.toLowerCase()) return;
    setPendingRenames((prev) => ({
      ...prev,
      [key]: [...prev[key], { from: src, to: dest }],
    }));
  }, []);

  const save = async () => {
    setMessage("");
    setSaving(true);
    try {
      const previousData = await api.get<{ options?: ExerciseDbOptions }>("/api/exercise-library/db-settings");
      const previous = previousData.options ?? defaults;

      const next = {
        categories: normalizeDraft(categories),
        types: normalizeTypeDraft(types),
        muscles: normalizeDraft(muscles),
        variants: normalizeDraft(variants),
      };

      const payload: ExerciseDbOptions = {
        categories: next.categories,
        types: next.types,
        muscles: next.muscles,
        variants: next.variants,
      };

      if (payload.categories.length === 0) {
        setMessage("Add at least one category.");
        setSaving(false);
        return;
      }
      if (payload.types.length === 0) {
        setMessage("Enable at least one type.");
        setSaving(false);
        return;
      }
      if (payload.muscles.length === 0) {
        setMessage("Add at least one muscle group.");
        setSaving(false);
        return;
      }

      await api.put("/api/exercise-library/db-settings", { options: payload, renames: pendingRenames });

      const formatValue = (values: string[]) => {
        const raw = values.join(", ") || "—";
        return raw.length > 500 ? `${raw.slice(0, 497)}...` : raw;
      };

      const changes: Array<{ field: string; beforeValue: string; afterValue: string }> = [];
      if (formatValue(previous.categories) !== formatValue(payload.categories)) {
        changes.push({
          field: "DB Categories",
          beforeValue: formatValue(previous.categories),
          afterValue: formatValue(payload.categories),
        });
      }
      if (formatValue(previous.types) !== formatValue(payload.types)) {
        changes.push({
          field: "DB Types",
          beforeValue: formatValue(previous.types),
          afterValue: formatValue(payload.types),
        });
      }
      if (formatValue(previous.muscles) !== formatValue(payload.muscles)) {
        changes.push({
          field: "DB Muscles",
          beforeValue: formatValue(previous.muscles),
          afterValue: formatValue(payload.muscles),
        });
      }
      if (formatValue(previous.variants) !== formatValue(payload.variants)) {
        changes.push({
          field: "DB Variants",
          beforeValue: formatValue(previous.variants),
          afterValue: formatValue(payload.variants),
        });
      }

      for (const change of changes) {
        await api.post("/api/exercise-library/edit-history", {
          exerciseId: "exercise-db-settings",
          exerciseName: "Exercise DB Settings",
          field: change.field,
          beforeValue: change.beforeValue,
          afterValue: change.afterValue,
        });
      }

      notifyExerciseDbSettingsUpdated();
      setMessage("DB settings saved.");
      setInitialOptions(payload);
      setPendingRenames({ categories: [], types: [], muscles: [], variants: [] });
    } catch (error) {
      console.error("Failed to save DB settings:", error);
      setMessage("Failed to save DB settings.");
    } finally {
      setSaving(false);
    }
  };

  const content = (
      <div className="nyaa-history-page space-y-2 px-0 py-2 sm:py-3">
        {loading ? (
          <div className="border px-3 py-8 text-sm text-center" style={{ borderColor: "var(--border)", borderRadius: "2px", backgroundColor: "var(--surface)", color: "var(--text-muted)" }}>
            Loading settings...
          </div>
        ) : (
          <div className="nyaa-history-table-shell space-y-3">
            <OptionListEditor
              title="Categories"
              subtitle="Shown when editing Category from Exercise DB"
              values={categories}
              onAdd={(value) => setCategories((prev) => addUnique(prev, value))}
              onRename={(from, to) => {
                setCategories((prev) => prev.map((item) => item === from ? to : item));
                registerRename("categories", from, to);
              }}
              onRemove={(value) => setCategories((prev) => prev.filter((item) => item !== value))}
              placeholder="Add category"
            />

            <OptionListEditor
              title="Types"
              subtitle="Shown when editing Type from Exercise DB"
              values={types}
              onAdd={(value) => addTypeValue(value)}
              onRename={(from, to) => {
                const normalizedTo = normalizeTypeLabel(to);
                setTypes((prev) => prev.map((item) => item === from ? normalizedTo : item));
                registerRename("types", from, normalizedTo);
              }}
              onRemove={(value) => setTypes((prev) => prev.filter((item) => item !== value))}
              placeholder="Add type"
            />

            <OptionListEditor
              title="Muscle Groups"
              subtitle="Shown when editing Muscles from Exercise DB"
              values={muscles}
              onAdd={(value) => setMuscles((prev) => addUnique(prev, value))}
              onRename={(from, to) => {
                setMuscles((prev) => prev.map((item) => item === from ? to : item));
                registerRename("muscles", from, to);
              }}
              onRemove={(value) => setMuscles((prev) => prev.filter((item) => item !== value))}
              placeholder="Add muscle group"
            />

            <div className="border overflow-hidden" style={{ borderColor: "var(--border)", borderRadius: "2px" }}>
              <div className="px-3 py-2 border-b" style={{ borderColor: "var(--nyaa-table-grid)", backgroundColor: "var(--nyaa-table-head-bg)" }}>
                <p className="text-xs font-semibold" style={{ color: "var(--text-primary)" }}>Exercise Progressions and Variants</p>
                <p className="text-[11px]" style={{ color: "var(--text-secondary)" }}>Review progression tracks and manage each exercise's unique variants here.</p>
              </div>
              <div className="flex flex-wrap gap-2 px-3 py-2 border-b" style={{ borderColor: "var(--border)", backgroundColor: "var(--surface)" }}>
                <select
                  value={variantCategoryFilter}
                  onChange={(e) => setVariantCategoryFilter(e.target.value)}
                  className="w-full sm:w-auto px-2 py-1.5 text-[11px] outline-none border transition-colors cursor-pointer hover:border-accent/60 hover:bg-surface-hover focus:border-accent/70"
                  style={{ borderColor: "var(--border)", color: "var(--text-primary)", backgroundColor: "var(--surface)", borderRadius: "2px" }}
                >
                  <option value="">All Categories</option>
                  {categories.map((category) => (
                    <option key={category} value={category}>{category}</option>
                  ))}
                </select>
                <select
                  value={variantTypeFilter}
                  onChange={(e) => setVariantTypeFilter(e.target.value)}
                  className="w-full sm:w-auto px-2 py-1.5 text-[11px] outline-none border transition-colors cursor-pointer hover:border-accent/60 hover:bg-surface-hover focus:border-accent/70"
                  style={{ borderColor: "var(--border)", color: "var(--text-primary)", backgroundColor: "var(--surface)", borderRadius: "2px" }}
                >
                  <option value="">All Types</option>
                  {types.map((type) => (
                    <option key={type} value={type}>{type}</option>
                  ))}
                </select>
              </div>
              <div className="space-y-2 p-2" style={{ backgroundColor: "var(--surface)" }}>
                {filteredExerciseVariantRows.length === 0 ? (
                  <div className="rounded border px-3 py-6 text-center text-xs" style={{ borderColor: "var(--border)", color: "var(--text-muted)" }}>
                    No exercises found.
                  </div>
                ) : (
                  filteredExerciseVariantRows.map((row) => (
                    <div key={row.id} className="rounded border p-2 space-y-2" style={{ borderColor: "var(--border)", backgroundColor: "color-mix(in srgb, var(--surface) 95%, var(--border))" }}>
                      <div className="flex flex-wrap items-center gap-1.5">
                        <span className="inline-flex items-center justify-center px-1.5 py-0.5 text-[10px]" style={{ borderRadius: "2px", color: "var(--text-secondary)", backgroundColor: "color-mix(in srgb, var(--border) 10%, transparent)" }}>
                          {row.category}
                        </span>
                        <span className="inline-flex items-center justify-center px-1.5 py-0.5 text-[10px]" style={{ borderRadius: "2px", color: "var(--text-secondary)", backgroundColor: "color-mix(in srgb, var(--border) 10%, transparent)" }}>
                          {row.exerciseType}
                        </span>
                      </div>
                      <p className="text-sm font-medium" style={{ color: "var(--text-primary)" }}>{resolveRowDisplayName(row)}</p>

                      <div className="rounded border p-2" style={{ borderColor: "var(--border)" }}>
                        <p className="mb-1 text-[10px] font-semibold uppercase" style={{ color: "var(--text-secondary)" }}>Progression</p>
                        <ExerciseRowLabelEditor
                          row={row}
                          values={row.progression}
                          kind="progression"
                          emptyLabel="No progression yet"
                          addPlaceholder="Add progression"
                          onSave={(exerciseId, exerciseName, previousValues, nextValues) => updateExerciseMetadata(
                            exerciseId,
                            exerciseName,
                            previousValues,
                            nextValues,
                            row.variants,
                            row.variants,
                          )}
                        />
                      </div>

                      <div className="rounded border p-2" style={{ borderColor: "var(--border)" }}>
                        <p className="mb-1 text-[10px] font-semibold uppercase" style={{ color: "var(--text-secondary)" }}>Variants</p>
                        <ExerciseRowLabelEditor
                          row={row}
                          values={row.variants}
                          kind="variant"
                          emptyLabel="No variants yet"
                          addPlaceholder="Add variant"
                          onSave={(exerciseId, exerciseName, previousValues, nextValues) => updateExerciseMetadata(
                            exerciseId,
                            exerciseName,
                            row.progression,
                            row.progression,
                            previousValues,
                            nextValues,
                          )}
                        />
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>

            {message && (
              <p className="text-xs" style={{ color: message.includes("saved") ? "var(--state-success)" : "var(--danger)" }}>
                {message}
              </p>
            )}

            {!embedded && (
              <div className="flex items-center justify-end pt-1">
                <button
                  type="button"
                  onClick={handleBack}
                  className="w-full sm:w-auto px-3 py-1.5 text-xs border"
                  style={{ borderColor: "var(--border)", borderRadius: "2px", color: "var(--text-secondary)", backgroundColor: "var(--surface)" }}
                >
                  Back to Exercise DB
                </button>
              </div>
            )}

            {hasUnsavedChanges && (
              <div
                className="border p-3 flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"
                style={{ borderColor: "color-mix(in srgb, var(--accent) 38%, var(--border))", borderRadius: "2px", backgroundColor: "color-mix(in srgb, var(--accent) 8%, var(--surface))" }}
              >
                <div>
                  <p className="text-xs font-semibold" style={{ color: "var(--text-primary)" }}>Unsaved changes detected</p>
                  <p className="text-[11px]" style={{ color: "var(--text-secondary)" }}>Review your edits and save to apply DB setting updates.</p>
                </div>
                <div className="flex w-full flex-col gap-2 sm:w-auto sm:flex-row sm:items-center sm:justify-end">
                  <button
                    type="button"
                    onClick={() => {
                      setCategories(initialOptions.categories);
                      setTypes(initialOptions.types);
                      setMuscles(initialOptions.muscles);
                      setVariants(initialOptions.variants);
                      setPendingRenames({ categories: [], types: [], muscles: [], variants: [] });
                      setMessage("Changes discarded.");
                    }}
                    className="w-full sm:w-auto px-3 py-1.5 text-xs border"
                    style={{ borderColor: "var(--border)", borderRadius: "2px", color: "var(--text-secondary)", backgroundColor: "var(--surface)" }}
                    disabled={saving}
                  >
                    Discard
                  </button>
                  <div className="w-full sm:w-auto">
                    <GlowButton onClick={save} variant="jade" size="sm" disabled={saving} className="w-full sm:w-auto">
                      {saving ? "Saving..." : "Save DB Settings"}
                    </GlowButton>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
  );

  if (!user || user.role !== "admin") {
    return (
      <PageLayout title="Exercise DB Settings" subtitle="Manage category, type, muscle, progression, and variant options" mobileContentPaddingClass="p-2 pb-24">
        <div className="flex flex-col items-center justify-center py-20 space-y-4">
          <div className="text-5xl opacity-50">🔒</div>
          <h3 className="text-lg font-semibold text-crimson-light">Access Restricted</h3>
          <p className="text-sm text-mist-dark text-center max-w-md">
            Exercise DB settings are available only to admins.
          </p>
          <GlowButton variant="ghost" size="sm" onClick={() => router.push("/dashboard/overview")}>
            ← Return to Overview
          </GlowButton>
        </div>
      </PageLayout>
    );
  }

  if (embedded) {
    return content;
  }

  return (
    <PageLayout title="Exercise DB Settings" subtitle="Manage category, type, muscle, progression, and variant options" mobileContentPaddingClass="p-2 pb-24">
      {content}
    </PageLayout>
  );
}

export default function ExerciseDbSettingsPage() {
  return <ExerciseDbSettingsPanel />;
