"use client";

import { useRouter } from "next/navigation";
import { useState, useEffect, useCallback } from "react";
import { AnimatePresence } from "framer-motion";
import { useAuth } from "@/context/AuthContext";
import { useOnboarding } from "@/hooks/useOnboarding";
import { getCopy } from "@/lib/copy";
import type { LanguageMode } from "@/lib/language";
import OnboardingProgress from "./components/OnboardingProgress";
import WelcomeStep from "./components/WelcomeStep";
import AssessmentStep from "./components/AssessmentStep";
import TierAssignmentStep from "./components/TierAssignmentStep";
import FirstCheckinStep from "./components/FirstCheckinStep";
import TourStep from "./components/TourStep";

const DISPLAY_SETTINGS_STORAGE_KEY = "cultivateos-display-settings";
const TOTAL_STEPS = 5;

function getStoredLanguage(): LanguageMode {
  if (typeof window === "undefined") return "english";
  try {
    const raw = window.localStorage.getItem(DISPLAY_SETTINGS_STORAGE_KEY);
    if (!raw) return "english";
    const parsed = JSON.parse(raw) as { languageMode?: LanguageMode };
    return parsed.languageMode === "vietnamese" ? "vietnamese" : "english";
  } catch {
    return "english";
  }
}

export default function OnboardingPage() {
  const router = useRouter();
  const { user, login } = useAuth();
  const onboarding = useOnboarding();
  const [currentStep, setCurrentStep] = useState(0);
  const [recommendedTier, setRecommendedTier] = useState("mortal");
  const [showSkipConfirm, setShowSkipConfirm] = useState(false);
  const [lang] = useState<LanguageMode>(getStoredLanguage);

  const copy = getCopy(lang);

  // Resume from last saved step
  useEffect(() => {
    if (!onboarding.loading && onboarding.step > 0 && onboarding.step < TOTAL_STEPS) {
      setCurrentStep(onboarding.step);
    }
    if (onboarding.profile?.recommendedTier) {
      setRecommendedTier(onboarding.profile.recommendedTier);
    }
  }, [onboarding.loading, onboarding.step, onboarding.profile]);

  // If onboarding already done, redirect to dashboard
  useEffect(() => {
    if (!onboarding.loading && (onboarding.completed || onboarding.skipped)) {
      router.replace("/dashboard");
    }
  }, [onboarding.loading, onboarding.completed, onboarding.skipped, router]);

  const goToStep = useCallback(
    (step: number) => {
      setCurrentStep(step);
      onboarding.setStep(step);
    },
    [onboarding]
  );

  const handleAssessmentComplete = useCallback(
    async (data: {
      fitnessBackground: string;
      primaryGoal: string;
      trainingDaysPerWeek: number;
      benchmarkAnswers: Record<string, string>;
    }) => {
      const result = await onboarding.saveAssessment(data);
      if (result) {
        setRecommendedTier(result.recommendedTier);
      }
      goToStep(2);
    },
    [onboarding, goToStep]
  );

  const handleTierConfirm = useCallback(
    async (tier: string) => {
      // Update assessment with selected tier if different
      if (onboarding.profile) {
        await onboarding.saveAssessment({
          fitnessBackground: onboarding.profile.fitnessBackground ?? "new",
          primaryGoal: onboarding.profile.primaryGoal ?? "consistency",
          trainingDaysPerWeek: onboarding.profile.trainingDaysPerWeek ?? 3,
          benchmarkAnswers: onboarding.profile.assessmentAnswers ?? {},
          selectedTier: tier,
        });
      }
      goToStep(3);
    },
    [onboarding, goToStep]
  );

  const handleComplete = useCallback(async () => {
    await onboarding.complete();
    // Update auth context so dashboard layout won't redirect back
    if (user) {
      login({ ...user, onboardingCompleted: true, onboardingStep: 5 });
    }
    router.replace("/dashboard");
  }, [onboarding, user, login, router]);

  const handleSkip = useCallback(async () => {
    await onboarding.skip();
    // Update auth context so dashboard layout won't redirect back
    if (user) {
      login({ ...user, onboardingSkipped: true, onboardingStep: 5 });
    }
    router.replace("/dashboard");
  }, [onboarding, user, login, router]);

  if (onboarding.loading) {
    return (
      <div className="safe-area-shell min-h-app flex items-center justify-center">
        <p className="text-mist-mid text-sm animate-pulse">Loading…</p>
      </div>
    );
  }

  return (
    <div className="safe-area-shell min-h-app bg-void-black relative overflow-x-hidden">
      {/* Background effects */}
      <div className="absolute inset-0 bg-gradient-to-br from-void-black via-ink-deep to-jade-glow/10 pointer-events-none" />
      <div className="absolute top-0 left-1/4 w-80 h-80 bg-jade-deep/10 rounded-full blur-xl pointer-events-none" />

      <div className="relative z-10 max-w-lg mx-auto">
        {/* Progress bar (hidden on welcome step) */}
        {currentStep > 0 && (
          <OnboardingProgress
            currentStep={currentStep}
            totalSteps={TOTAL_STEPS}
            stepLabel={copy.onboarding.progress.step}
            ofLabel={copy.onboarding.progress.of}
          />
        )}

        {/* Skip button */}
        {currentStep > 0 && (
          <div className="flex justify-end px-6 pt-2">
            <button
              onClick={() => setShowSkipConfirm(true)}
              className="text-xs text-mist-dark hover:text-mist-mid transition-colors"
            >
              Skip
            </button>
          </div>
        )}

        {/* Steps */}
        <AnimatePresence mode="wait">
          {currentStep === 0 && (
            <WelcomeStep
              key="welcome"
              copy={copy.onboarding.welcome}
              onContinue={() => goToStep(1)}
            />
          )}
          {currentStep === 1 && (
            <AssessmentStep
              key="assessment"
              copy={copy.onboarding.assessment}
              onContinue={handleAssessmentComplete}
              onBack={() => goToStep(0)}
              initialData={onboarding.profile}
            />
          )}
          {currentStep === 2 && (
            <TierAssignmentStep
              key="tier"
              copy={copy.onboarding.tierAssignment}
              recommendedTier={recommendedTier}
              onContinue={handleTierConfirm}
              onBack={() => goToStep(1)}
            />
          )}
          {currentStep === 3 && (
            <FirstCheckinStep
              key="checkin"
              copy={copy.onboarding.firstCheckin}
              onContinue={() => goToStep(4)}
              onBack={() => goToStep(2)}
            />
          )}
          {currentStep === 4 && (
            <TourStep
              key="tour"
              copy={copy.onboarding.tour}
              onComplete={handleComplete}
              onBack={() => goToStep(3)}
            />
          )}
        </AnimatePresence>
      </div>

      {/* Skip confirmation modal */}
      <AnimatePresence>
        {showSkipConfirm && (
          <div
            className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/60"
            onClick={() => setShowSkipConfirm(false)}
          >
            <div
              className="w-full max-w-sm p-6 rounded-2xl bg-ink-deep border border-ink-light/30"
              onClick={(e) => e.stopPropagation()}
            >
              <h3 className="text-lg font-bold text-cloud-white mb-2">
                {copy.onboarding.skipConfirm.title}
              </h3>
              <p className="text-mist-mid text-sm mb-6">
                {copy.onboarding.skipConfirm.message}
              </p>
              <div className="flex gap-3">
                <button
                  onClick={() => setShowSkipConfirm(false)}
                  className="flex-1 py-2.5 rounded-xl border border-ink-light text-mist-light
                             hover:bg-ink-mid transition-colors text-sm"
                >
                  {copy.onboarding.skipConfirm.cancel}
                </button>
                <button
                  onClick={handleSkip}
                  className="flex-1 py-2.5 rounded-xl bg-crimson-deep/30 border border-crimson/30
                             text-crimson-light hover:bg-crimson/20 transition-colors text-sm"
                >
                  {copy.onboarding.skipConfirm.confirm}
                </button>
              </div>
            </div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { motion } from "framer-motion";
import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import GlowButton from "@/components/ui/GlowButton";
import GlowInput from "@/components/ui/GlowInput";
import { useAuth } from "@/context/AuthContext";
import { THEME_CLASS_NAMES } from "@/lib/config";
import ConnectivityBanner from "@/components/system/ConnectivityBanner";
import type { LanguageMode } from "@/lib/language";
import { translateEnglishToLanguage } from "@/lib/language";

export default function LoginPage() {
  const DISPLAY_SETTINGS_STORAGE_KEY = "cultivateos-display-settings";
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [languageMode, setLanguageMode] = useState<LanguageMode>("english");
  const router = useRouter();
  const { login, isAuthenticated, isLoading } = useAuth();

  // Redirect already-authenticated users away from the login page
  // (e.g. when the browser back button is used after login)
  useEffect(() => {
    if (!isLoading && isAuthenticated) {
      router.replace("/dashboard");
    }
  }, [isLoading, isAuthenticated, router]);

  // Apply the saved palette while keeping the same shared canvas.
  useEffect(() => {
    try {
      const savedTheme = localStorage.getItem("cultivation-theme-style");
      const appliedTheme = savedTheme && THEME_CLASS_NAMES.includes(savedTheme as (typeof THEME_CLASS_NAMES)[number])
        ? savedTheme
        : "discord";

      document.documentElement.classList.remove(...THEME_CLASS_NAMES);
      document.documentElement.classList.add(appliedTheme);
      localStorage.setItem("cultivation-theme-style", appliedTheme);

      const rawDisplaySettings = localStorage.getItem(DISPLAY_SETTINGS_STORAGE_KEY);
      if (rawDisplaySettings) {
        const parsed = JSON.parse(rawDisplaySettings) as { languageMode?: LanguageMode };
        if (parsed.languageMode === "english" || parsed.languageMode === "vietnamese") {
          setLanguageMode(parsed.languageMode);
        }
      }
    } catch {}
  }, []);

  const persistLanguageMode = (mode: LanguageMode) => {
    setLanguageMode(mode);
    try {
      const raw = localStorage.getItem(DISPLAY_SETTINGS_STORAGE_KEY);
      const current = raw ? (JSON.parse(raw) as Record<string, unknown>) : {};
      const next = {
        ...current,
        languageMode: mode,
        ...(mode === "vietnamese" ? { showExerciseForeignLanguage: true } : {}),
      };
      localStorage.setItem(DISPLAY_SETTINGS_STORAGE_KEY, JSON.stringify(next));
    } catch {
      // Ignore storage errors.
    }
  };

  const lt = (englishText: string) => translateEnglishToLanguage(englishText, languageMode);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ username, password, rememberMe }),
      });

      const data = await res.json();

      if (!res.ok) {
        const msg = typeof data.error === "string" ? data.error : data.error?.message ?? "An error occurred";
        setError(msg);
        return;
      }

      // Set user in auth context (cookie is set by server)
      // API returns { success, data: { user } } via apiSuccess wrapper
      const userData = data.data?.user ?? data.user;
      if (userData) {
        login(userData, rememberMe);
      }

      if (userData && !userData.onboardingCompleted && !userData.onboardingSkipped) {
        router.replace("/onboarding");
      } else {
        router.replace("/dashboard");
      }
    } catch {
      setError("Cannot connect to server/database. Please verify the server URL and your network connection.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="safe-area-shell min-h-app flex items-center justify-center relative overflow-hidden">
      <div className="absolute top-0 inset-x-0 z-20">
        <ConnectivityBanner />
      </div>
      {/* Background mist layers — forced dark regardless of theme */}
      <div className="absolute inset-0 login-atmosphere" />
      <div className="absolute inset-0 login-orbs">
        <div
          className="absolute top-0 left-1/4 w-96 h-96 rounded-full blur-3xl animate-glow-pulse"
        />
        <div
          className="absolute bottom-1/4 right-1/4 w-80 h-80 rounded-full blur-3xl animate-glow-pulse"
          style={{ animationDelay: "1.5s" }}
        />
        <div
          className="absolute top-1/3 right-1/3 w-64 h-64 rounded-full blur-3xl animate-glow-pulse"
          style={{ animationDelay: "3s" }}
        />
      </div>

      {/* Floating particles */}
      {[...Array(6)].map((_, i) => {
        // Use deterministic values based on index to avoid hydration mismatch
        const randomSeed = (i * 12321) % 100;
        const topOffset = 60 + (randomSeed % 20);
        const xOffset = (randomSeed % 40) - 20;
        const duration = 4 + (randomSeed % 3);

        return (
          <motion.div
            key={i}
            className="absolute w-1 h-1 rounded-full login-particle"
            animate={{
              y: [0, -100, 0],
              x: [0, xOffset, 0],
              opacity: [0, 0.8, 0],
            }}
            transition={{
              duration: duration,
              repeat: Infinity,
              delay: i * 0.8,
            }}
            style={{
              left: `${15 + i * 14}%`,
              top: `${topOffset}%`,
            }}
          />
        );
      })}


      {/* Login Card */}
      <motion.div
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8, ease: "easeOut" }}
        className="relative z-10 w-full max-w-md mx-4"
      >
        <div className="login-panel rounded-2xl p-8 glow-subtle">

          {/* Title - bilingual */}
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="text-center mb-8"
          >
            <h1 className="text-3xl font-bold text-jade-light mb-1 tracking-wider">
              修炼之路
            </h1>
            <p className="text-xs text-mist-mid tracking-[0.3em] uppercase">
              Path of Cultivation
            </p>
            <div className="mt-4 w-16 h-px bg-gradient-to-r from-transparent via-jade-light to-transparent mx-auto" />
          </motion.div>

          {/* Decorative subtitle */}
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.5 }}
            className="text-center text-mist-dark text-xs mb-6 italic"
          >
            欢迎回来，修士 — Welcome back, cultivator
          </motion.p>

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-4">
            <motion.div
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.4 }}
            >
              <GlowInput
                label={`道号 · ${lt("Dao Name")}`}
                placeholder={lt("Enter your cultivator name")}
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                required
              />
            </motion.div>


            <motion.div
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.5 }}
            >
              <div className="space-y-1">
                <label className="block text-xs text-mist-light tracking-wider uppercase">
                  密码 · {lt("Secret Art")}
                </label>
                <div className="relative">
                  <input
                    type={showPassword ? "text" : "password"}
                    placeholder={lt("Enter your secret art")}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    className="w-full bg-ink-dark border border-ink-light rounded-lg px-3 py-2 pr-9 text-sm text-cloud-white placeholder:text-mist-dark outline-none transition-all duration-300 focus:border-jade-glow focus:shadow-[var(--glow-jade)]"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-2.5 top-1/2 -translate-y-1/2 text-mist-dark hover:text-mist-light transition-colors"
                    tabIndex={-1}
                    aria-label={showPassword ? lt("Hide password") : lt("Show password")}
                  >
                    {showPassword ? (
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.878 9.878L3 3m6.878 6.878L21 21" />
                      </svg>
                    ) : (
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                      </svg>
                    )}
                  </button>
                </div>
              </div>
            </motion.div>

            {/* Login options */}
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.55 }}
              className="space-y-2"
            >
              <div className="flex items-center gap-2">
                <input
                  type="checkbox"
                  id="rememberMe"
                  checked={rememberMe}
                  onChange={(e) => setRememberMe(e.target.checked)}
                  className="w-3.5 h-3.5 rounded border-ink-light bg-ink-dark accent-jade-glow cursor-pointer"
                />
                <label htmlFor="rememberMe" className="text-xs text-mist-mid cursor-pointer select-none">
                  记住我 · {lt("Remember Me")}
                </label>
              </div>
            </motion.div>

            {error && (
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="text-crimson-light text-xs text-center"
              >
                {error}
              </motion.p>
            )}

            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.6 }}
              className="pt-2"
            >
              <GlowButton
                type="submit"
                variant="jade"
                size="lg"
                glow
                className="w-full !border-jade-glow/80 hover:!border-jade-light"
                style={{ backgroundColor: 'var(--jade-glow)', color: '#ffffff' }}
                disabled={loading}
              >
                {loading
                  ? lt("Channeling Qi...")
                  : `${lt("Enter the Sect")} 进入宗门`}
              </GlowButton>
            </motion.div>

            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.64 }}
              className="flex items-center justify-center gap-2"
            >
              <button
                type="button"
                onClick={() => persistLanguageMode("english")}
                className="rounded border px-2 py-1 text-[10px] login-lang-btn"
                style={{
                  borderColor: languageMode === "english" ? "var(--jade-glow)" : "rgba(60, 70, 90, 0.5)",
                  color: languageMode === "english" ? "var(--jade-glow)" : "#9eaab6",
                  backgroundColor: "rgba(10, 14, 22, 0.5)",
                }}
              >
                English
              </button>
              <button
                type="button"
                onClick={() => persistLanguageMode("vietnamese")}
                className="rounded border px-2 py-1 text-[10px] login-lang-btn"
                style={{
                  borderColor: languageMode === "vietnamese" ? "var(--jade-glow)" : "rgba(60, 70, 90, 0.5)",
                  color: languageMode === "vietnamese" ? "var(--jade-glow)" : "#9eaab6",
                  backgroundColor: "rgba(10, 14, 22, 0.5)",
                }}
              >
                Tiếng Việt
              </button>
            </motion.div>
          </form>

          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.7 }}
            className="mt-6 text-center"
          >
            <p className="text-xs text-mist-mid">
              {lt("Accounts are created by admins only. Please contact an administrator for access.")}
            </p>
          </motion.div>

          {/* Bottom decoration */}
          <div className="mt-8 flex items-center justify-center gap-3">
            <div className="w-8 h-px bg-ink-light" />
            <span className="text-[10px] text-mist-dark">天道酬勤</span>
            <div className="w-8 h-px bg-ink-light" />
          </div>
          <p className="text-center text-[10px] text-mist-dark mt-1">
            {lt("Heaven rewards the diligent")}
          </p>
        </div>
      </motion.div>
    </div>
  );
}

