  const timeZone = settings.timeZone;
  const isAdmin = user?.role === "admin";

  const isActive = pathname === DASHBOARD_ROUTES.circle || pathname?.startsWith(`${DASHBOARD_ROUTES.circle}/`);
  const [drawerFriendId, setDrawerFriendId] = useState("");
