    const frame = window.requestAnimationFrame(() => {
      friendExerciseSearchInputRef.current?.focus();
      friendExerciseSearchInputRef.current?.select();
    });
    return () => window.cancelAnimationFrame(frame);
  }, [friendExerciseSearchOpen]);

  useEffect(() => {
