    void loadFriendHistory();

    return () => {
      cancelled = true;
    };
  }, [activeFriend?.id, friendViewMode]);

  useEffect(() => {
    if (!activeFriend?.id) {
      setFriendOverviewStats({
        latestWeight: null,
        todayCheckedIn: false,
