                    <select value={r1} onChange={(e) => { setR1(e.target.value); if (shakeError) setShakeError(false); }}
                      className={`w-full rounded-md px-1 py-1.5 text-center text-xs outline-none transition-colors duration-200 bg-ink-dark border border-ink-light/30 text-cloud-white focus:border-gold/50 focus:bg-ink-mid/40${shakeError ? ' animate-shake' : ''}`}
                      style={{ borderColor: shakeError ? 'var(--state-error-border)' : 'color-mix(in srgb, var(--gold) 15%, transparent)' }}>
                      <option value=""></option>
                      {repOptions.map((rep) => (
                        <option key={`compact-hold-r1-${rep}`} value={rep}>{rep}</option>
                      ))}
                    </select>
                    <input type="number" min="0" value={hold2} onChange={(e) => setHold2(e.target.value)} placeholder="s"
                      className="w-full rounded-md px-1 py-1.5 text-center text-xs outline-none transition-all duration-200 bg-ink-dark border border-mountain-blue/20 text-cloud-white placeholder:text-mist-dark/30 focus:border-mountain-blue-glow/50 focus:bg-ink-mid/40" />
                    <select value={r2} onChange={(e) => setR2(e.target.value)}
                      className="w-full rounded-md px-1 py-1.5 text-center text-xs outline-none transition-all duration-200 bg-ink-dark border border-ink-light/30 text-cloud-white focus:border-gold/50 focus:bg-ink-mid/40"
                      style={{ borderColor: 'color-mix(in srgb, var(--gold) 15%, transparent)' }}>
                      <option value=""></option>
                      {repOptions.map((rep) => (
                        <option key={`compact-hold-r2-${rep}`} value={rep}>{rep}</option>
                      ))}
                    </select>
                    <input type="number" min="0" value={hold3} onChange={(e) => setHold3(e.target.value)} placeholder="s"
                      className="w-full rounded-md px-1 py-1.5 text-center text-xs outline-none transition-all duration-200 bg-ink-dark border border-mountain-blue/20 text-cloud-white placeholder:text-mist-dark/30 focus:border-mountain-blue-glow/50 focus:bg-ink-mid/40" />
                    <select value={r3} onChange={(e) => setR3(e.target.value)}
                      className="w-full rounded-md px-1 py-1.5 text-center text-xs outline-none transition-all duration-200 bg-ink-dark border border-ink-light/30 text-cloud-white focus:border-gold/50 focus:bg-ink-mid/40"
                      style={{ borderColor: 'color-mix(in srgb, var(--gold) 15%, transparent)' }}>
                      <option value=""></option>
                      {repOptions.map((rep) => (
                        <option key={`compact-hold-r3-${rep}`} value={rep}>{rep}</option>
                      ))}
                    </select>
                  </>
                )}
                <input type="text" value={notes} onChange={(e) => setNotes(e.target.value)} placeholder={shortNotesPlaceholder}
                  className="w-full rounded-md px-1.5 py-1.5 text-xs outline-none transition-all duration-200 bg-ink-dark border border-ink-light/20 text-cloud-white placeholder:text-mist-dark/40 focus:border-mist-mid/30 focus:bg-ink-mid/30" />
              </div>
            </div>

            <div className="mt-3 flex items-center justify-end gap-2 pl-2">
              {saved && (
                <motion.span
                  initial={{ opacity: 0, x: 10 }}
                  animate={{ opacity: 1, x: 0 }}
                  className="text-xs font-medium"
                  style={{ color: diffStyle.glowColor }}
                >
                  ✦ Saved
                </motion.span>
              )}
              {showHold && (
                <button
                  type="button"
                  onClick={() => { setShowTimerModal(true); setTimerTarget(getNextTimerTarget()); setTimerReps(""); resetTimer(); }}
                  className="px-3 py-1.5 text-[10px] font-bold rounded-md border text-cloud-white bg-mountain-blue/35 hover:bg-mountain-blue/45 border-mountain-blue-glow/70 shadow-[var(--glow-blue)] hover:shadow-[var(--glow-blue)] transition-all"
                  style={{ boxShadow: `0 0 10px ${diffStyle.glowColor}66, inset 0 0 0 1px ${diffStyle.glowColor}40` }}
                  title="Open compact hold timer"
                >
                  Start Timer
                </button>
              )}
              <motion.button
                onClick={handleSubmit}
                disabled={submitting}
                animate={saved ? { scale: [1, 1.1, 1] } : { scale: 1 }}
                whileHover={!submitting ? { scale: 1.06, boxShadow: `0 0 10px ${diffStyle.glowColor}50` } : {}}
                whileTap={!submitting ? { scale: 0.96 } : {}}
                transition={{ duration: 0.3 }}
                className="px-4 py-1.5 rounded-md text-xs font-bold uppercase tracking-[0.08em] border disabled:opacity-40 cursor-pointer"
                style={{
                  background: saved
                    ? `linear-gradient(180deg, color-mix(in srgb, ${diffStyle.glowColor} 42%, var(--ink-mid)) 0%, color-mix(in srgb, ${diffStyle.glowColor} 30%, var(--ink-dark)) 100%)`
                    : `linear-gradient(180deg, color-mix(in srgb, ${diffStyle.glowColor} 32%, var(--ink-mid)) 0%, color-mix(in srgb, ${diffStyle.glowColor} 20%, var(--ink-dark)) 100%)`,
                  borderColor: saved ? `${diffStyle.glowColor}88` : `${diffStyle.glowColor}66`,
                  boxShadow: saved
                    ? `0 0 18px ${diffStyle.glowColor}66, inset 0 1px 0 color-mix(in srgb, var(--cloud-white) 20%, transparent)`
                    : `0 8px 18px color-mix(in srgb, ${diffStyle.glowColor} 26%, transparent), inset 0 1px 0 color-mix(in srgb, var(--cloud-white) 14%, transparent)`,
                  color: "var(--cloud-white)",
                  textShadow: "0 1px 0 rgba(0,0,0,.35)",
                  transition: 'background 0.3s, border-color 0.3s, box-shadow 0.3s',
                }}
              >
                {submitting ? "Saving…" : saved ? "✦ Logged!" : "Log Set"}
              </motion.button>
            </div>
          </>
        )}

        {showTimerModal && showHold && (
          <div className="absolute inset-0 z-30 flex items-end sm:items-center justify-center bg-black/75 p-2" onClick={closeTimerModal}>
            <div
              className="w-full max-w-[300px] rounded-lg border bg-ink-deep/95 p-3"
              style={{
                borderColor: `${diffStyle.glowColor}80`,
                boxShadow: `0 0 20px ${diffStyle.glowColor}40, var(--shadow-elev-2), inset 0 0 0 1px ${diffStyle.glowColor}20`,
              }}
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-center justify-between mb-2">
                <p className="text-[11px] font-bold uppercase tracking-wider" style={{ color: diffStyle.glowColor }}>Hold Timer</p>
                <button
                  type="button"
                  onClick={closeTimerModal}
                  className="text-mist-dark hover:text-mist-light text-xs px-1"
                  title="Close timer"
                >
                  ✕
                </button>
              </div>

              <div className="flex rounded-md border overflow-hidden mb-2" style={{ borderColor: `${diffStyle.glowColor}55` }}>
                {([
                  { key: "hold", label: "T1", rep: "R1" },
                  { key: "hold2", label: "T2", rep: "R2" },
                  { key: "hold3", label: "T3", rep: "R3" },
                ] as const).map((slot, idx) => (
                  <button
                    key={slot.key}
                    type="button"
                    onClick={() => setTimerTarget(slot.key)}
                    className={`flex-1 py-1 text-[10px] font-semibold text-center ${idx > 0 ? "border-l border-ink-light/30" : ""}`}
                    style={slot.key === timerTarget ? {
                      background: `${diffStyle.glowColor}2e`,
                      color: diffStyle.glowColor,
                    } : { color: "var(--mist-dark)" }}
                  >
                    <div>{slot.label}</div>
                    <div className="text-[9px] opacity-80">
                      {slot.key === "hold"
                        ? `${hold || "-"}s${r1 ? ` • ${r1}r` : ""}`
                        : slot.key === "hold2"
                          ? `${hold2 || "-"}s${r2 ? ` • ${r2}r` : ""}`
                          : `${hold3 || "-"}s${r3 ? ` • ${r3}r` : ""}`}
                    </div>
                  </button>
                ))}
              </div>

              <div className="mb-2">
                <span className="block text-center sm:text-left text-[12px] font-mono font-semibold mb-2" style={{ color: diffStyle.glowColor }}>{timerMinutes}:{timerSeconds}.{timerMillis}</span>
              </div>

              <div className="mb-3">
                <label className="text-[10px] text-mist-dark block mb-1">
                  Reps for {timerTarget === "hold" ? "R1" : timerTarget === "hold2" ? "R2" : "R3"} (optional)
                </label>
                <input
                  type="number"
                  min="0"
                  max="500"
                  value={timerReps}
                  onChange={(e) => setTimerReps(e.target.value)}
                  placeholder="—"
                  className="w-full rounded border border-ink-light/30 bg-ink-dark px-2 py-1 text-xs text-gold outline-none focus:border-gold/50"
                />
              </div>

              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={resetTimer}
                  className="flex-1 py-1 rounded border border-ink-light/30 text-[10px] text-mist-dark hover:text-mist-light"
                >
                  Reset
                </button>
                <button
                  type="button"
                  onClick={handleTimerButton}
                  className={`flex-1 py-1 rounded border text-[10px] font-semibold transition-all ${timerRunning ? "text-crimson-light border-crimson/50 bg-crimson-deep/20 shadow-[var(--glow-crimson)]" : ""}`}
                  style={!timerRunning ? {
                    borderColor: `${diffStyle.glowColor}88`,
                    background: `${diffStyle.glowColor}26`,
                    color: diffStyle.glowColor,
                  } : undefined}
                >
                  {timerRunning ? "Stop Timer" : "Start Timer"}
                </button>
              </div>
            </div>
          </div>
        )}

        {isMobile && mobilePicker && typeof document !== "undefined" && createPortal(
          <AnimatePresence>
            <>
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="fixed inset-0 z-[95] bg-black/70"
                onClick={() => setMobilePicker(null)}
              />
              <motion.div
                initial={{ opacity: 0, y: 24 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: 24 }}
                className="fixed left-1/2 bottom-0 z-[96] max-h-[72vh] w-[min(82vw,32rem)] -translate-x-1/2 overflow-hidden rounded-none border safe-area-top safe-area-bottom"
                style={{ borderColor: "var(--border)", backgroundColor: "var(--surface)", boxShadow: "var(--shadow-elev-2)" }}
                onClick={(event) => event.stopPropagation()}
              >
                <div className="flex items-center justify-between border-b px-4 py-3" style={{ borderColor: "var(--border)" }}>
                  <p className="text-xs font-semibold uppercase tracking-[0.08em]" style={{ color: "var(--text-primary)" }}>
                    {mobilePicker.title}
                  </p>
                  <button
                    type="button"
                    onClick={() => setMobilePicker(null)}
                    className="rounded border px-2.5 py-1 text-[11px]"
                    style={{ borderColor: "var(--border)", color: "var(--text-secondary)", backgroundColor: "var(--surface-hover)" }}
                  >
                    Close
                  </button>
                </div>
                <div className="max-h-[calc(72vh-52px)] overflow-y-auto p-2">
                  {mobilePickerOptions.map((option, index) => {
                    const isActive = option.value === mobilePickerCurrentValue;
                    return (
                      <button
                        key={`${mobilePicker.field}-${option.value || "empty"}-${index}`}
                        type="button"
                        onClick={() => {
                          applyMobilePickerValue(mobilePicker.field, option.value);
                          setMobilePicker(null);
                        }}
                        className="mb-1.5 flex w-full items-center justify-between rounded-lg border px-3 py-2.5 text-left text-sm"
                        style={{
                          borderColor: isActive ? "var(--accent)" : "var(--border)",
                          backgroundColor: isActive
                            ? "color-mix(in srgb, var(--accent) 16%, var(--surface))"
                            : "var(--surface)",
                          color: isActive ? "var(--text-primary)" : "var(--text-secondary)",
                        }}
                      >
                        <span className="truncate">{option.label}</span>
                        <span className="ml-3 text-xs" style={{ color: isActive ? "var(--accent)" : "transparent" }}>●</span>
                      </button>
                    );
                  })}
                </div>
              </motion.div>
            </>
          </AnimatePresence>,
          document.body,
        )}
      </div>
    </motion.div>
  );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import type { ProgressionExercise } from "@/app/dashboard/workout/types";
import {
  parseCategoryTags,
  getEquipmentTags,
  isGymCategoryExercise,
  getWeightedDifficulty,
} from "@/app/dashboard/workout/utils";
import { EquipmentBadges } from "@/components/workout/EquipmentBadges";
import { useDisplaySettings, DISPLAY_DEFAULTS } from "@/context/DisplaySettingsContext";
import { useIsMobile } from "@/context/AppContext";
import { useDebouncedValue } from "@/hooks/useDebouncedValue";
import GlowButton from "@/components/ui/GlowButton";
import ExerciseImageBox from "@/components/exercise/ExerciseImageBox";
import { getTypeColor, DAY_ABBREVIATIONS, parseDayAssignments } from "@/lib/constants";
import { getExerciseDisplayName, matchesLooseSearchInFields, getTypeDisplayName, getTypeColorKey } from "@/lib/exercise-name";

export function TrainingGroundsSidebar({
  exercises,
  selectedIds,
  onToggleExercise,
  onAddExercise,
  onSelectWithLevel,
  selectedTierIds,
  searchTerm,
  onSearch,
  filterCategory,
  setFilterCategory,
  filterType,
  setFilterType,
  filterEquipment,
  setFilterEquipment,
  categories,
  types,
  equipmentTypes,
  levelDefaults,
  autoLevelByExerciseId,
  selectedDayFilter,
  setSelectedDayFilter,
  onDrawerOpen,
  userBodyweightKg,
}: {
  exercises: ProgressionExercise[];
  selectedIds: Set<string>;
  onToggleExercise: (id: string) => void;
  onAddExercise: (id: string) => void;
  onSelectWithLevel: (exerciseId: string, level: number, tierId?: string) => void;
  selectedTierIds: Record<string, string>;
  searchTerm: string;
  onSearch: (term: string) => void;
  filterCategory: string;
  setFilterCategory: (v: string) => void;
  filterType: string;
  setFilterType: (v: string) => void;
  filterEquipment: string;
  setFilterEquipment: (v: string) => void;
  categories: string[];
  types: string[];
  equipmentTypes: string[];
  levelDefaults: Record<string, number>;
  autoLevelByExerciseId: Record<string, number>;
  selectedDayFilter: number | null;
  setSelectedDayFilter: (v: number | null) => void;
  onDrawerOpen: () => void;
  userBodyweightKg: number | null;
}) {
  const isMobile = useIsMobile();
  const { settings } = useDisplaySettings();
  const [isCompact, setIsCompact] = useState(() => {
    if (typeof window === "undefined") return false;
    try {
      const saved = localStorage.getItem("cultivateos-progression-sidebar-compact");
      return saved === null ? true : saved === "true";
    } catch {
      return true;
    }
  });

  useEffect(() => {
    try { localStorage.setItem("cultivateos-progression-sidebar-compact", String(isCompact)); } catch {}
  }, [isCompact]);

  const [sortMode, setSortMode] = useState<string>(() => {
    if (typeof window === "undefined") return "a-z";
    try { return localStorage.getItem("cultivateos-progression-sidebar-sort") || "a-z"; } catch { return "a-z"; }
  });

  useEffect(() => {
    try { localStorage.setItem("cultivateos-progression-sidebar-sort", sortMode); } catch {}
  }, [sortMode]);

  const displayMode = DISPLAY_DEFAULTS.progressionSidebarMode;
  const cardStyle = DISPLAY_DEFAULTS.progressionSidebarStyle;
  const glowIntensity = DISPLAY_DEFAULTS.glowIntensityProgressionSidebar;
  const loreVisible = DISPLAY_DEFAULTS.progressionSidebarLoreVisible;

  const showIllumination = displayMode !== "name-only";
  const showRealm = displayMode === "name-illumination-realm" || displayMode === "name-illumination-realm-path";
  const showPath = displayMode === "name-illumination-realm-path";
  const isScrollStyle = cardStyle === "scroll-card";

  const dayCounts = useMemo(() => {
    const counts: number[] = [0, 0, 0, 0, 0, 0, 0];
    for (const ex of exercises) {
      const days = parseDayAssignments(ex.assignedDays || "");
      for (const d of days) {
        if (d >= 0 && d <= 6) counts[d]++;
      }
    }
    return counts;
  }, [exercises]);

  const [disciplineFilter, setDisciplineFilter] = useState<"all" | "gym" | "calisthenics" | "recent">("all");

  const debouncedSearchTerm = useDebouncedValue(searchTerm, 150);
  const searchQuery = debouncedSearchTerm.trim();
  const isSearchActive = searchQuery.length > 0;

  const exerciseDerived = useMemo(() => {
    const map = new Map<
      string,
      {
        categoryTags: string[];
        equipmentTags: string[];
        assignedDays: Set<number>;
        isGym: boolean;
        displayName: string;
        primaryCategory: string;
        logCount: number;
        latestLogTs: number;
        latestLogId: string;
        searchFields: string[];
        nameFields: string[];
      }
    >();

    for (const ex of exercises) {
      const categoryTags = parseCategoryTags(ex.category);
      const equipmentTags = getEquipmentTags(ex);
      const assignedDays = new Set(parseDayAssignments(ex.assignedDays || ""));
      const logs = ex.userProgress[0]?.logs ?? [];
      const latestLog = [...logs].sort((a, b) => {
        const timeDiff = new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
        if (timeDiff !== 0) return timeDiff;
        return b.id.localeCompare(a.id);
      })[0];
      const latestLogTs = latestLog ? new Date(latestLog.createdAt).getTime() : 0;
      const nameFields = [ex.name, ex.wuxiaName].filter(Boolean) as string[];
      const searchFields = [
        ex.name,
        ex.wuxiaName,
        ex.primaryMuscles,
        ex.secondaryMuscles,
        ex.category,
      ].filter(Boolean) as string[];

      map.set(ex.id, {
        categoryTags,
        equipmentTags,
        assignedDays,
        isGym: isGymCategoryExercise(ex),
        displayName: getExerciseDisplayName(ex, settings.terminologyMode, settings.showExerciseForeignLanguage),
        primaryCategory: categoryTags[0] || "Uncategorised",
        logCount: logs.length,
        latestLogTs,
        latestLogId: latestLog?.id ?? "",
        searchFields,
        nameFields,
      });
    }

    return map;
  }, [exercises, settings.showExerciseForeignLanguage, settings.terminologyMode]);

  const filtered = useMemo(
    () =>
      exercises.filter((e) => {
        const derived = exerciseDerived.get(e.id);
        if (!derived) return false;

        if (disciplineFilter === "gym" && !derived.isGym) return false;
        if (disciplineFilter === "calisthenics" && derived.isGym) return false;
        if (disciplineFilter === "recent" && derived.logCount === 0) return false;

        if (selectedDayFilter !== null) {
          if (!derived.assignedDays.has(selectedDayFilter)) return false;
        }
        if (filterCategory && !derived.categoryTags.includes(filterCategory)) return false;
        if (filterType && e.type !== filterType) return false;
        if (filterEquipment && !derived.equipmentTags.includes(filterEquipment)) return false;
        if (searchQuery) {
          return matchesLooseSearchInFields(searchQuery, derived.searchFields);
        }
        return true;
      }),
    [
      disciplineFilter,
      exerciseDerived,
      exercises,
      filterCategory,
      filterEquipment,
      filterType,
      searchQuery,
      selectedDayFilter,
    ]
  );

  const sorted = useMemo(
    () =>
      [...filtered].sort((a, b) => {
        const aDerived = exerciseDerived.get(a.id);
        const bDerived = exerciseDerived.get(b.id);
        const nameA = aDerived?.displayName ?? getExerciseDisplayName(a, settings.terminologyMode, settings.showExerciseForeignLanguage);
        const nameB = bDerived?.displayName ?? getExerciseDisplayName(b, settings.terminologyMode, settings.showExerciseForeignLanguage);

        switch (sortMode) {
          case "a-z":
            return nameA.localeCompare(nameB);
          case "z-a":
            return nameB.localeCompare(nameA);
          case "recent": {
            const timeDiff = (bDerived?.latestLogTs ?? 0) - (aDerived?.latestLogTs ?? 0);
            if (timeDiff !== 0) return timeDiff;
            return (bDerived?.latestLogId ?? "").localeCompare(aDerived?.latestLogId ?? "");
          }
          case "most-logged":
            return (bDerived?.logCount ?? 0) - (aDerived?.logCount ?? 0);
          case "selected": {
            const aS = selectedIds.has(a.id) ? 0 : 1;
            const bS = selectedIds.has(b.id) ? 0 : 1;
            if (aS !== bS) return aS - bS;
            return nameA.localeCompare(nameB);
          }
          default:
            return 0;
        }
      }),
    [exerciseDerived, filtered, selectedIds, settings.showExerciseForeignLanguage, settings.terminologyMode, sortMode]
  );

  const [showFilters, setShowFilters] = useState(false);

  const activeFiltersCount = (filterCategory ? 1 : 0) + (filterType ? 1 : 0) + (filterEquipment ? 1 : 0);

  const searchGroupedByCategory = useMemo(() => {
    if (!isSearchActive) return null;
    const groups: { category: string; exercises: typeof sorted }[] = [];
    const categoryMap = new Map<string, typeof sorted>();
    for (const ex of sorted) {
      const categoryKey = exerciseDerived.get(ex.id)?.primaryCategory || "Uncategorised";
      if (!categoryMap.has(categoryKey)) categoryMap.set(categoryKey, []);
      categoryMap.get(categoryKey)!.push(ex);
    }
    for (const [category, exercises] of categoryMap) {
      groups.push({ category, exercises });
    }
    return groups;
  }, [exerciseDerived, isSearchActive, sorted]);

  const searchGroupCountByCategory = useMemo(() => {
    if (!searchGroupedByCategory) return new Map<string, number>();
    return new Map(searchGroupedByCategory.map((group) => [group.category, group.exercises.length]));
  }, [searchGroupedByCategory]);

  const searchNameMatchById = useMemo(() => {
    if (!isSearchActive) return new Map<string, boolean>();
    const map = new Map<string, boolean>();
    for (const exercise of sorted) {
      const derived = exerciseDerived.get(exercise.id);
      map.set(
        exercise.id,
        matchesLooseSearchInFields(searchQuery, derived?.nameFields ?? [exercise.name, exercise.wuxiaName].filter(Boolean) as string[])
      );
    }
    return map;
  }, [exerciseDerived, isSearchActive, searchQuery, sorted]);

  const sortOptions = [
    { key: "a-z", label: "A–Z", icon: "↕" },
    { key: "z-a", label: "Z–A", icon: "↕" },
    { key: "recent", label: "Recent", icon: "◷" },
    { key: "most-logged", label: "Most Logged", icon: "▤" },
    { key: "selected", label: "Selected", icon: "✦" },
  ] as const;

  const compactEnabled = !isMobile && isCompact;
  const chipTextClass = isMobile ? "text-xs" : "text-[10px]";
  const labelTextClass = isMobile ? "text-[10px]" : "text-[9px]";

  return (
    <div className="dashboard-sidebar-shell">
      {/* ── Primary Controls (MapleRanks-style simple flow) ── */}
      <div className="px-2 py-2 shrink-0 space-y-2">
        <div className="flex items-center justify-between gap-2">
          <h3 className="text-[10px] font-medium uppercase tracking-[0.08em] text-mist-dark">Exercise Library</h3>
          <div className="flex items-center gap-1">
            {selectedDayFilter !== null && (
              <GlowButton
                onClick={(e) => { e.stopPropagation(); onDrawerOpen(); }}
                variant="jade"
                size="sm"
                glow
                className={`${isMobile ? "!py-2 !text-xs" : "!py-1 !text-[10px]"} shrink-0`}
              >
                Manage
              </GlowButton>
            )}
            <button
              onClick={() => setShowFilters(!showFilters)}
              className={`${isMobile ? "h-9 px-2.5 text-xs" : "h-7 px-2 text-[10px]"} rounded-md border font-medium transition-all duration-150 ${
                showFilters
                  ? "bg-ink-mid/25 border-ink-light/55 text-mist-light"
                  : "border-ink-light/40 text-mist-dark hover:text-mist-light hover:border-ink-light/60"
              }`}
              title={showFilters ? "Hide advanced controls" : "Show advanced controls"}
            >
              {showFilters ? "Basic" : "Advanced"}
            </button>
          </div>
        </div>

        <div className="relative">
          <input
            type="text"
            placeholder=""
            value={searchTerm}
            onChange={(e) => onSearch(e.target.value)}
