          exercise: row.exercise,
          displayLabel: contextual,
          searchLabel: contextual,
          canonicalName: row.canonicalName,
          hasHistory: row.hasHistory,
          lastLoggedAt: row.lastLoggedAt,
          matchSource: "progression",
