    const itemHeight = 44;
    const viewportHeight = 224;
    const sidePadding = (viewportHeight - itemHeight) / 2;
    const targetValue = mobileInputPicker.field === "modifierKg" ? "0" : mobileInputPickerCurrentValue;
    const selectedIndex = Math.max(
