    applyScrollPosition();
    const rafId = window.requestAnimationFrame(applyScrollPosition);
    const timeoutId = window.setTimeout(applyScrollPosition, 120);

    return () => {
      window.cancelAnimationFrame(rafId);
      window.clearTimeout(timeoutId);
