    if (!response.ok) {
      throw new Error("Failed to fetch exercise history page");
    }
    const data = (await response.json()) as ExerciseHistoryResponse;
    const payload = data.data ?? data;
    return {
      history: Array.isArray(payload.history) ? payload.history : [],
