                          const avgWeightTitle = [weightBreakdown || "No weight recorded", modifierText !== noModifierLabel ? `Mod: ${modifierText}` : null]
                            .filter(Boolean)
                            .join(" | ");
                          const avgRepsTitle = [repsBreakdown || "No reps recorded", modifierText !== noModifierLabel ? `Mod: ${modifierText}` : null]
                            .filter(Boolean)
                            .join(" | ");

                          return (
                            <tr key={entry.id} className="border-b" style={{ borderColor: "color-mix(in srgb, var(--border) 55%, transparent)" }}>
                              <td className="px-2 py-1 text-center whitespace-nowrap" style={{ color: "var(--text-secondary)" }}>
