function mockCtx(pathname: string): MiddlewareContext {
  const url = new URL(pathname, "http://localhost:3000");
  return {
    request: {
      nextUrl: {
        pathname,
        clone() {
          return new URL(pathname, "http://localhost:3000");
        },
      },
      url: url.toString(),
